window.__D("text/zohar/c039",{"p":[[9520012655,"<p>פָּתַח רִבִּי אַבָּא וְאָמַר, (תהילים קכ״ג:א׳) שִׁיר הַמַּעֲלוֹת אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמַיִם. שִׁיר דָּא, לָא כְּתִיב מַאן אָמָרוֹ. אֶלָּא בְּכָל אֲתָר דְּאִיהוּ סָתִים, רוּחַ הַקֹּדֶשׁ אַמָרוֹ עָלַיְיהוּ דְּיִשְׂרָאֵל בְּגָלוּתָא. הַיּוֹשְׁבִי בַּשָּׁמַיִם, הַיּוֹשֵׁב מִבָּעֵי לֵיהּ, מַאי הַיּוֹשְׁבִי.</p>\n<p>אֶלָּא אוֹקִימְנָא, מַאן דְּבָעֵי לְצַלָּאָה צְלוֹתֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא, בָּעֵי לְמִבָּעֵי מֵעֲמִיקְתָא דְּכֹלָּא, לְאַרְקָא בִּרְכָאן לְתַתָּא, כְּמָה דִּכְתִּיב, (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. וְהַאי יוֹ\"ד יַתִּיר, עֲמִיקְתָא דְּכֹלָּא הִיא, וּבְהַאי בָּעֵי לְמִבָּעֵי בָּעוּתֵיהּ, לְאַרְקָא בִּרְכָאן לְהַהוּא אֲתָר דְּאִקְרֵי שָׁמַיִם, לְאַתְּזְנָא מִנֵּיהּ כֹּלָּא, וְעַל דָּא הַיּוֹשְׁבִי בַּשָּׁמַיִם, בַּשָּׁמַיִם מַמָּשׁ, דְּכַד אִינּוּן בִּרְכָאן נְגִידוּ וְאִתְמְשָׁכוּ מֵהַהוּא אֲתָר עוּמְקָא דְּכֹלָּא, וְאִתְיַשְּׁבָן בַּאֲתָר דְּאִקְרֵי שָׁמַיִם, כְּדֵין בִּרְכָאן מִשְׁתַּכְּחֵי בְּעִלָּאֵי וְתַתָּאֵי.</p>\n<p>כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם, מַאי כְעֵינֵי עֲבָדִים. אִלֵּין אִינּוּן שְׁאַר רַבְרְבֵי עַמִּין, דְּלָא אִתְּזָנוּ אֶלָּא מִשִּׁיּוּרַא (משיורי) (ס\"א גופא) נוֹפָא דְּאִילָנָא, דְּיִשְׂרָאֵל מִתְדַּבְּקֵי בֵּיהּ. וְכַד יִשְׂרָאֵל נַטְלִין בִּרְכָאן מֵהַהוּא אֲתָר, כֻּלְּהוּ מִתְבָּרְכָן מִיִּשְׂרָאֵל.</p>\n<p>כְעֵינֵי שִׁפְחָה אֶל יַד גְּבִירְתָּהּ, דָּא הִיא שִׁפְחָה דְּאוֹקִימְנָא, דְּקָטִיל קוּדְשָׁא בְּרִיךְ הוּא חֵילָא דִּילָהּ בְּמִצְרַיִם, דְּהָא לֵית חֵילָא דִּידָהּ, אֶלָּא כַּד אִתְנְגִיד מִתַּמְצִית דְּהַאי אֶרֶץ יִשְׂרָאֵל. וְאֶרֶץ יִשְׂרָאֵל <Nonei></i> גְּבִרְתָּהּ אִקְרֵי. וְעַל הַאי כְּתִיב, (משלי ל׳:כ״א) תַּחַת שָׁלֹשׁ רָגְזָה אֶרֶץ. מַאן אֶרֶץ. דָּא אֶרֶץ יִשְׂרָאֵל, כְּמָה דְּאִתְּמַר. תַּחַת עֶבֶד כִּי יִמְלוֹךְ, אִלֵּין אִינּוּן עֲבָדִים דְּקָאַמְרָן. כַּד אִתְיְהִיב שֻׁלְטָנוּתָא לְחַד מִנַּיְיהוּ. וְדָא הוּא דִּכְתִּיב, אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם מִבֵּית עֲבָדִים. שִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ (ס\"א מאי היא) דָּא הִיא שִׁפְחָה דְּקָאַמְרָן.</p>\n<p>תָּא חֲזֵי, מִסִּטְרָא דְּהַאי שִׁפְחָה, נַפְקֵי כַּמָה גַּרְדִּינֵי טְהִירִין, מְקַטְרְגִין לָקֳּבְלַיְיהוּ דְּיִשְׂרָאֵל, וּלְקַטְרְגָא לוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְהוּ לְיִשְׂרָאֵל נְטִירוּ, כְּאַבָּא דְּבָעֵי לְנַטְרָא לִבְרֵיהּ מִן כֹּלָּא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, כַּמָה מְקַטְרְגִין זְמִינִין לָקֳבְלַיְיכוּ, אִשְׁתְּדָלוּ בְּפוּלְחָנִי, וַאֲנָא אֱהֵא נָטִיר לְכוּ לְבַר. וְאַתּוּן תֶּהֱווֹן זְמִינִין בְּבָתֵּיכוֹן מִלְּגוֹ, וְנַיְימֵי בְּעַרְסֵיכוֹן, וַאֲנָא אֱהֵא נָטִיר לְכוּ לְבַר, וְסוֹחֲרָנֵי עַרְסַיְיכוּ.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּאִינּוּן זִינִין בִּישִׁין קְרִיבִין לְפִתְחָא דְּבַּר נָשׁ זַקְפָן רֵישָׁא, וּמִסְתַּכְּלָן בִּשְׁמָא קַדִּישָׁא דְּאִתְחָזֵי לְבַר, דְּאִיהוּ שַׁדַּי, דְּמִתְעַטָּר בְּעִטְרוֹי, שְׁמָא דָּא שַׁלִּיט עַל כֻּלְּהוּ, מִנֵּיהּ דַּחֲלִין וְעַרְקִין, וְלָא קְרָבִין לְפִתְחָא דְּבַּר נָשׁ.</p>\n<p>אָמַר לֵיהּ רִבִּי יִצְחָק, אִי הָכִי, יִרְשׁוֹם בַּר נָשׁ שְׁמָא דָּא בְּפִתְחָא דְּבֵיתָא, וְלָא יַתִּיר, אֲמַאי כָּל פַּרְשְׁתָּא. אָמַר לֵיהּ שַׁפִּיר הוּא, דְּהָא שְׁמָא דָּא לָא אִתְעֲטָּר, אֶלָּא בְּאִינּוּן אַתְוָון כֻּלְּהוּ, רְשִׁימִין בִּרְשִׁימָא דְּמַלְכָּא, וְכַד אַכְתָּב כָּל פַּרְשְׁתָּא, כְּדֵין שְׁמָא דָּא מִתְעֲטָּר בְּעִטְרוֹי וְנָפִיק מַלְכָּא בְּכָל חֵילוֹי, כֻּלְּהוּ רְשִׁימִין בִּרְשִׁימָא דְּמַלְכָּא, כְּדֵין דַּחֲלִין מִנֵּיהּ, וְעַרְקִין מִקַּמֵּיהּ.</p>\n<p>תָּא חֲזֵי, וְהָיָה שְׁמָא קַדִּישָׁא, מִתַּתָּא לְעֵילָּא. וְעַל דָּא, שַׁדַּי אִתְרְשִׁים מִלְבַר, לָקֳבְלֵי שְׁמָא דָּא. וְהָיָ\"ה מִלְּגַו, שַׁדָּ\"י מִלְבַר. לְמֶהֱוֵי נָטִיר בַּר נָשׁ מִכָּל סִטְרִין מִלְּגַאו וּמִלְּבַר. אָמַר רִבִּי אַבָּא, כַּמָה חַיָּילִין קַדִּישִׁין זְמִינִין בְּהַהִיא שַׁעֲתָא דְּאָנַח בַּר נָשׁ מְזוּזָה לְתַרְעֵיהּ, כֻּלְּהוּ מַכְרְזֵי וְאַמְרֵי (תהלים קיח) זֶה הַשַּׁעַר לַיְיָ' וְגוֹ'.</p>\n<p>זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, כְּדֵין אִשְׁתְּמוֹדְעָן יִשְׂרָאֵל דְּאִינּוּן בְּנֵי מַלְכָּא קַדִּישָׁא, דְּהָא כֻּלְּהוּ אִתְרְשִׁימוּ מִנֵּיהּ. אִתְרְשִׁימוּ בְּגוּפַיְיהוּ, בִּרְשִׁימָא קַדִּישָׁא. אִתְרְשִׁימוּ בִּלְבוּשַׁיְיהוּ, בְּעִטּוּפַיְיהוּ דְּמִצְוָה. אִתְרְשִׁימוּ בְּרֵישַׁיְיהוּ, בְּבָתֵּי דִּתְפִילֵי, בִּשְׁמָא דְּמָארֵיהוֹן. אִתְרְשִׁימוּ בִּידַיְיהוּ, בִּרְצוּעֵי דִּקְדוּשָּׁא. אִתְרְשִׁימוּ בִּמְסָאנַיְיהוּ, בִּמְסָאנָא דְּמִצְוָה. אִתְרְשִׁימוּ לְבַר, בִּזְרִיעָה בְּחַצְדָּא. אִתְרְשִׁימוּ בְּבָתֵּיהוֹן, בִּמְּזוּזָה דְּפִתְחָא. בְּכֹלָּא רְשִׁימִין דְּאִינּוּן בְּנֵי מַלְכָּא עִלָּאָה, זַכָּאָה חוּלָקֵיהוֹן.</p>"],[9520012656,"<p>עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב, (ירמיהו ב׳:י״ג) אוֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים לַחְצוֹב לָהֶם בֹּארוֹת וְגוֹ'. אוֹתִי עָזְבוּ, דָּא הוּא מַאן דִּמְשַׁקֵּר בְּאָת רְשִׁימָא קַדִּישָׁא. וּבְמָּה מְשַׁקֵּר בֵּיהּ. דְּעָיִיל לֵיהּ בִּרְשׁוּתָא אַחֲרָא, כְּמָה דְאַתְּ אָמֵר (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר, דְּאִקְרֵי (ירמיהו ב׳:י״ג) בּוֹרוֹת נִשְׁבָּרִים. דְּהָא עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִקְרוּ בּוֹרוֹת נִשְׁבָּרִים.</p>\n<p>וּדְיִשְׂרָאֵל, אִקְרֵי בְּאֵר מְקוֹר מַיִם חַיִּים, דָּא רְשׁוּתָא קַדִּישָׁא, מְהֵימְנוּתָא קַדִּישָׁא. וְאִקְרֵי בְּאֵר מַבּוּעֵי דְּמַיִין צְלִילָן, נָפְקִין וְנַזְלִין מִנָהּ, כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:ט״ו) וְנוֹזְלִים מִן לְבָנוֹן. (משלי ה׳:ט״ו) וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךָ. וּכְתִיב (שיר השירים ד׳:ט״ו) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים. סִטְרָא אַחֲרָא אִקְרֵי בּוֹרוֹת נִשְׁבָּרִים. אֲשֶׁר לֹא יָכִילוּ הַמָּיִם. (ס\"א מהו, אלא ההוא וכו').</p>\n<p>תָּא חֲזֵי, נַהֲרָא דְּנָגִיד וְנָפִיק, אַשְׁקֵי לְכָל גִּינְתָּא, (ס\"א ורוי לכל גינתא) וְרַוֵּי לְכָל אֲתָר וַאֲתָר, כְּמָה דְּאוֹקִימְנָא, עַד דְּמָלֵּי (נ\"א דמטי) לְהַהוּא אֲתָר בְּגִנְתָּא, דְּאִקְרֵי בְּאֵר מַיִם חַיִּים. וּמִתַּמָּן אִתְּזָנוּ עִלָּאִין וְתַתָּאִין, (נ\"א עלמין תתאין) כְּמָה דְאַתְּ אָמֵר (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד.</p>\n<p>וְכָל אִינּוּן סִטְרִין דִּסְטָר שְׂמָאלָא, לָא מִשְׁתַּקְיָין מֵהַהוּא נְבִיעוּ דְּמַיִין נְבִיעִין, בְּגִין דְּאִינּוּן מִסִּטְרָא דִּשְׁאַר עַמִּין, וְאִקְרוּ בּוֹרוֹת נִשְׁבָּרִים. וּמַאן דִּמְשַׁקֵּר בִּשְׁמָא (נ\"א ברשימא) קַדִּישָׁא בְּהַהוּא סִטְרָא, אִתְדְּבַק בְּבוֹרוֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִילוּ הַמָּיִם, וְלָא עַיְילֵי לְתַמָּן. וְהַהוּא דְּזָכֵי לְנַטְרָא לֵיהּ, זָכֵי לְאִתְשַׁקְיָיא מֵהַהוּא נְבִיעוּ דְּנַחֲלָא (בעלמא דין) בְּעָלְמָא דְּאָתֵי, וְזָכֵי דְּאִתְמְלֵּי הַהוּא בְּאֵר עִלָּאָה, לְנַגְדָּא בִּרְכָאן לְעֵילָּא וְתַתָּא. זַכָּאָה אִיהוּ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עַל דָּא כְּתִיב, (ישעיהו נ״ח:י״א) וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו.</p>\n<p>וַוי לְמַאן דִּמְשַׁקֵּר בִּרְשִׁימָא קַדִּישָׁא, דְּהָא מְשַׁקֵּר <Nonei></i> בִּשְׁמָא עִלָּאָה. וְלֹא עוֹד, אֶלָּא דְּגָרִים לְהַאי בְּאֵר דְּלָא אִתְבָּרְכָא, וְקָרֵינָן עָלֵיהּ (דברים כ״ב:י״ט) כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. בְּתוּלַת יִשְׂרָאֵל דַּיְיקָא. וְאוֹקְמֵיהּ רִבִּי שִׁמְעוֹן בְּאַתְרֵיהּ, מַאן דְּשַׁוֵּי תִּסְקוֹפֵי מִלִּין עַל אִנְתְּתֵיהּ קַדְמִיתָא, וְאַפִּיק עֲלָהּ שׁוּם בִּישׁ, כְּמָה דְּאַפִּיק לְעֵילָּא, דִּכְתִּיב כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל סְתָם.</p>\n<p>וְאַזְלָא הָא, כִּי הָא דְּאָמַר רִבִּי חִיָּיא אָמַר רִבִּי יוֹסִי, בְּתוּלָה יָרְתָא שֶׁבַע בְּרָכוֹת, דְּאִתְבָּרְכָא בְּשֶׁבַע, בְּגִין דִּבְתּוּלַת יִשְׂרָאֵל יָרְתָא שֶׁבַע בִּרְכָן, וְעַל דָּא אִתְקְרֵי בַּת שֶׁבַע.</p>\n<p>וְאִנְתְּתָא אַחֲרָא, מַאן בִּרְכָאן דִּילָהּ. בִּרְכָתָא דְּבֹעַז וְרוּת, כְּמָה דְאַתְּ אָמֵר, (רות ד׳:י״א) וַיֹּאמְרוּ כָּל הָעָם אֲשֶׁר בַּשַּׁעַר וְהַזְּקֵנִים עֵדִים יִתֵּן יְיָ' אֶת וְגוֹ', דְּוַדַּאי בְּתוּלָה בְּז' אִתְבָּרְכָא, וְלָא אִתְּתָא אַחֲרָא בְּרָזָא דָּא. כֵּיוָן דְּמָטוּ בַּחֲקָל חַד, חָמוּ אִילָנִין, יָתְבוּ תְּחוֹתַיְיהוּ. אָמַר רִבִּי אַבָּא, הָא צָחוּתָא דְּמִלֵּי דְּאוֹרַיְיתָא. נְתִיב.</p>"],[9520012657,"<p>פָּתַח וְאָמַר, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְגוֹ'. וְהָיָה בְּיוֹם הַהוּא, מַאן בַּיּוֹם הַהוּא. אֶלָּא הַהוּא יוֹמָא דְּאִתְיְדַע לְקוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאַתְּ אָמֵר (זכריה י״ד:ד׳) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ'. תּוּ, בַּיוֹם הַהוּא, כְּמָה דְאַתְּ אָמֵר (יחזקאל ל״ח:י״ח) בְּיוֹם בֹּא גּוֹג עַל אַדְמַת יִשְׂרָאֵל.</p>\n<p>יִתָּקַע בְּשׁוֹפָר גָּדוֹל. מַה לָן בֵּיהּ, אִי הוּא רַב אוֹ זְעֵיר. אֶלָּא הַהוּא שׁוֹפָר עִלָּאָה, דְּבֵיהּ נָפְקִין עַבְדִּין לְחֵירוּ תָּדִיר, וְהַאי אִיהוּ יוֹבְלָא, דְּיוֹבְלָא עִלָּאָה וְרַבְרְבָא הוּא. וְכַד הַאי אִתְּעַר, כָּל חֵירוּ דְּעָלְמִין מִתְעָרִין בֵּיהּ, וְהַהוּא אִקְרֵי שׁוֹפָר גָּדוֹל.</p>\n<p>וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. הָאֲבוּדִים מִבָּעֵי לֵיהּ, אוֹ הַנֶּאֱבָדִים, מַאי הָאוֹבְדִים. הָאוֹבְדִים מַמָּשׁ, בְּגִין דְּאִינּוּן בְּאַרְעָא אַחֲרָא, וּמַאן דְּשָׁארִי בְּאַרְעָא אַחֲרָא, יָנִיק מֵרְשׁוּתָא אַחֲרָא וּכְאִלּוּ לָא שַׁרְיָא בִּמְהֵימְנוּתָא, בְּגִין כָּךְ אוֹבְדִים אִקְרוּן. אוֹבְדִים אִינּוּן בְּכָל סִטְרִין, דְּכַד יִשְׂרָאֵל שַׁרְיָין בְּאַרְעָא קַדִּישָׁא, זַכָּאִין, זַכָּאִין תָּדִיר בְּכֹלָּא, זַכָּאן לְעֵילָּא וְתַתָּא.</p>\n<p>דָּבָר אַחֵר וּבָאוּ הָאוֹבְדִים, מַאן אִינּוּן. אִלֵּין צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל. דְּאִקְרוּן אוֹבְדִים. מְנָלָן. כְּנֶסֶת יִשְׂרָאֵל, דִּכְתִּיב, (ירמיהו ט׳:י״א) עַל מַה אָבְדָה הָאָרֶץ, אֲבוּדָה אוֹ נֶאֱבֶדֶת לָא כְּתִיב, אֶלָּא אָבְדָה הָאָרֶץ, דָּא כְּנֶסֶת יִשְׂרָאֵל. צַדִּיק, דִּכְתִּיב, (ישעיהו נ״ז:א׳) הַצַּדִיק אָבָד, אָבוּד אוֹ נֶאֱבַד לָא כְּתִיב, אֶלָּא אָבָד, וְהָא אוֹקְמוּהָ.</p>\n<p>וְאִי תֵּימָא, וּבָאוּ, מֵאָן אֲתָר אַתְיָין אִלֵּין אוֹבְדִים. אֶלָּא, כְּנֶסֶת יִשְׂרָאֵל מִן גָּלוּתָא. צַדִּיק, כְּמָה דְּאוֹקְמוּהָ, דִּכְתִּיב (תהילים קכ״ו:א׳) בְּשׁוּב יְיָ' אֶת שִׁיבַת צִיּוֹן, בְּגִין דְּיֵיתוּב לְאַתְרֵיהּ, וְיֵיתֵי לְאִתְחַבְּרָא בִּכְנֶסֶת יִשְׂרָאֵל. וְעַל דָּא, וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. וְהִשְׁתַּחֲווּ לַיְיָ' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלַיִם, מַאי קָא מַיְירֵי. אֶלָּא מִלָּה דָּא דְּהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם, כִּבְיָכוֹל, יִשְׂרָאֵל לָא יִפְּקוּן מִן גָּלוּתָא, אֶלָּא בִּשְׁכִינְתָּא, כְּמָה דְּאוֹקְמוּהָ, וְאִינּוּן נִדָּחִים הִשְׁתַּחֲווּ לַיְיָ'.</p>"],[9520012658,"<p>תּוּ אָמַר רִבִּי אַבָּא, כְּתִיב, (תהילים קכ״א:ח׳) יְיָ' יִשְׁמוֹר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. יִשְׁמָר צֵאתְךָ תִּינַח. אֶלָּא וּבוֹאֶךָ, מַאי קָא מַיְירֵי, דְּהָא מַאן דְּעָאל לְבֵיתֵיהּ לָא מִסְתָּפֵי. אֶלָּא הַאי בַּר נָשׁ דְּשַׁוֵּי רְשִׁימָא קַדִּישָׁא לְבֵיתֵיהּ, בְּמִלִּין דִּשְׁמָא עִלָּאָה, הַאי אִתְנְטִיר מִכֹּלָּא. כַּד נָפִיק הַהוּא דְּמָדוֹרֵיהּ לְתַרְעָא דְּבֵיתֵיהּ, זָקִיף וְחָמֵי רְשִׁימָא קַדִּישָׁא, וְעָיִיִן (ס\"א נעיץ) בְּפִתְחֵיהּ. כַּד נָפִיק בַּר נָשׁ, הוּא אוֹזִיף לֵיהּ, וְנָטִיר לֵיהּ. כַּד עָיִּיל לְבֵיתֵיהּ, הוּא אַכְרִיז קַמֵּיהּ, אִזְדָּהֲרוּ בִּיקָרָא דְּדִיּוּקְנָא דְּמַלְכָּא קַדִּישָׁא. וְכָל דָּא, בְּגִין הַהוּא רְשִׁימָא דִּשְׁמָא קַדִּישָׁא, דְּאִתְרְשִׁים בְּתַרְעֵיהּ.</p>\n<p>וְלָאו דַּי לֵיהּ לְבַּר נָשׁ דְּאִתְנְטַר בְּבֵיתֵיהּ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לֵיהּ כַּד עָיִּיל, וְכַד נָפִיק. דִּכְתִּיב, יְיָ' יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, הַאי רוּחָא בִּישָׁא דְּשָׁארִי <Nonei></i> בֵּין תַּרְעֵי. וַוי לֵיהּ לְבַּר נָשׁ, דְּלָא יָדַע לְאִזְדַּהֲרָא מִנֵּיהּ, וְלָא רָשִׁים לְפִתְחָא דְּבֵיתֵיהּ שְׁמָא עִלָּאָה קַדִּישָׁא, דְּיִשְׁתְּכַח עִמֵּיהּ. דְּהָא אִית לֵיהּ תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ שַׁמָּשִׁין בִּישִׁין מְקַטְרְגִין, כָּל חַד מְשַׁמֵשׁ יוֹמֵיהּ, וְכֻלְּהוּ מִשְׁתַּכְּחֵי עִמֵּיהּ כָּל יוֹמֵי שַׁתָּא, וּמְקַטְרְגֵי בֵּיהּ לְעֵילָּא וְתַתָּא. וְכֻלְּהוּ מִשְׁתַּכְּחֵי בֵּיהּ בִּימָמָא וּבְלֵילְיָא. בִּימָמָא, לְקַטְרְגָא לֵיהּ. בְּלֵילְיָא, לְצַעֲרָא לֵיהּ בְּחֶלְמֵיהּ.</p>\n<p>כַּד נָפִיק לְקַטְרְגָא לֵיהּ, כַּד עָאל, שַׁוְּויָן יְדַיְיהוּ עָלֵיהּ דְּכִתְפֵיהּ, וְאַמְרִין לֵיהּ, וַוי לֵיהּ לִפְלַנְיָּא דְּנָפַק מֵרְשׁוּתָא דְּמָארֵיהּ. וַוי לֵיהּ לִפְלַנְיָּא בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. בְּגִין כָּךְ בָּעָאן בְּנֵי מְהֵימְנוּתָא, לְמֶהֱוֵי רְשִׁימִין בְּכֹלָּא, לְמֶהֱוֵי רְשִׁימִין בִּרְשִׁימָא דְּמָארֵיהוֹן, לִאִזְדַּעְזְעָא מִנַּיְיהוּ כָּל סִטְרִין זִינִין בִּישִׁין, לְמֶהֱוֵי נְטִירִין בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. זַכָּאִין חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, עָלַיְיהוּ כְּתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'.</p>"],[9520012659,"<p>(דברים ו׳:ה׳) וְאָהַבְתָּ אֵת יְיָ' אֱלֹהֶיךָ. רִבִּי יוֹסִי פָּתַח, (ישעיהו נ״ב:ה׳) וְעַתָּה מַה לִי פֹה נְאֻם יְיָ' כִּי לֻקַּח עַמִּי חִנָּם וְגוֹ'. תָּא חֲזֵי, רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּיִשְׂרָאֵל אַף עַל גַּב דְּחוֹבַיְיהוּ גָּרְמוּ לְאִסְתַּלְּקָא מִבֵּינַיְיהוּ, וְאִתְבָּדָּרוּ בֵּינֵי עַמָמַיָא, הוּא תָּבַע עֶלְבּוֹנָא דִּלְהוֹן. וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל שָׁרָאן בְּאַרְעֲהוֹן, קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּגִנְתֵּיהּ, וְקָרִיב לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, וְשָׁמַע קַלֵּיהוֹן, וְאִשְׁתְּבַּח בְּהוּ.</p>\n<p>כֵּיוָן דְּגַרְמוּ חוֹבַיְיהוּ, וְאִתְגְּלֵי יִשְׂרָאֵל מֵאַרְעָא קַדִּישָׁא, קוּדְשָׁא בְּרִיךְ הוּא לָא עָאל בְּגִנְתֵּיהּ, וְלָא מִשְׁתַּעֲשָׁע בֵּיהּ. וְלָא עוֹד, אֶלָּא דְּאִיהוּ צָוַוח וְאָמַר, וְעַתָּה מַה לִּי פֹה נְאֻם יְיָ', וּכְתִיב הָתָם (תהילים קל״ב:י״ד) פֹּה אֵשֵׁב כִּי אִוִּיתִיהָ. כִּי לֻקַּח עַמִּי חִנָּם, כְּמָה דְּאַתְּ אָמֵר, (ישעיהו נ״ב:ה׳) חִנָּם נִמְכַּרְתֶּם.</p>\n<p>וּמֵהַהוּא יוֹמָא דְּאִתְגְּלִיאוּ יִשְׂרָאֵל מֵאַרְעֲהוֹן, לָא אִשְׁתְּכַח חֶדְוָותָא קָמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. וְכָל דָּא, בְּגִין רְחִימוּתָא דִּלְהוֹן, דְּרָחִים לוֹן קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאַתְּ אָמֵר, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ'. (ועל דא) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. וְאָהַבְתָּ: דְּבָעֵי בַּר נָשׁ לְאִתְקַשְּׁרָא בֵּיהּ בִּרְחִימוּתָא עִלָּאָה, דְּכָל פּוּלְחָנָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח לְקוּדְשָׁא בְּרִיךְ הוּא, דְּיִפְלַח בִּרְחִימוּ. דְּלֵית לָךְ פּוּלְחָנָא, כְּמוֹ רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא. רִבִּי אַבָּא אָמַר, הָנֵי מִלֵּי כְּלָלָא דְּאוֹרַיְיתָא אִינּוּן, בְּגִין דְּעֶשֶׂר אֲמִירָן דְּאוֹרַיְיתָא, הָכָא אִתְכְּלִילוּ, וְהָא אוֹקְמוּהָ חַבְרַיָּיא.</p>\n<p>תָּא חֲזֵי, לֵית לָךְ מִלָּה בַּחֲבִיבוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כְּמַאן דְּרָחִים לֵיהּ כַּדְּקָא יָאוּת. וּמַה הוּא. כְּמָה דִּכְתִּיב, בְּכָל לְבָבְךָ. בְּכָל, מַאי קָא מַיְירֵי, בִּלְבָבְךָ מִבָּעֵי לֵיהּ. בְּנַפְשְׁךָ, בִּמְאֹדֶךָ, מַהוּ בְּכָל לְבָבְךָ. אֶלָּא לְאַכְלְלָא תְּרֵין לִבִּין, חַד טַב וְחַד בִּישׁ. בְּכָל נַפְשְׁךָ: חַד טַב, וְחַד בִּישׁ. בְּכָל מְאֹדֶךָ, דָּא לָא אַתְיָא לִדְּרָשָׁא. אָמַר רִבִּי אֶלְעָזָר, וַאֲפִילּוּ הַאי לִדְּרָשָׁא הוּא. מַאי טַעְמָא. בֵּין דְּנָפַל לֵיהּ מָמוֹנָא מִיְּרוּתָא, אוֹ מִסִּטְרָא אַחֲרָא, אוֹ בֵּין דְּאִיהוּ רָוַוח לֵיהּ, וְעַל דָּא כְּתִיב בְּכָל מְאֹדֶךָ.</p>\n<p>אָמַר רִבִּי אַבָּא, אַהֲדַרְנָא לַקְּרָא וְאָהַבְתָּ. מַאן דְּרָחִים לְקוּדְשָׁא בְּרִיךְ הוּא, אִתְעֲטָּר בְּחֶסֶד מִכָּל סִטְרִין, וְעָבִיד חֶסֶד בְּכֹלָּא, וְלָא חָיִיס עַל גּוּפֵיהּ וְעַל מָמוֹנֵיהּ. מְנָלָן. מֵאַבְרָהָם. כְּמָה דְּאִתְּמַר, דְּהָא לָא חָס בִּרְחִימוּתָא דְּמָארֵיהּ, עַל לִבֵּיהּ, (דהוא יצריה) וְעַל נַפְשֵׁיהּ, וְעַל מָמוֹנֵיהּ.</p>\n<p>עַל לִבֵּיהּ לָא אַשְׁגַּח, עַל רְעוּתָא דִּילֵיהּ, בְּגִין רְחִימוּתָא דְּמָארֵיהּ. עַל נַפְשֵׁיהּ, דְּלָא חָס עַל בְּרֵיהּ, וְעַל אִתְּתֵיהּ, בְּגִין רְחִימוּתָא דְּמָארֵיהּ. עַל מָמוֹנֵיהּ, דְּהֲוָה קָאִים בְּפָרָשַׁת אָרְחִין, וְאַתְקִין מְזוֹנֵי לְכָל עָלְמָא. בְּגִין כָּךְ, אִתְעֲטָּר בְּעִטְרָא דְּחֶסֶד. כְּמָה דִּכְתִּיב, (מיכה ז׳:כ׳) חֶסֶד לְאַבְרָהָם. וּמַאן דְּאִתְקְשַּׁר בִּרְחִימוּתָא דְּמָארֵיהּ, זָכָה לְהַאי. וְלֹא עוֹד, אֶלָּא דְּעָלְמִין כֻּלְּהוּ מִתְבָּרְכָן בְּגִינֵיהּ. הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה, אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹּ\"ה. (דכתיב, (בראשית י״ב:ג׳) ונברכו בך כל משפחות האדמה)</p>\n<p>יוֹמָא חַד, הֲוָה חָלַשׁ רִבִּי יוֹסִי, עָאל (עאלו) לְגַבֵּיהּ רִבִּי אַבָּא וְרִבִּי יְהוּדָה וְרִבִּי יִצְחָק, חָמוּ לֵיהּ דְּהֲוָה נָפִיל עַל אַנְפּוֹי וְנָאִים. יָתְבוּ. כַּד אִתְּעַר, חָמוּ לֵיהּ לְאַנְפּוֹי דְּחַיְיכִין. אָמַר לֵיהּ רִבִּי אַבָּא, מִלָּה חַדְתָּא חֲמֵיתָא. <Nonei></i> אָמַר לֵיהּ וַדַּאי, דְּהַשְׁתָּא סַלְּקָא נַפְשִׁי, וְחָמֵית יְקָרָא, מֵאִינּוּן דְּמָסָרוּ גַּרְמַיְיהוּ עַל קְדוּשָּׁה דְּמָארֵיהוֹן, דַּהֲווֹ עָאלִין בִּתְלֵיסָר נַהֲרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא. וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּהוּ. וַחֲמֵינָא מַה דְּלָא יָהֲבוּ לִי רְשׁוּתָא לְמֵימַר. וְשָׁאִילְנָא לוֹן, אֲמֵינָא, הַאי יְקָרָא דְּמַאן הוּא. אָמְרוּ לִי, מֵאִינּוּן דִּרְחִימוּ לְמָארֵיהוֹן בְּהַהוּא עָלְמָא. וּמִמָּה דְּחָמִית, נַפְשָׁאי וְלִבָּאי אִתְנְהִיר, וְעַל דָּא אַנְפָּאִי חַיְּיכִין.</p>\n<p>אָמַר לֵיהּ רִבִּי אַבָּא, זַכָּאָה חוּלָקָךְ, אֲבָל אוֹרַיְיתָא אַסְהִיד בְּהוּ, דִּכְתִּיב, (ישעיהו ס״ד:ג׳) עַיִן לָא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. אָמַר לֵיהּ רִבִּי יְהוּדָה, הָא שָׁאִילוּ חַבְרַיָּיא, דָּא דִּכְתִּיב יַעֲשֶׂה, תַּעֲשֶׂה מִבָּעֵי לֵיהּ.</p>\n<p>אָמַר לֵיהּ, הָא אִתְּמַר. אֲבָל רָזָא דְּמִלָּה, הַיְינוּ דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ' וּלְבַקֵּר בְּהֵיכָלוֹ. וְאוֹקְמוּהָ, נֹעַם יְיָ', הַהוּא דְּאַתְיָא מֵעַתִּיקָא קַדִּישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בֵּיהּ. דְּהָא הַהוּא נֹעַם מֵעַתִּיקָא נָפְקָא. וּלְבַקֵּר בְּהֵיכָלוֹ, בְּהֵיכָלָא עִילָּאָה עַל כֹּלָּא. אוּף הָכָא, עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה. מַאן, הַהוּא עַתִּיקָא סְתִימָא דְּכֹלָּא, דְּהָא בֵּיהּ תַּלְיָא, אָמַר לֵיהּ, וַדַּאי הָכִי הוּא. זַכָּאָה חוּלָקֵיהוֹן דְּאִינּוּן דִּרְחִימוּתָא דְּמָארֵיהוֹן מִתְדַּבְּקָן בְּהוּ, לְאִלֵּין לֵית שִׁעוּרָא לְחוּלָקֵיהוֹן בְּהַהוּא עָלְמָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, כַּמָה מָדוֹרִין עַל מָדוֹרִין אִית לְהוּ לְצַדִּיקַיָּיא בְּהַהוּא עָלְמָא, וּמָדוֹרָא עִלָּאָה דְּכֹלָּא, אִינּוּן דִּרְחִימוּתָא דְּמָארֵיהוֹן אִתְקְשַּׁר בְּהוּ, דְּהָא מָדוֹרֵיהוֹן אִתְקְשַּׁר בְּהֵיכָלָא דְּסָלִיק עַל כֹּלָּא. מַאי טַעְמָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי אִתְעֲטָּר.</p>\n<p>תָּא חֲזֵי, (ס\"א כלא אהבה) הֵיכָלָא דָּא, אַהֲבָה אִתְקְרֵי, וּבְגִין אַהֲבָה קַיְּימָא כֹּלָּא. כְּמָה דִּכְתִּיב, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. וְכֹלָּא בִּרְחִימוּתָא קַיְּימָא, דְּהָא שְׁמָא קַדִּישָׁא הָכִי אִשְׁתְּכַח דְּהָא אוּקְמוּהָ, י' לָא מִתְפְּרַשׁ קוֹצָא דִּלְעֵילָּא מִן י' לְעָלְמִין. דְּהָא בִּרְחִימוּתָא שַׁרְיָא עָלֵיהּ, וְלָא מִתְפְּרַשׁ מִנֵּיהּ לְעָלְמִין. ה', הָא אוּקְמוּהָ, דְּיוֹד לָא מִתְפְּרַשׁ מִנָהּ, וְאִשְׁתְּכָחוּ כַּחֲדָא בַּחֲבִיבוּתָא, לָא אִתְפָּרְשָׁן דָּא מִן דָּא. כְּגַוְונָא דָּא ה' וְהָא אִתְּמַר, כְּמָה דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן, יוֹצֵא תָּדִיר לְעָלְמִין, בַּחֲבִיבוּתָא אִתְדַּבְּקָן.</p>\n<p>ו\"ה כַּד אִתְדַּבְּקָן דָּא בְּדָא, אִתְדַּבְּקָן בַּחֲבִיבוּתָא כַּחֲדָא, חָתָן בְּכַלָּה, דְּאָרְחַיְיהוּ תָּדִיר בַּחֲבִיבוּתָא אִשְׁתְּכַח. י' בְּה', ה' עִם ו', ו' עִם ה'. וְדָא בְּדָא אִתְקְשַּׁר בַּחֲבִיבוּתָא. וְכֹלָּא אַהֲבָה אִקְרֵי. וְעַל דָּא מַאן דְּרָחִים לְמַלְכָּא, הָא אִתְקְשַׁר בְּהַהוּא אַהֲבָה. וּבְּגִין כָּךְ, וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ.</p>"],[9520012660,"<p>וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ'. רִבִּי יִצְחָק פָּתַח, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָּה יְיָ' מִי כָמוֹךָ מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ וְעָנִי וְאֶבְיוֹן מִגּוֹזְלוֹ. הַאי קְרָא דָּוִד אַמְרֵיהּ (אמרו) בְּרוּחָא דְּקוּדְשָׁא, כָּל עַצְמוֹתַי תֹּאמַרְנָּה, וְכִי מַאן חָמָא גַּרְמֵי דְּאָמְרוּ שִׁירָתָא. אֶלָּא הַאי קְרָא, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאַחֲיָיא מֵתַיָּיא, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַתְקְנָא גַּרְמֵי, וּלְקָרְבָא כָּל חַד וְחַד לְאַתְרַיְיהוּ, דִּכְתִּיב, (יחזקאל ל״ז:ז׳) וַתִּקְרְבוּ עֲצָמוֹת עֶצֶם אֶל עַצְמוֹ. וּכְתִיב (ישעיהו נ״ח:י״א) וְעַצְמוֹתֶיךָ יַחֲלִיץ. כְּדֵין זְמִינִין אִינּוּן לְמֵימַר שִׁירָתָא.</p>\n<p>מַאי שִׁירָתָא אַמְרֵי. יְיָ' מִי כָמוֹךָ (מקדמי) וְדָא שִׁירָתָא מְעַלְּיָיא, מִמַּה דְּאָמְרוּ יִשְׂרָאֵל עַל יַמָּא, דְּהָא אִינּוּן לָא אַדְכְּרוּ שְׁמָא קַדִּישָׁא, אֶלָּא בָּתַר תְּלַת מִלִּין, דִּכְתִּיב, (שמות ט״ו:י״א) מִי כָמוֹכָה בָּאֵלִים יְיָ'. וְהָכָא אִינּוּן מַקְדְּמֵי לִשְׁמָא קַדִּישָׁא, דִּכְתִּיב יְיָ' מִי כָמוֹךָ. מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ, דָּא יֵצֶר טוֹב, מִיֵּצֶר רָע. בְּגִין דְּיֵצֶר הָרָע תַּקִּיף הוּא כְּאַבְנָא. כְּמָה דִּכְתִּיב, (יחזקאל ל״ו:כ״ו) וַהֲסִירוֹתִי אֶת לֵב הָאֶבֶן. וְיֵצֶר טוֹב הוּא בִּשְׂרָא, דִּכְתִּיב, (שם) וְנָתַתִּי לָכֶם לֵב בָּשָׂר.</p>"],[9520012661,"<p>תָּא חֲזֵי, יֵצֶר הָרָע לְמָה הוּא דּוֹמֶה. בְּשַׁעֲתָא דְּאָתֵי לְאִזְדַּוְּוגָא בְּבַּר נָשׁ, הוּא כְּפַרְזְלָא, עַד דְּעָאלִין לֵיהּ בְּנוּרָא. בָּתַר דְּיִתְחַמֵּם אִתְהַדָּר כֹּלָּא כְּנוּרָא.</p>\n<p>רִבִּי חִיָּיא אָמַר, יֵצֶר הָרָע כַּד אָתֵי לְאִזְדַּוְּוגָא בֵּיהּ לְבַּר נָשׁ, דָּמֵי לְבַּר נָשׁ דְּקָרִיב לְפִתְחָא, וְחָמֵי דְּלָא אִית מַאן דְּמָחֵי בִּידֵיהּ. עָאל לְבֵיתָא, וְאִתְעָבִיד לֵיהּ אֹרֵחַ. חָמָא דְּלָא אִית מַאן דִּמְחֵי בִּידֵיהּ, וְיֵיזִיל לֵיהּ לְאָרְחֵיהּ. כֵּיוָן דְּעָיִּיל לְבֵיתָא, וְלָא אִית דְּיִמְחֵי בִּידֵיהּ, אִתְמְנָא עָלֵיהּ וְאִתְעָבִיד מָארֵיהּ דְּבֵיתָא <Nonei></i> עַד דְּיִשְׁתְּכַח דְּכָל בֵּיתָא קָאִים בִּרְשׁוּתֵיהּ.</p>\n<p>מֵאַן אוֹלִיפְנָא. מִפַּרְשְׁתָּא דְּדָוִד אוֹלִיפְנָא. מַה כְּתִיב, (שמואל ב י״ב:ד׳) וַיָּבֹא הֵלֶךְ לְאִישׁ הֶעָשִׁיר, הֵלֶךְ דְּקָרִיב לְפִתְחָא, וְלָא בָּעֵי לְאִתְעַכְּבָא תַּמָּן, אֶלָּא לְמֵהַךְ לְאָרְחֵיהּ. כַּךְ הוּא יֵצֶר הָרָע, כְּמָה דְּמִקְרַב לְבֵיתָא, מִתְקָרֵב גַּבֵּי דְּבַּר נָשׁ, אִתְּעַר עָלֵיהּ בְּחוֹבָא זְעֵיר, דָּא הוּא אוֹרֵחַ עֲרָאי. חָמֵי דְּלֵית דִּמְחֵי בִּידֵיהּ, מַה כְּתִיב, לַעֲשׂוֹת לָאוֹרֵחַ הַבָּא אֵלָיו, אִתְעָבִיד לֵיהּ אוֹרֵחַ אַכְסְנַאי בְּבֵיתָא, אִתְּעַר עָלֵיהּ בְּחוֹבוֹי יַתִּיר, יוֹמָא חַד, אוֹ תְּרֵין יוֹמִין, כְּהַאי אוֹרֵחַ דְּשָׁרָאן לֵיהּ בְּבֵיתָא, יוֹמָא חֲדָא, אוֹ ב' יוֹמִין, (בגין דאיהו אורח) כֵּיוָן דְּחָמֵי דְּלֵית מַאן דִּמְחֵי בִּידֵיהּ, מַה כְּתִיב, (שם) וַיַּעַשׂ לְאִישׁ הַבָּא אֵלָיו, אִתְעָבִיד מָארֵי דְּבֵיתָא, כְּמָה דְאַתְּ אָמֵר (בראשית מ״ב:ל׳) הָאִישׁ אֲדוֹנֵי הָאָרֶץ. (רות א׳:ג׳) אִישׁ נָעֳמִי. כַּךְ הוּא יֵצֶר הָרָע, אִתְעָבִיד לָקֳבְלֵיהּ דְּבַּר נָשׁ, אִישׁ, בַּעַל הַבַּיִת, הָא אִתְקְשַׁר בַּר נָשׁ בְּפוּלְחָנֵיהּ, וְהוּא עָבִיד בֵּיהּ רְעוּתֵיהּ.</p>\n<p>וְעַל דָּא בָּעֵי בַּר נָשׁ לְשַׁוָּאָה מִלִּין דְּאוֹרַיְיתָא עָלֵיהּ תָּדִיר, בְּגִין דִּיְהֵא הַהוּא יֵצֶר הָרָע תָּבִיר בְּהוּ, דְּלֵית לֵיהּ מְקַטְרֵג לְיֵצֶר הָרָע, בַּר מִלֵּי דְּאוֹרַיְיתָא. וְעַל דָּא כְּתִיב, וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ', עַל לְבָבֶךָ, עַל תְּרֵי יְצָרֶיךָ, יֵצֶר הַטּוֹב אִתְעֲטָּר בְּהוּ, וְיֵצֶר הָרָע אִתְכָּנַע בְּהוּ. אָמַר רִבִּי יְהוּדָה, יֵצֶר הַטּוֹב, מַה בָּעֵי מִלֵּי דְּאוֹרַיְיתָא. אָמַר לֵיהּ, יֵצֶר הַטּוֹב אִתְעֲטָּר בְּהוּ. וְיֵצֶר הָרָע, כֵּיוָן דְּחָמֵי בַּר נָשׁ לָא תָּב, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּדֵין הוּא סָלִיק לְעֵילָּא, וְאוֹלִיף עָלֵיהּ חוֹבָה, הֲדָא הוּא דִכְתִיב, (משלי ג׳:ל״ה) וּכְסִילִים מֵרִים קָלוֹן.</p>"],[9520012662,"<p>כַּד אָתָא רִבִּי שִׁמְעוֹן, אָמַר, הָא וַדַּאי פַּרְשְׁתָּא דִּקְרִיאַת שְׁמַע רְמִיזָא בֵּיהּ י' אֲמִירָן כְּמָה דְּאוּקְמוּהָ, וְהָכִי הוּא וַדַּאי. וְהָיוּ הַדְּבָרִים הָאֵלֶּה, כְּלָלָא דְּעֶשֶׂר אֲמִירָן אִינּוּן. וּבְּגִין כָּךְ י' פִּקּוּדִין אִית הָכָא, לָקֳבֵל י' פִּקּוּדִין דְּאוֹרַיְיתָא. וּמַאן אִינּוּן. וְשִׁנַּנְתָּם לְבָנֶיךָ. וְדִבַּרְתָּ בָּם. בְּשִׁבְתְּךָ בְּבֵיתֶךָ. וּבְלֶכְתְּךָ בַדֶרֶךְ. וּבְשָׁכְבְּךָ. וּבְקוּמֶךָ. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ. וְהָיוּ לְטוֹטָפוֹת בֵּין עֵינֶיךָ. וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ. וּבִשְׁעָרֶיךָ. הָא י', לָקֳבֵל י' אֲמִירָן. וְעַל דָּא פָּרְשִׁיָּין אִלֵּין כְּלַל רַב אִינּוּן בְּאוֹרַיְיתָא, זַכָּאָה חוּלָקֵיהּ, מַאן דְּאַשְׁלִים לֵיהּ בְּכָל יוֹמָא תְּרֵי זִימְנֵי, דְּהָא אִתְקַדָּשׁ בְּפוּמֵיהּ שְׁמָא קַדִּישָׁא כַּדְּקָא יָאוּת.</p>\n<p>רִבִּי אֲחָא, הֲוָה קָאִים עִמֵּיהּ דְּרִבִּי אֶלְעָזָר לֵילְיָא חַד בָּתַר פַּלְגּוּת לֵילְיָא, וַהֲווּ מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר, (נ\"א רבי אחא) וְאָמַר, (דברים לב) כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ וְגוֹ'. תָּא חֲזֵי, עַל כָּל תְּנָאִין (נ\"א פקודין) דְּגָזַר קוּדְשָׁא בְּרִיךְ הוּא כַּד עָאלוּ לְאַרְעָא דְּיִשְׂרָאֵל, גְּזֵרָה דְּאוֹרַיְיתָא הֲוָה. מַאי טַעֲמָא, בְּגִין דִּשְׁכִינְתָּא לָא מִתְיַישְּׁבָא בְּאַרְעָא, אֶלָּא בְּאוֹרַיְיתָא. וְלָא מִתְיַישְּׁבָא לְעֵילָּא, אֶלָּא בְּאוֹרַיְיתָא.</p>"],[9520012663,"<p>דְּהָכִי אָמַר (רבי שמעון) אַבָּא, תּוֹרָה שֶׁבְּעַל פֶּה לָא אִשְׁתְּמוֹדָע, אֶלָּא בְּגִין תּוֹרָה שֶׁבִּכְתָב. שְׁכִינְתָּא לָא מִתְיַישְּׁבָא לְעֵילָּא אֶלָּא עִם תּוֹרָה דִּלְתַּתָּא. דְּכָל זִמְנָא דְּאוֹרַיְיתָא אִשְׁתְּכַח עִמֵּיהּ (דבר נש), יַכְלָא לְמֵיקָם בְּעָלְמָא. (נ\"א תורה שבכתב לא אשתמודעא אלא בגין תורה שבעל פה, ותורה שבעל פה לא אשתמודעא אלא מתורה שבכתב, ודאי כלל הצריך לפרט, ופרט הצריך לכלל. שכינתא לא מתיישבא לעילא אלא באורייתא דלתתא. דכל זמנא דאורייתא אשתכחת יכילא למיקם בעלמא) הֲדָא הוּא דִכְתִיב, כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ לָשֶׁבֶת עַל הָאֲדָמָה. עַל הָאֲדָמָה סְתָם. וְאִי לָאו דְּאַפְסִיק מִלֵּי דְּאוֹרַיְיתָא לָא יַכְלָא לְמֵיקָם. דִּכְתִּיב, (ירמיהו ט׳:י״ב) עַל מַה אָבְדָה הָאָרֶץ. וּכְתִיב, וַיֹּאמֶר יְיָ' עַל עָזְבָם אֶת תּוֹרָתִי.</p>\n<p>עַד דַּהֲווֹ יַתְבֵי, מָאִיךְ רִבִּי שִׁמְעוֹן רֵישֵׁיהּ. אָמַר, וַדַּאי הָכִי הוּא וְדָא הוּא רָזָא דְּאַשְׁכַּחְנָא בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, וְאוֹקִים קְרָא דָּא, בְּרָזָא דִּכְנֶסֶת יִשְׂרָאֵל, דִּכְתִּיב, (שמות כ״א:י׳) שְׁאֵרָהּ כְּסוּתָהּ וְעוֹנָתָהּ לָא יִגְרָע. וְאִי אִתְמְנָעוּ מִנָהּ, מָה כְּתִיב, וְיָצְאָה חִנָּם אֵין כָּסֶף. כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ׳:א׳) אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. וּכְתִיב, (ישעיהו נ״ב:ג׳) חִנָּם נִמְכַּרְתֶּם וְלֹא בְכֶסֶף תִּגָּאֵלוּ. וּמַאן דְּמָנַע אוֹרַיְיתָא מִנָהּ, כְּמַאן דְּנָסַב מָארֵי (ס\"א שארה) דְּאִתְּתָא, וּמָנַע לֵיהּ מִנָהּ, דָּא אִשְׁתְּאָרַת כְּאַרְמַלְתָּא, וְלָא אַרְמַלְתָא. הֲדָא הוּא דִכְתִיב, (איכה א׳:א׳) הָיְתָה כְּאַלְמָנָה, וְלָא אַלְמָנָה.</p>\n<p>יָתְבוּ אִתְעַסְּקוּ בְּאוֹרַיְיתָא, עַד דְּנָהִיר יוֹמָא. בָּתַר דְּנָהִיר יוֹמָא, קָמוּ וְאָזְלוּ. עַד דַּהֲווֹ אָזְלוּ, חָמוּ חַד גְּבָר דְּהֲוָה אָזִיל בְּאָרְחָא, וְרֵישֵׁיהּ עָטִיף, קְרִיבוּ גַּבֵּיהּ, וַהֲוָה רָחִישׁ <Nonei></i> בְּשִׂפְוָותֵיהּ, וְלָא אָתִיב לוֹן מִדִי. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי הַאי אִמְלַךְ בְּמָארֵיהּ. יָתִיב רִבִּי אֶלְעָזָר וְרַבִּי אֲחָא וְצַלּוּ צְלוֹתָא, וְהַהוּא גְּבַר קָאִים בְּקִיּוּמֵיהּ בַּאֲתָר אַחֲרָא. בָּתַר דְּסִיְּימוּ צְלוֹתָא, אַזְלוּ בְּאָרְחָא, וְהַהוּא גַּבְרָא אִשְׁתְּמִיט מִנַּיְיהוּ. אָמַר רִבִּי אֶלְעָזָר, הַאי גַּבְרָא, אוֹ טִפְּשָׁא הוּא, אוֹ אָרְחוֹי לָא מִתְיַשְּׁרָן. אָמַר, נִתְעֲסָק בְּאוֹרַיְיתָא, דְּהָא שַׁעֲתָא הִיא.</p>"],[9520012664,"<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. כָּבוֹד חֲכָמִים יִנְחָלוּ, זַכָּאִין אִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא. עַד לָא פָּתַח מִלָּה, קָרִיב הַהוּא בַּר נָשׁ גַּבַּיְיהוּ. אָמַר רִבִּי אֶלְעָזָר, לֵית לָן לְמִפְסַק מִלֵּי דְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, זָכֵי לְמֵירַת יְרוּתָא דְּאַחֲסָנָא דִּלְעֵילָּא, בִּיקָרָא דְּמַלְכָּא עִלָּאָה קַדִּישָׁא, וְזָכֵי לְמֵירַת יְרוּתָא דְּאַחֲסָנָא בְּהַאי עָלְמָא, וּמַאי אִיהוּ. הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ', דְּלָא פָּסַק מִנַּיְיהוּ לְעָלְמָא. הֲדָא הוּא דִכְתִיב, כָּבוֹד חֲכָמִים יִנְחָלוּ, הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ'.</p>\n<p>וּכְסִילִים מֵרִים קָלוֹן, מַאי הוּא. תָּא חֲזֵי, כַּד בַּר נָשׁ אָזַל בְּאֹרַח מֵישָׁר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתָּדַּל בְּאוֹרַיְיתָא, הָא הַהוּא כְּבוֹד יְיָ' יָרִית לְגַרְמֵיהּ, וְכַמָּה אַפֹּטְרוֹפְּסִין סַנֵּיגוֹרִין אִשְׁתַּכְּחוּ לְעֵילָּא עָלֵיהּ דְּבַּר נָשׁ, וְכֻלְּהוּ אוֹלְפִין עָלֵיהּ זְכוּ, קַמֵּי מַלְכָּא קַדִּישָׁא, וְאִי בַּר נָשׁ לָא אִשְׁתְּדַּל בְּאוֹרַיְיתָא, וְלָא אָזַל בְּאָרְחָא דְּמָארֵיהּ, הוּא עָבִיד קַטֵיגוֹרָא עָלֵיהּ. וְהַהוּא קַטֵיגוֹרָא שָׁאט בַּאֲוִירָא (ואזיל ליה), וְלָא סָלִיק לְעֵילָּא, דִּלְמָא יְתוּב אָדָם מֵחוֹבוֹי. כֵּיוָן דְּחָמֵי דְּבַר נָשׁ לָא תָּב, וְלָא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּדֵין הוּא סָלִיק לְעֵילָּא, וְאוֹלִיף עָלֵיהּ חוֹבָא. הֲדָא הוּא דִכְתִיב, וּכְסִילִים מֵרִים קָלוֹן, וְסָלִיק לְעֵילָּא וְעָבִיד קִטְרוּגָא.</p>\n<p>פָּתַח וְאָמַר, (זכריה י״ד:י״ח) וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְלֹא עֲלֵיהֶם תִּהְיֶה הַמַּגֵּפָה וְגוֹ'. מַאי שְׁנָא מִצְרַיִם הָכָא, מִכָּל שְׁאַר עַמִּין, דְּהָא לְכֻלְּהוּ כְּתִיב (שם) וְלֹא עֲלֵיהֶם יְהִי הַגָּשֶׁם, וְהָכָא לָא. אֶלָּא הָא אוֹקְמוּהָ חַבְרַיָּיא, דְּהָא אַרְעָא דְּמִצְרַיִם לָא אִצְטְרִיךְ לְמִטְרָא, וְעַל דָּא לָאו הִיא בִּכְלָלָא דְּאִינּוּן דְּבָעָן מִטְרָא, אֲבָל אִינּוּן, דִּינָא אַחֲרָא אִסְתַּלָּק עָלַיְיהוּ, וְשַׁפִּיר קָאַמְרוּ.</p>\n<p>תָּא חֲזֵי, כְּתִיב (דברים י״א:י׳) כִּי הָאָרֶץ אֲשֶׁר אַתָּה בָא שָׁמָּה לְרִשְׁתָּה לֹא כְאֶרֶץ מִצְרַיִם הִיא אֲשֶׁר יְצָאתֶם מִשָּׁם וְגוֹ'. דְּהָא נַהֲרָא סָלִיק, (ומניה) מִנֵּיהּ מִשְׁתַּקְיָּיא אַרְעָא, אֲבָל הָכָא לִמְטַר הַשָּׁמַיִם תִּשְׁתֶּה מָּיִם, דְּהָא אַרְעָא קַדִּישָׁא מִן שְׁמַיָיא אִתְשַׁקְיָיא תָּדִיר. וְכַד יִשְׂרָאֵל הֲווֹ עַסְקִין בְּאוֹרַיְיתָא, הֲוָה אִתְשַׁקְיָיא כְּדְקָא יָאוּת. וּמַאן דְּמָנַע אוֹרַיְיתָא מִנָהּ, כְּאִילּוּ מָנַע טַב מִן כָּל עָלְמָא. עָאלוּ לְגוֹ מְעַרְתָּא חֲדָא דְּהֲוָה בְּאָרְחָא, עָאל הַהוּא גְּבַר עִמְּהוֹן, יָתְבוּ.</p>\n<p>פָּתַח הַהוּא גַּבְרָא וְאָמַר, (שמות ל״ג:י״א) וְדִבֶּר יְיָ' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים כַּאֲשֶׁר יְדַבֵּר וְגוֹ', הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. וְלָא מִלָּה דָּא כְּמִלָה דָּא, בְּקַדְמִיתָא וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים שַׁפִּיר, לְבָתַר וְשָׁב אֶל הַמַּחֲנֶה, לְבָתַר וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, מַהוּ. אָמַר רִבִּי אֶלְעָזָר וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בִּיקָרָא דִּילָן, דְּהַשְׁתָּא זִוּוּגָא דִּילָן בִּשְׁכִינְתָּא, וּשְׁכִינְתָּא לָא אִתְעָדֵי מִנָן. מַאן דְּפָתַח פִּתְחָא, לֵימָּא מִלָּה.</p>"],[9520012665,"<p>פָּתַח וְאָמַר, וְדִבֶּר יְיָ' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים, בְּכַמָּה דַּרְגִּין עִלָּאִין וְיַקִּירִין, אִתְפְּרַשׁ מֹשֶׁה נְבִיאָה מְהֵימָנָא, עַל כָּל שְׁאַר נְבִיאֵי דְּעָלְמָא. דְּהָא כֻּלְּהוּ לָקֳבְלֵיהּ, כְּקוֹף בִּפְנֵי בְּנֵי נָשָׁא. שְׁאַר נְבִיאֵי הֲווֹ מִסְתַּכְּלֵי בְּאַסְפָּקָלַרְיָא דְּלָא נָהִיר, וְעִם כָּל דָּא לָא הֲווֹ זַקְפָן אַנְפִּין לְעֵילָּא לְאִסְתַּכְּלָא, אֶלָּא כְּמָה דִּכְתִּיב, (דניאל י׳:ט׳) וַאֲנִי הָיִיתִי נִרְדָּם עַל פָּנַי וּפָנַי אָרְצָה. וְלֹא עוֹד אֶלָּא דְּמִלִּין לָא הֲווֹ גַּבַּיְיהוּ בְּאִתְגַּלְיָיא.</p>\n<p>וּמֹשֶׁה נְבִיאָה מְהֵימָנָא לָאו הָכִי, דְּהוּא הֲוָה מִסְתָּכַּל בְּאַסְפָּקָלַרְיָא דְּנַהֲרָא, וְקָאִים בְּקִיּוּמֵיהּ. וְלֹא עוֹד, אֶלָּא דְּהֲוָה זָקִיף רֵישָׁא לְאִסְתַּכְּלָא, כְּמַאן דְּאָמַר לְחַבְרֵיהּ, זָקוֹף רֵישָׁךְ, וְיִסְתַּכְּלוּן אַנְפָּךְ בְּאַנְפִּי (באנפאי), בְּגִין דְּתִנְדַּע מִלֵּי. כַּךְ מֹשֶׁה, פָּנִים אֶל פָּנִים זָקִיף רֵישָׁא, בְּלָא דְּחִילוּ, אַנְפּוֹי זַקְפָאן וּמִסְתְּכַּל <Nonei></i> בְּזִיו יְקָרָא עִלָּאָה, וְלָא אִשְׁתַּנֵי דַּעְתּוֹי וְאַנְפּוֹי, כִּשְׁאַר נְבִיאִין, דְּכַד הֲווֹ (מתנבאן) נַבְאָן (ס\"א בעאן) לְאִסְתַּכְּלָא, נַפְקָא מֵרְשׁוּתַיְיהוּ וּמִדַּעֲתַּיְיהוּ, וְאִשְׁתָּנֵי זִיו אַנְפַּיְיהוּ, וְלָא הֲווֹ יַדְעֵי מֵהַאי עָלְמָא כְּלוּם.</p>\n<p>וּמֹשֶׁה לָאו הָכִי, דְּמֹשֶׁה בְּהַהוּא דַּרְגָּא עִלָּאָה מַמָּשׁ הֲוָה מִסְתָּכַּל, וְלָא נָפַק מֵרְשׁוּתֵיהּ וּמִן דַּעְתֵּיהּ, דְּהָא בְּשַׁעֲתָא דְּהֲוָה מִסְתָּכַּל בְּזִיו יְקָרָא עִלָּאָה, מִיַּד וְשָׁב אֶל הַמַּחֲנֶה, לְמַלְּלָא עִמְּהוֹן בְּכָל מַה דְּאִצְטְרִיכָאן, וְדַעְתּוֹי מִתְיַשְּׁבָא בֵּיהּ כְּקַדְמִיתָא, וְיַתִּיר. וְדָא הוּא וְשָׁב אֶל הַמַּחֲנֶה. וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, וַדַּאי דְּהֲוָה יָנִיק מִתּוֹךְ הָאֹהֶל, אוֹלִיף לְאִסְתַּכְּלָא בְּרוּחַ קוּדְשָׁא, כְּמָה דְאַתְּ אָמֵר (שמואל א ג׳:א׳) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת אֶת יְיָ'.</p>\n<p>תָּא חֲזֵי, כָּל זִמְנָא דְּהֲוָה יְהוֹשֻׁעַ לְגַבֵּי דְּמֹשֶׁה, הֲוָה אוֹלִיף (ויניק) וְאָנִיק מִתּוֹךְ הָאוֹהֶל, וְלָא דָּחִיל. בָּתַר דְּאִתְפְּרַשׁ מִמֹּשֶׁה, וַהֲוָה בִּלְחוֹדוֹי, מַה כְּתִיב, (יהושע ה׳:י״ד) וַיִּפּוֹל יְהוֹשֻׁעַ עַל פָּנָיו אַרְצָה וְיִשְׁתָּחוּ, דְּלָא הֲוָה יָכִיל לְאִסְתַּכָּל, וְהַאי מֵחַד שְׁלִיחָא, כָּל שֶׁכֵּן מֵאֲתָר אַחֲרָא.</p>\n<p>לְבַר נָשׁ, דְּאַפְקִיד מַלְכָּא גַּבֵּיהּ מָאנֵי דְּהָב וְאַבְנֵי יְקָר, כָּל זִמְנָא דְּמִשְׁתַּכַּח גַּבֵּיהּ, שַׁמָּשָׁא דְּבֵיתֵיהּ, אָחִיד בְּהוּ וְאִסְתְּכַּל בְּהוּ. כֵּיוָן דְּסָלִיק הַהוּא בַּר נָשׁ מֵעָלְמָא, לָא שָׁבִיק מַלְכָּא לְגַבֵּי שַׁמָּשָׁא כְּלוּם, וְאָחִיד פִּקְדּוֹנָא דִּילֵיהּ. אָמַר הַהוּא שַׁמָּשָׁא, וַוי דְּאָבָדִית. בְּיוֹמוֹי דְּמָארִי, כָּל אִלֵּין הֲווֹ בִּידִי.</p>\n<p>כַּךְ יְהוֹשֻׁעַ, בְּיוֹמוֹי דְּמֹשֶׁה הֲוָה יָנִיק בְּכָל יוֹמָא מִתּוֹךְ הָאֹהֶל, וְלָא דָּחִיל. בָּתַר דְּשָׁכִיב, וַיִּפּוֹל יְהוֹשֻׁעַ עַל פָּנָיו. וַאֲנָא בְּגִין דַּאֲנָא שְׁכִיחַ בְּגַּוַויְיכוּ, אֶסְתָּכַּל בְּמִלֵי דְּאוֹרַיְיתָא, וְלָא אֱהֵא דָּחִיל. בָּתַר דְּאֶתְפְּרַשׁ מִנַּיְיכוּ, וְלָא אִיכוּל לְאִסְתַּכְּלָא בִּלְחוֹדָאי.</p>"],[9520012666,"<p>תּוּ פָּתַח וְאָמַר, (דברים ו׳:ז׳) וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם וְגוֹ'. כְּמָה דְאַתְּ אָמֵר (תהילים מ״ה:ו׳) חִצֶּיךָ שְׁנוּנִים. דְּבָעֵי בַּר נָשׁ לְחַדְּדָא מִלֵּי דְּאוֹרַיְיתָא לִבְרֵיהּ, כְּחַרְבָּא דְּאִיהוּ שִׁנָּנָא בִּתְרֵי סִטְרוֹי, בְּגִין דְּיֵיעוּל לֵיהּ חִדוּדָא וְחֶדְוָה (דאורייתא) בְּאוֹרַיְיתָא, וְלָא יִשְׁתְּכַּח לִבֵּיהּ בְּטִפְּשׁוּתָא. וְדִבַּרְתָּ בָּם, כָּל מִלִּין דְּאוֹרַיְיתָא, כָּל חַד וְחַד אוֹרְחָא לֵיהּ בִּלְחוֹדוֹי. וְדִבַּרְתָּ בָּם, וּתְדַבֵּר מִבָּעֵי לֵיהּ. אֶלָּא בָּעֵי בַּר נָשׁ לְאַנְהָגָא גַּרְמֵיהּ בְּהוּ, וּלְאִתְנַהֲגָא גַּרְמֵיהּ, דְּלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא.</p>\n<p>בְּשִׁבְתְּךָ בְּבֵיתֶךָ, לְאַנְהָגָא גַּרְמֵיהּ בְּבֵיתֵיהּ בְּאֹרַח מֵישָׁר וּבְאֹרַח תִּקּוּנָא, דְּיִלְפוּן מִנֵּיהּ בְּנֵי בֵּיתֵיהּ לְאַנְהָגָא גַּרְמֵיהּ עִמְּהוֹן בְּנַחַת וּבְחֵידוּ, וְלָא יָטִיל דְּחִילוּ בִּבְנֵי בֵּיתֵיהּ יַתִּיר, וְכָל עוֹבָדוֹי בְּבֵיתֵיהּ בְּאֹרַח תִּקּוּנָא. וּבְלֶכְתְּךָ בַדֶּרֶךְ, לְאַנְהָגָא בְּמִלֵּי דְּאוֹרַיְיתָא, וּלְתַקְּנָא גַּרְמֵיהּ בְּהוּ כְּמָה דְּאִצְטְרִיךְ, וּלְדַבְּרָא גַּרְמֵיהּ בְּאוֹרְחוֹי דְּאוֹרַיְיתָא. וּמַאי אִיהוּ. כְּמָה דְּיַעֲקֹב. לְדוֹרוֹן. לִקְרָבָא. לִצְלוֹתָא. וּצְלוֹתָא בָּעֵי לְצַלָּאָה לְמָארֵיהּ, וְעֵילָּא מִנְּהוֹן מִלֵּי דְּאוֹרַיְיתָא.</p>\n<p>וּבְשָׁכְבְּךָ, לְדַבְּרָא גַּרְמֵיהּ בִּדְחִילוּ דְּמָארֵיהּ, בִּקְדוּשָּׁה, בַּעֲנָוָה דְּלָא יִשְׁתְּכַח חָצִיף לָקֳבְלֵיהּ דְּמָארֵיהּ. וּבְקוּמֶךָ, לְמֵיהַב תּוּשְׁבְּחָן לְמָארֵיהּ דְּאָתִיב נִשְׁמָתֵיהּ. דְּהָא בְּכַמָּה חִיּוּבִין אִשְׁתְּכַח קַמֵּי מָארֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד עִמֵּיהּ חֶסֶד, וְאָתִיב לָהּ לְגוּפֵיהּ. (דברים ו׳:ח׳) וּקְשַׁרְתָּם לְאוֹת עַל יָדְכָה. הָא אוּקְמוּהָ, עַל יַד כֵּהָה, וְדָא הוּא שְׂמָאלָא. וּבְסִפְרָא דְּאַגַּדְתָּא אָמַר, עַל יַד כֹּ\"ה. כְּמָה דְאַתְּ אָמֵר (בראשית ט״ו:ה׳) כֹּ\"ה יִהְיֶה זַרְעֶךָ.</p>"],[9520012667,"<p>וְחַבְרַיָּיא יַתְבֵי דָּרוֹמָא אוֹקְמוּהָ בְּרָזָא דִּלְהוֹן, אַרְבַּע בָּתֵּי דִּתְפִילִין כְּהַאי גַּוְונָא. (נ\"א בגוונא אחרא) קַדֶּשׁ לִי כָל בְּכוֹר סְתָם, לָקֳבֵל כִּתְרָא עִלָּאָה דְּכֹלָּא. וְהָיָה כִּי יְבִיאֲךָ, לָקֳבֵל חָכְמָה. שְׁמַע יִשְׂרָאֵל וְאָהַבְתָּ, לָקֳבֵל בִּינָה. וְהָיָה לָקֳבֵל חֶסֶד. לְבָתַר כְּלִילָן כֻּלְּהוּ בִּדְרוֹעָא שְׂמָאלָא, דְּאִקְרֵי עֹז. וּכְתִיב, (ישעיהו ס״ב:ח׳) וּבִזְרוֹעַ עְֵזּוֹ. וְאֵין עֹז, אֶלָּא תּוֹרָה, וְאֵין עֹז, אֶלָּא תְּפִלִּין.</p>\n<p>וּמִלִּין לָא מִתְיַשְּׁבָן לְגַבָּן. מַאי טַעְמָא. בְּגִין דְּכִתְרָא עִלָּאָה הוּא כָּלִיל כֹּלָּא, דְּלָאו הוּא בְּחוּשְׁבָּנָא. וְעוֹד, וְהָיָה <Nonei></i> כִּי יְבִיאֲךָ בִּיצִיאַת מִצְרַיִם תַּלְיָיא, הַהוּא אֲתָר דְּאִשְׁתְּכַח בֵּיהּ חֵירוּ לְעַבְדִין, וְעַל דָּא לָא מִתְתַּקְּנָן בְּאָרְחַיְיהוּ. וַאֲנָן מֵחָכְמָה שַׁרְיָין, וְהָכִי הוּא וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיל לוֹן, אַרְבַּע לְעֵילָּא, אַרְבַּע לְתַתָּא, אַרְבַּע בַּאֲתָר דְּמוֹחָא. אַרְבַּע בַּאֲתָר דְּלִבָּא שַׁרְיָיא. בְּגִין דְּדָא בְּדָא אִתְקְשַּׁר.</p>\n<p>וּבָעֵי בַּר נָשׁ לְאִתְעַטְּרָא בְּהוּ, בְּגִין דְּאִיהוּ שְׁמָא קַדִּישָׁא עִלָּאָה. דִּכְתִּיב, (דברים כ״ח:י׳) וְרָאוּ כֹּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' וְגוֹ'. וְכָל מַאן דְּמִתְעַטָּר בְּעִטְרָא קַדִּישָׁא עִלָּאָה דָּא, אִקְרֵי מֶלֶךְ בְּאַרְעָא. וְקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ בִּרְקִיעָ. הֲדָא הוּא דִכְתִיב, (שיר השירים ז׳:ו׳) מֶלֶךְ אָסוּר בָּרְהָטִים. כְּמָה דְּקוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ לְעֵילָּא, הָכִי נָמֵי הוּא מֶלֶךְ לְתַתָּא. (ועם כל דא) וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ, בְּגִין דִּיהֱוֵי בַּר נָשׁ שְׁלִים בְּכֹלָּא, וְיִשְׁתְּכַּח שְׁלִים בְּפִקּוּדֵי דְּמָארֵיהּ, רָשִׁים לְעֵילָּא, רָשִׁים לְתַתָּא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל.</p>\n<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, תְּרֵי קְרָאֵי אַשְׁכַּחְנָא, דְּאַף עַל גַּב דְּכֹלָּא בְּחַד דַּרְגָּא תַּלְיָין, לָאו אִינּוּן מִדַּרְגָּא חַד. חַד קְרָא כְּתִיב, (חגי א) כֹּה אָמַר יְיָ' צְבָאוֹת. וְחַד קְרָא כְּתִיב, (ישעיה ו) כֹּה אָמַר יְיָ' אֱלֹהִים. מַה בֵּין הַאי לְהַאי. אֶלָּא בְּזִמְנָא דִּכְתִּיב כֹּה אָמַר יְיָ' צְבָאוֹת, כְּדֵין מִלָּה אַתְיָא בְּרַחֲמֵי. וּבְזִמְנָא דִּכְתִּיב כֹּה אָמַר יְיָ' אֱלֹהִים, כְּדֵין מִלָּה אַתְיָא בְּדִינָא.</p>\n<p>כֹּה אָמַר יְיָ' צְבָאוֹת, בְּגִין דְּהַאי כֹּה, אִתְבָּרְכָא מִצַדִּיק וּמִנֶצַח וְהוֹד, דְּאִקְרֵי יְיָ' צְבָאוֹת. וּכְדֵין, מִלָּה בְּאִתְבַּסְּמוּתָא אַתְיָיא, דְּהָא מֵאֲתָר דָּא קָא אַתְיָא. כֹּה אָמַר יְיָ' אֱלֹהִים, כְּדֵין הַאי כֹּה יַנְקָא מִסִּטְרָא דְּדִינָא, מֵאֲתָר דִּגְבוּרָה עִלָּאָה, וְאוֹלִיפְנָא מֵאַבָּא, דְּדִינָא הוּא בְּרַחֲמֵי, בְּגִין דִּכְתִּיב יְיָ' אֱלֹהִים.</p>\n<p>דְּהָא אֱלֹהִים גְּבוּרָה הוּא בְּכָל אֲתָר אֲדֹנָי, גְּבוּרָה תַּתָּאָה הִיא בְּכָל אֲתָר. וְעַל דָּא אִשְׁתְּמוֹדְעָן מִלֵּי מִפּוּמָא דִּנְבִיאָה, וְהוּא הֲוָה מִתְכַּוֵּין לְמֵימַר מִלָּה מֵאַתְרֵיהּ. וּכְדֵין הֲווֹ יַדְעֵי אִלֵּין בְּנֵי מְהֵימְנוּתָא, מֵאָן אֲתָר תַּלְיָיא מִלְּתָא.</p>"],[9520012668,"<p>פָּתַח רִבִּי אֲחָא וְאָמַר (שופטים ה׳:כ״ג) אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ יְיָ' וְגוֹ'. תָּא חֲזֵי, הַאי קְרָא רָזָא הוּא בְּרָזִין עִלָּאִין. בְּשַׁעֲתָא דְּמַלְכָּא קַדִּישָׁא מָסַר בֵּיתֵיהּ בִּידָא דְּמַטְרוֹנִיתָא כָּל זַיְינִין וְרוּמְחִין וּבַלֵיסְטְרָאוֹת דִּילֵיהּ אַפְקִיד בִּידָהָא, וְכָל אִינּוּן מַגִיחֵי קְרָבָא דִּילֵיהּ אַפְקִיד עִמָּהּ. הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל, וְהָא אוֹקְמוּהָ, וְכַד אֲגַח קוּדְשָׁא בְּרִיךְ הוּא קְרָבָא, בְּאִינּוּן גִּבּוֹרִין מַגִיחֵי קְרָבָא דְּקָאָמַרָן אַגָח, וְאִינּוּן אִקְרוּן מְלוּמְּדֵי מִלְחָמָה.</p>\n<p>כְּתִיב (שופטים ה׳:כ׳) מִן שָׁמַיִם נִלְחָמוּ הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא וְגוֹ'. וּתְנָן, בְּהַאי שַׁעֲתָא דְּאִתְנְדִיבוּ יִשְׂרָאֵל לְגַלָּאָה רְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵהוֹן, כְּדֵין הַאי חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, כָּנַשׁ כָּל חֵילָא דִּילֵיהּ, וְכָל זַיְינִין, וְכָל אִינּוּן מַגִיחֵי קְרָבָא, לְאַגָּחָא קְרָבָא עִמֵּיהּ (נ\"א דסיהרא) דְּסִיסְרָא. וְכוֹכָבַיָּיא הֲווֹ אוֹשְׁדִין נוּרָא מִלְעֵילָּא. וְאָמַר רִבִּי שִׁמְעוֹן, כָּל כּוֹכָב וְכוֹכָב אִית לֵיהּ שְׁמָא בִּלְחוֹדוֹי, וְכֻלְּהוּ בִּשְׁמָהָן אִקְרוּן.</p>\n<p>אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִתְעַתְּדוּ לְנַקְמָא נוּקְמָא דְּבָנַי. תְּרֵי נוּקְמֵי אֲנָא זַמִּין לְאִתְפָּרְעָא מִנַּיְיהוּ. חַד נוּקְמָא דְּשִׁית מְאָה רְתִיכִין דְּאוֹזִיף לֵיהּ לְרַבְרְבָא דְּמִצְרָאֵי, בְּגִין לְאַגָחָא קְרָבָא בְּהוּ בְּיִשְׂרָאֵל. דִּכְתִּיב, (שמות י״ד:ז׳) וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְכֹל רֶכֶב מִצְרָיִם. וְחַד נוּקְמָא דְּבָנַי, דְּעָאקוּ לְהוּ עַד הַשְׁתָּא. וּבְגִין כַּךְ אִתְדָּנוּ בִּתְרֵין דִּינִין, חַד בְּמַיָּיא, וְחַד בְּאֶשָּׁא. בְּמַיָּיא, דִּכְתִּיב, (שופטים ה׳:כ״א) נַחַל קִישׁוֹן גְּרָפָם. בְּאֶשָּׁא, דִּכְתִּיב הַכּוֹכָבִים מִמְּסִלּוֹתָם.</p>\n<p>וּבְאִינּוּן כֹּכָבַיָיא, אִית כֹּכָבָא חַד דְּלָא אָתָא לְהַהוּא נוּקְמָא, וְאִתְלַטְּיָּא לְעָלְמִין, דְּכַד שָׁארֵי לְאַנְהָרָא, אָתָאן שְׁאַר כֹּכָבַיָיא וּבַלְעִין לֵיהּ, וּלְכָל סִיעָתָא דִּילֵיהּ, וְאִתְאֲבִידוּ כֻּלְּהוּ כַּחֲדָא. כְּמָה דְאַתְּ אָמֵר, אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ יְיָ'. וְכִי רְשׁוּת אִית לְמַלְאָכָא בְּהַאי. אֶלָּא דָּא הוּא מַלְאָךְ, דִּכְתִּיב בֵּיהּ (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְדָא הוּא דְּכָל קְרָבִין דִּילֵיהּ אִינּוּן. <Nonei></i></p>\n<p><Nonei></i>כִּי לֹא בָאוּ לְעֶזְרַת יְיָ', כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. לְעֶזְרַת יְיָ' בַּגִּבּוֹרִים, בְּאִינּוּן שִׁשִּׁים גִּבּוֹרִים כַּד אִזְדְּמָנוּ קְרָבָא עִם סִיסְרָא. וְדָא מַלְאָךְ, רָזָא דְּכָל דִּינִין וְכָל קְרָבִין דְּמַלְכָּא בִּרְשׁוּתֵיהּ. וְעַל דָּא אָמַר, מַלְאַךְ יְיָ'. וְדָא הוּא דִּכְתִּיב, (בראשית מ״ח:ט״ז) הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי וְגוֹ', וְהָא אוּקְמוּהָ חַבְרַיָּא. וְדָא זְמִינָא לְמֶהֱוֵי עִלָּאָה וְיַקִּירָא לְזִמְנָא דְּאָתֵי. וּבְדָא יִתְרַבֵּי שְׁמָא קַדִּישָׁא. וּבְדָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְפָּרְעָא מֵעַמִּין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְעַל דָּא כְּתִיב, (יחזקאל ל״ח:כ״ג) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'. אַזְלוּ, עַד דְּמָטוּ לְגַבֵּיהּ דְּרַבִּי שִׁמְעוֹן. כֵּיוָן דְּחָמָא לוֹן, אָמַר רִבִּי שִׁמְעוֹן, הָא שְׁכִינְתָּא הָכָא. וַדַּאי צְרִיכִין אֲנָן לְמֶחְזָק טִיבוּ לְאַנְפֵּי שְׁכִינְתָּא.</p>"],[9520012669,"<p>פָּתַח וְאָמַר (בראשית כ״ט:ז׳) הֵן עוֹד הַיּוֹם גָּדוֹל וְגוֹ'. הַאי קְרָא אוֹקְמוּהָ, דְּכַד יִשְׂרָאֵל יִתְּעֲרוּן תְּשׁוּבָה לְקָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בִּזְכוּ אוֹרַיְיתָא יְתוּבוּן לְאַרְעָא קַדִּישָׁא, וְיִתְכַּנְּשׁוּן מִן גָּלוּתָא. דְּהָא וַדַּאי יוֹמָא חַד יְהֵא גָּלוּתָא לְיִשְׂרָאֵל, וְלָא יַתִּיר. הֲדָא הוּא דִכְתִיב, (איכה א׳:י״ג) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. וְאִי לָא יְתוּבוּן, קוּדְשָׁא בְּרִיךְ הוּא אָמַר, הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, בְּלָא זְכוּ וּבְלָא עוֹבָדִין דְּכַשְׁרָן. אֲבָל אַסְוָתָא חַד לְכוּ, הַשְׁקוּ הַצֹאן, אִשְׁתְּדָּלוּ בְּאוֹרַיְיתָא, דְּאִתְשַׁקְייוּ מֵימֵי אוֹרַיְיתָא. וּלְכוּ רְעוּ, לַאֲתָר דְּנַיְיחָא לַאֲתָר טָבָא וְכִסּוּפָא דְּאַחֲסַנְתֵּיכוֹן.</p>\n<p>דָּבָר אַחֵר הֵן עוֹד הַיּוֹם גָּדוֹל, דָּא הוּא יוֹם דְּאִקְרֵי (ישעיהו כ״ב:ה׳) יוֹם מְהוּמָה וּמְבוּסָה וּמְבוּכָה, דִּי בְּהַהוּא יוֹם אִתְחֲרִיב בֵּי מַקְדְּשָׁא, וְנָפְלוּ יִשְׂרָאֵל בְּגָלוּתָא. וּבְגִין עוֹבָדִין בִּישִׁין, הַהוּא יוֹמָא אִתְמְשַׁךְ וְאִתְרְבֵּי, הֲדָא הוּא דִכְתִיב הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, בְּגִין דְּאִינּוּן מַשְׁכִין לֵיהּ לְהַהוּא יוֹמָא. הַשְׁקוּ הַצֹּאן, כְּמָה דְּאִתְּמַר בְּמִלֵּי דְּאוֹרַיְיתָא, דְּהָא בִּזְכוּתָא דְּאוֹרַיְיתָא יִפְּקוּן יִשְׂרָאֵל מִן גָּלוּתָא.</p>\n<p>יִשְׂרָאֵל מַאי קָא אַמְרֵי. וַיֹּאמְרוּ לֹא נוּכַל עַד אֲשֶׁר יֵאָסְפוּ כָּל הָעֲדָרִים, עַד דְּיִתְכַּנְּשׁוּ כָּל שְׁאַר יוֹמִין עִלָּאִין. וְגָלְלוּ אֶת הָאֶבֶן, וְיִגַּנְדְּרוּן לְהַהוּא דִּינָא קַשְׁיָא דְּהַהוּא יוֹמָא דְּשַׁלְטָא עַל פִּי הַבְּאֵר, וְאִשְׁתְּכָחַת הַהִיא בְּאֵ\"ר בְּגָלוּתָא עִמָּנָא. וְכַד אִתְגַּלְיָיא הַאי בְּאֵ\"ר, וְהַהוּא אֶבֶן לָא שַׁלְטָא עָלָהּ, מִיַּד וְהִשְׁקִינוּ הַצֹּאן.</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא בְּסוֹף יוֹמַיָּיא, לְאָהַדְרָא לְיִשְׂרָאֵל לְאַרְעָא קַדִּישָׁא, וּלְאַכְנְשָׁא לוֹן מִגָּלוּתָא. וּמַאן אִינּוּן סוֹף יוֹמַיָּיא, הַהוּא דְּהִיא אַחֲרִית הַיָּמִים. בְּהַאי אַחֲרִית הַיָּמִים, יִשְׂרָאֵל סַבְלוּ גָּלוּתָא. הֲדָא הוּא דִכְתִיב, (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וּכְתִיב (דברים ל״א:כ״ט) וְקָרָאת אֶתְכֶם הָרָעָה בְּאַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים דַּיְיקָא, וְדָא הִיא כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא. וְעִם אַחֲרִית הַיָּמִים דָּא, קַבִּילוּ עוֹנְשָׁא בְּגָלוּתָא. וּבְדָא יַעְבִּיד קוּדְשָׁא בְּרִיךְ הוּא נוּקְמִין לְיִשְׂרָאֵל תְּדִירָא. הֲדָא הוּא דִכְתִיב, (במדבר כ״ד:י״ד) אֲשֶׁר יַעֲשֶׂה הָעָם הַזֶּה לְעַמְּךָ בְּאַחֲרִית הַיָּמִים. וּבְכָל אֲתָר דָּא הִיא, וְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְאָתָבָא לָהּ לְאַתְרָהָא, הֲדָא הוּא דִכְתִיב, (ישעיהו ב׳:ב׳) וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית יְיָ' וְגוֹ' וְדָא הוּא יוֹם.</p>\n<p>וּמִדְּשָׁארֵי צֵל לְמֶעְבַּד בְּשֵׁירוּתָא דְּיוֹמָא אָחֳרָא, כְּמָה בְּזִמְנָא דְּאִתְחֲרִיב מַקְדְּשָׁא הֲוָה, וְנָטָה צֵל לְמֵיעַל. הֲדָא הוּא דִכְתִיב, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָּנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. יוֹם וְצֵל, הוּא סוֹף גָּלוּתָא. וְשִׁיעוּרָא דְּהַאי צֵל, שִׁית קְמָצִין וּפַלְגָּא. וּבְגוּדָל דְּמִשְׁחָא דְּבַר נָשׁ, גְּבַר בֵּין גּוּבְרִין. וְדוּכְרָנָא דְּהַאי רָזָא דְּבֵין חַבְרַיָּיא, דִּכְתִּיב, (איוב ח׳:ט׳) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי תְמוֹל אֲנַחְנוּ בְּגָלוּתָא, וְלָא הֲוֵינָא יַדְעֵי כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ, לְאַשְׁרָאָה לוֹן קוּדְשָׁא בְּרִיךְ הוּא עֲלֵי אָרֶץ.</p>\n<p>זַכָּאָה חוּלָקֵיהּ מַאן דְּחָמֵי לֵיהּ, וְזַכָּאָה חוּלָקֵיהּ מַאן דְּלָא חָמֵי לֵיהּ. וַוי לְמַאן דְּיִזְדָּמַן כַּד יִתְבַּע אַרְיָא רַבְרְבָא, לְאִתְחַבְּרָא לְנוּקְבֵיהּ. כָּל שֶׁכֵּן בְּשַׁעֲתָא דְּיִזְדַּוְּוגֻן כַּחֲדָא, עַל הַהִיא שַׁעֲתָא כְּתִיב, (עמוס ג׳:ח׳) אַרְיֵה שָׁאָג מִי לֹא יִירָא וְגוֹ'.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב, (ירמיהו כ״ה:ל׳) שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וּבְהַהוּא זִמְנָא כַּד יִפּוּק לְקַבְּלָא לְבַת זוּגוֹ, כְּדֵין אַרְיֵה שָׁאָג מִי לֹא יִירָא יְיָ' אֱלֹהִים דִּבֶּר מִי לֹא יִנָּבֵא. בְּהַהִיא שַׁעֲתָא כְּתִיב, (דברים ל׳:ג׳) וְשָׁב יְיָ' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְגוֹ'. וְשָׁב מַאי הוּא, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא שָׁב כְּנֶסֶת יִשְׂרָאֵל מִגָּלוּתָא, וְשָׁב צַדִּיק לְאִזְדַּוְּוגָא <Nonei></i> בְּאַתְרֵיהּ. כְּדֵין כְּתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ.</p>"],[9520012670,"<p>מַתְנִיתִין, לְכוֹן בְּנֵי נָשָׁא, מָארֵי דְּחָכְמְתָא, מָארֵי דְּסֻכְלְתָנוּ, קָלָא קָרֵי. מַאן מִנְּכוֹן דְּאִתְחַכָּם וְיָדַע, בְּשַׁעֲתָא דְּרֵישָׁא חִיוָּורָא, אַתְקִין רֵישָׁא, רְשִׁימָא מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. אַתְקִין סְטָר צָפוֹן, בְּעִטּוּרָא דְּקוּנָארִיתָא, בֵּיהּ רָשִׁים עוּמְקָא דִּתְהוֹמָא עִלָּאָה, דְּסָלִיק וְנָחִית בְּגַוֵּויהּ. נָחִית חַד דַּרְגָּא טְמִירָא, בְּאֶלֶף וַחֲמֵשׁ מְאָה רְשִׁימִין, דְּאֶלֶף וַחֲמֵשׁ מְאָה עָלְמִין.</p>\n<p>(דניאל ד׳:ט׳) תְּחוֹתֵיהּ תַּטְלֵל חַד חֵיוַת בָּרָא, (דניאל ז׳:ז׳) וְקַרְנַיִן עֶשֶׂר לָהּ. וַאֲרוּ עַיְינִין כְּעַיְינֵי אֱנָשָׁא לְחֵיוָתָא, וּפוּם מְמַלֵּל רַבְרְבָן. כַּד סַלְּקָא, אַזְלַא בִּימָמָא, טְמִירָא בְּלֵילְיָא. כַּד נַחְתָּא, טְמִירָא בִּימָמָא, וְאַזְלָא בְּלֵילְיָא. כַּד נַטְלָא, מִזְדַּעְזְעָן אַרְבַּע מַגְרוֹפֵי דַּאֲחִידָן בִּידָהָא. וְנַטְלִין עִמָּהּ שִׁתִּין פּוּלְסִין דְּנוּרָא, כָּל חַד חַרְבָּא שִׁנָּנָא עַל יְרֵיכֵיהּ.</p>\n<p>סָלִיק בִּרְעוּתָא, לְאַפָּקָא בַּר נָשׁ שַׁלִּיטָא לְתַתָּא. אַתְקִין בְּהַאי חֵיוָתָא חַד עַפְרָא דְּקִיקָא, כָּלִיל מִכֹּלָּא. נָשַׁב בֵּיהּ, אִתְפְּשַׁט בְּד' סִטְרֵי עָלְמָא. וְד' פּוּלְסִין אִתְגַּלְגָּלוּ, חַד לְעֵילָּא, חַד לְתַתָּא, חַד לַצָּפוֹן, חַד לַדָּרוֹם.</p>\n<p>אִילָנָא חַד רַבְרְבָא וְתַקִּיף, אִתְחַבָּר וְאִזְדְּוַוג בָּהּ בְּחַד עַנְפָּא שַׁפִּירָא, דְּחֵזוּ חֶדְוָותָא דְּכֹלָּא. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. בֵּיהּ אִזְדְּוַוג, אַפִּיקוּ חַד רוּחָא טְמִירָא, וּמַלְיָא לְהַהוּא גְּבִילוּ דְּעַפְרָא, וְקָאִים עַל רַגְלוֹי, וְאַמְלְכֵיהּ עַל כָּל עָלְמָא, וְשַׁלְטֵיהּ עַל כֹּלָּא. הֲדָא הוּא דִכְתִיב, (תהילים ח׳:ז׳) תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךָ וְגוֹ'. אִתְפְּקִיד עַל הַהוּא אִילָנָא, לָא נָטַר פִּקּוּדָא, אָתִיב מַלְכָּא רוּחֵיהּ לְגַבֵּיהּ, וְהַהוּא חֵיוָתָא נַטְלָא לֵיהּ.</p>\n<p>כְּדֵין זְמִינִין מָנָא אַחֲרָא, וְקָאִים בֵּינַיְיהוּ. בְּקוּטְרָא דִּגְלִיפִין בֵּין מַלְאָכִין קַדִּישִׁין, בְּטוּפְסְרָא (ס\"א בטפסא) דְּעִטּוּרִין אִתְאַחֲדָן.</p>\n<p>דָּרִין בַּתְרָאִין, תְּפִיסִין בְּחוֹבַיְיהוּ. אִשְׁתְּלִיף רוּחֵיהוֹן מֵהַהוּא מָאנָא דִּלְבוּשָׁא, לְבָתַר אַגְנִיז בְּעַפְרָא, בֵּין רִגְבֵי נַחֲלָא אִתְטְמָרוּ וְאִתְגְּנִיזוּ. בְּחַד גַּרְמָא תַּקִּיף דְּהַהוּא מָאנָא, יִתְבְּנוּן בְּקַדְמִיתָא, וִיקוּמוּן חֵילִין חֵילִין תִּנְיָינוּת, בְּאַרְעָא קַדִּישָׁא מִתְעָרִין.</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְמִגְבַּל הַהוּא עַפְרָא קַדְמִיתָא, דְּהַהוּא מָאנָא מַמָּשׁ. וּלְאַעֲלָא בֵּיהּ גְּבִילוּ דָּקִיק כְּהַאי חֲמִירָא דְּעִיסָה. וּמֵהַהוּא גְּבִילוּ דְּאִיהוּ צָחוּתָא דִּלְעֵילָּא, יִתְתָּקַּן וְיִתְיְשַׁר מָאנָא דְּכַשְׁרָא. כְּגַוְונָא דְּאָמַר קְרָא, (יואל ד׳:י״ח) וּמַעְיָן מִבֵּית יְיָ' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִׁטִּים. בְּגִין דְּהַהוּא נַחַל אַסְגֵּי חֲבִיבוּתָא (ס\"א זכותא) (ס\"א זנותא) בְּעָלְמָא. וְכַד הַהוּא מַעְיָינָא קַדִּישָׁא, יִפּוּק וְיֵיעוּל לְגַבֵּיהּ, כְּדֵין יִתְתָּקַּן וְיִתְיְשַׁר, וְלָא יְהֵא בְּסוּרְחָנֵיהּ כְּקַדְמִיתָא.</p>\n<p>וְאִינּוּן דְּלָא זָכָּאן, יְקוּמוּן לְאִתְדְּנָא בְּדִינָא דְּמַלְכָּא עִלָּאָה. הֲדָא הוּא דִכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם. וּכְדֵין כְּתִיב, (ישעיהו ס״ו:כ״ב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עוֹשֶׂה עוֹמְדִים לְפָנַי נְאֻם יְיָ' כֵּן יַעֲמוֹד זַרְעֲכֶם וְשִׁמְכֶם. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן</p>"],[9520012671,"<p><Noneb>רעיא מהימנא</b><br>וְהָיָה עֵקֶב תִּשְׁמְעוּן אֵת הַמִּשְׁפָּטִים הָאֵלֶּה וְגוֹ', וְאָכַלְתָּ וְשבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ וְגוֹ'. פִּקוּדָא (י\"ח) דָּא לְבָרְכָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַל כָּל מַה דְּאָכִיל וְשָׁתֵי, וְאִתְהֲנֵי בְּהַאי עָלְמָא. וְאִי לָא בָּרִיךְ, אִקְרֵי גַּזְלָן לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב, (משלי כ״ח:כ״ד) גּוֹזֵל אָבִיו וְאִמּוֹ. וְהָא אוֹקְמוּהָ חַבְרַיָּיא. בְּגִין דְּבִרְכָּאן דְּבָרִיךְ בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, אָתֵי לְאַמְשָׁכָא חַיִּין מִמְּקוֹרָא דְּחַיֵּי, לִשְׁמֵיהּ (קדישא) דְּקוּדְשָׁא בְּרִיךְ הוּא קַדִּישָׁא, וּלְאַרְקָא עָלֵיהּ מֵהַהוּא מִשְׁחָא עִלָּאָה, וְאָתֵי לְאִתְמַשְּׁכָא מִתַּמָּן לְכָל עָלְמָא.</p>\n<p>וּכְתִיב וְאָכַלְתָּ וְשָבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ <Nonei></i> וְאִינּוּן בִּרְכָאן, אָרִיק בַּר נָשׁ בְּאִינּוּן מִלִּין מֵהַהוּא מְקוֹרָא עִלָּאָה, וְאִתְבָּרְכָאן כָּל אִינּוּן דַּרְגִּין וּמְקוֹרִין, וְאִתְמַלְּיָין לְאַרְקָא עַל כָּל עָלְמִין. וְאִתְבָּרְכָאן כֻּלְּהוּ כַּחֲדָא.</p>\n<p>וְעַל דָּא אִצְטְרִיךְ בַּר נָשׁ, לְשַׁוָּאָה רְעוּתֵיהּ בְּרָזָא דְּבִרְכָּאן, בְּגִין דְּיִתְבָּרְכוּן אֲבָהָן וּבְנִין, כֹּלָּא כַּחֲדָא. וּמַאן דִּמְבָרֵךְ לְקוּדְשָׁא בְּרִיךְ הוּא, אִתְבְּרַךְ, וְנָטִיל חוּלָקֵיהּ מֵאִינּוּן בִּרְכָאן בְּקַדְמִיתָא דְּכָל עָלְמָא לְתַתָּא. כֵּיוָן דִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא מִתְבָּרֵךְ מִתַּמָּן, נָחִית וְשָׁרָא עַל רֵישֵׁיהּ חוּלָקָא קַדְמָאָה. וְהָא אוֹקִימְנָא דִּכְתִּיב, (שמות כ׳:כ״א) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי אָבֹא אֵלֶיךָ וּבֵרַכְתִּיךָ. (אזכיר כמה דאת אמר (תהלים כ) יזכור כל מנחותיך) כֵּיוָן דְּהַהִיא בְּרָכָה אַתְיָיא וְשַׁרְיָיא עַל רֵישֵׁיהּ, מִתַּמָּן אִתְפְּשַׁט בְּכָל עָלְמָא.</p>\n<p>בְּשַׁעֲתָא דְּאִינּוּן בִּרְכָאן נַחְתִּין, מִתְעַטְּרָן גּוֹ חֲקַל תַּפּוּחִין קַדִּישִׁין, וּפַגְעֵי בְּהוּ כַּמָה דַּרְגִּין דִּמְמָנָן בְּעָלְמָא, וְנַחְתֵּי בְּהוּ, וְאַמְרֵי וּמַכְרִיזֵי דָּא אִיהוּ דּוֹרוֹנָא דְּשָׁדַר פְּלוֹנִי לְקוּדְשָׁא בְּרִיךְ הוּא. מֵאָן אֲתָר נַחְתֵּי, לְבָתַר דְּנַחְתֵּי מֵאֲתָר רֵישָׁא חֲדָא דְּצַדִּיק. תַּמָּן סַלְּקִין, מִתְעָרֵי לְנַחְתָּא אַחֲרָנִין מִלְּעֵילָּא, וְאִתְמַלְּיָיא מִלְּעֵילָּא וּמִתַּתָּא, הֲדָא הוּא דִכְתִיב (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק. כֵּיוָן דְּהַאי דַּרְגָּא אִתְמַלְּיָיא, אָרִיק לְהַאי כַּלָּה, וּמִתַּמָּן נַגְדִּין וְאִתְמַשְּׁכָן לְתַתָּא.</p>\n<p>כַּד סַלְּקִין אִינּוּן בִּרְכָאן מִתַּתָּא, לֵית פִּתְחָא וּפִתְחָא לְעֵילָּא, וְלֵית מְמָנָא לְעֵילָּא, דְּלָא פָּתַח כָּל אִינּוּן פִּתְחִין. וּמַכְרִזֵי וְאַמְרֵי בְּכָל אִינּוּן רְקִיעִין, דָּא אִיהוּ דּוֹרוֹנָא דְּמַלְכָּא דְּשָׁדַר פְּלוֹנִי, דָּא הוּא דּוֹרוֹנָא בְּקִיּוּמָא כַּדְּקָא יָאוּת. וּמַאן אִיהוּ. בְּרָכָה דְּאָתִיבוּ עָלֵיהּ אָמֵן. דְּכָל בְּרָכָה דְּאָתִיבוּ עָלֵיהּ אָמֵן, דָּא אִיהוּ בְּקִיּוּמָא כַּדְּקָא יָאוּת.</p>\n<p>וְכֵיוָן דְּהַאי בִּרְכָתָא סַלְּקָא, כָּל דַּרְגִּין דִּלְעֵילָּא, כֻּלְּהוּ זְמִינִין לְגַבֵּי הַהוּא נְהוֹרָא דְּלָא נָהִיר, בְּגִין לְאַנְהָרָא לְגַבָּהּ. וְכָל שֶׁכֵּן אִי הִיא בִּרְכָתָא דְּסַגִּיאִין מְבָרְכָן לָהּ, וּמְעַטְּרִין לָהּ בְּעִטְרִין קַדִּישִׁין, (עיין לקמן סוד אמן רפ\"ה ע\"א) בְּרָזָא דְּאָמֵן. אָמֵן הוּא רָזָא דְּקִשְׁרֵי, דְּכָל יִחוּדָא וּקְדוּשָׁה בְּרָזָא דְּמָארֵיהּ. וּמְעַטֵּר לְהַהִיא בִּרְכָתָא בְּעִטְרִין עִלָּאִין כַּדְּקָא יָאוּת.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, בְּאִינּוּן דִּמְבָרְכִין לֵיהּ, וְתִיאוּבְתֵיהּ בְּבִרְכָתָא דִּלְתַּתָּא, דְּהַהִיא בִּרְכָתָא סַלְּקָא, וְאַנְהִיר בּוּצִינָא דְּלָא נָהִיר, וְאַתְקִיף לָהּ בְּתּוּקְפָא תַּקִּיפָא, לְסַלְּקָא לְעֵילָּא. וְעַל רָזָא דָּא כְּתִיב, (שמואל א ב׳:ל׳) כִּי מְכַבְּדַי אֲכַבֵּד, אִלֵּין אִינּוּן דִּמְבָרְכִין לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וּבוֹזַי יֵקָלּוּ, אִלֵּין אִינּוּן דְּלָא מְבָרְכִין לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וּמַנְעִין בִּרְכָתָא מִפּוּמַיְיהוּ.</p>\n<p>רָזָא דְּרָזִין, לְאִינּוּן דְּיַדְעֵי חָכְמְתָא דְּמָארֵיהוֹן, לְמִנְדַּע רָזָא דְּבִרְכָּאן, בְּפִקּוּדֵי אוֹרַיְיתָא, וּבְכָל הַנָאִין וְכִסּוּפִין דְּהַאי עָלְמָא, לְאַרְקָא בִּרְכָאן מֵעֵילָּא לְתַתָּא.</p>\n<p>כַּד (ס\"א בר) בִּרְכָאן דִּצְלוֹתָא, דְּאִינּוּן תִּקּוּנָא דְּמָארֵיהוֹן, מִתַּתָּא לְעֵילָּא וּמֵעֵילָּא לְתַתָּא. בִּרְכָאן דְּלָאו אִינּוּן בִּצְלוֹתָא, סַלְּקִין מִתַּתָּא לְעֵילָּא, עַד דְּמָטוּ גּוֹ נְהוֹרָא דְּלָא נָהִיר, וּמִתְעָרֵי (לעילא) בְּתּוּקְפָא, לְהַהוּא נְהוֹרָא דְּלָא נָהִיר, בְּהַהִיא בְּרָכָה, וְסַלְּקָא אִתְּעֲרוּ לְעֵילָּא, עַד דְּמָטוּ לְכֻרְסַיָיא עִלָּאָה, מְקוֹרָא דְּכָל חַיִּין. כְּדֵין נָפְקוּ מֵהַהוּא מְקוֹרָא עִלָּאָה, בִּרְכָאן אַחֲרָנִין, וְאִעֲרָעוּ אִלֵּין בְּאִלֵּין, וְנַשְּׁקֵי אִלֵּין לְאִלֵּין, וְאָתָאן וְשַׁרְיָין לְרֵישׁ צַדִּיק, לְאַרְקָא לְתַתָּא. וְכַד נַחְתִּין, אִתְבָּרְכָן אֲבָהָן וּבְנִין, וְכָל שְׁרָגִין דִּלְהוֹן.</p>\n<p>וְרָזָא דְּאִלֵּין בִּרְכָאן לְאַתְּעָרָא מֵעֵילָּא לְתַתָּא, בְּרָזָא דָּא, בָּרוּךְ: דָּא רָזָא דִּמְקוֹרָא עִלָּאָה מִכֹּלָּא, לְאַרְקָא וּלְאַמְשָׁכָא וּלְאַנְהֲרָא כָּל בּוֹצִינִין. וְאִיהוּ בָּרוּךְ (נ\"א בריך) תָּדִיר, דְּלָא פַּסְקִין מֵימוֹי. וּמִתַּמָּן שֵׁירוּתָא דְּאִקְרֵי עָלְמָא דְּאָתֵי, וְאִיהוּ קְצֵה הַשָּׁמַיִם, דְּהַהוּא קָצֶה, קָצֶה עִלָּאָה אִיהוּ. בְּגִין דְּאִית קָצֶה כְּגַוְונָא דָּא לְתַתָּא, וְאִיהוּ עָלְמָא תַּתָּאָה. וְאִקְרֵי אוּף הָכִי בָּרוּךְ, לָקֳבֵל תַּתָּאֵי, לְאַרְקָא לְתַתָּא, וּלְאִתְעֲרָא מִתַּתָּא לְעֵילָּא בְּבִרְכָּאן דִּצְלוֹתָא. וּבָרוּךְ (קדמאה) דָּא אִקְרֵי הָכָא, בְּרָזָא דְּחָכְמְתָא עִלָּאָה, דְּאַמְלֵי לְהַהוּא אֲתָר, בְּחַד שְׁבִיל דָּקִיק דְּאָעִיל בֵּיהּ.</p>\n<p>אַתָּה: לְבָתַר שָׁארֵי לְאִתְגַּלְיָיא, דְּהָא הַאי בָּרוּךְ סָתִים אִיהוּ, וּבְּגִין כָּךְ אִקְרֵי בְּאֹרַח סָתִים בָּרוּךְ, מְקוֹרָא עִלָּאָה דְּלָא אִתְגַּלְיָיא. אַתָּה, שִׁירוּתָא לְאִתְגַּלְיָיא לְבַר, וּבְּגִין כָּךְ אִקְרֵי אַתָּה. וּמַאן אִיהוּ. דָּא רָזָא דִּימִינָא, וְאִקְרֵי כֹּהֵן לְגַבֵּי הַהוּא אֲתָר. וְרָזָא דָּא (תהילים ק״י:ד׳) אַתָּה כֹהֵן לְעוֹלָם, מַאן כֹּהֵן לְהַהוּא עוֹלָם, אַתָּה. וְדָא אִיהוּ יְמִינָא עִלָּאָה, דְּהָא אִשְׁתְּכַח לְאִתְגַּלְיָיא.</p>\n<p>יְהוָֹה: דָּא רָזָא דְּאֶמְצָעִיתָא. רָזָא דִּמְהֵימְנוּתָא בְּכָל סִטְרִין. <Nonei></i> אֱלֹהֵינוּ: דָּא סִטְרָא דִּשְׂמָאלָא, דְּכָלִיל בִּימִינָא, וִימִינָא בֵּיהּ, וְאִתְכְּלִילוּ דָּא בְּדָא, לְמֶהֱוֵי חַד. וְעַד הָכָא, אִתְקְשָּׁרוּ בִּרְכָאן, דְּכֵיוָן דְּאִלֵּין אִתְבָּרְכָאן, כֻּלְּהוֹן דִּלְתַּתָּא אִתְבָּרְכָאן.</p>\n<p>לְבָתַר דְּאִינּוּן אִתְבָּרְכָאן, וְנַטְלֵי בִּרְכָאן לְגַרְמַיְיהוּ, אִתְהֲדָרוּ כְּלִילָן כְּחַד לְהַהוּא מְקוֹרָא, דְּאִינּוּן לָא יַכְלִין לְאִתְהַדְרָא לְגַבֵּי הַהוּא אֲתָר, עַד דְּאִתְבָּרְכָן. כֵּיוָן דְּאִתְבָּרְכָן בְּקַדְמִיתָא, אִתְהֲדָרוּ וְעָאלִין לְגַבֵּי הַהוּא אֲתָר, לְנַטְלָא בִּרְכָאן יְתֵירִין אַחֲרָנִין, לְאַרְקָא לְתַתָּא. וְעַד דְּאִינּוּן אִתְבָּרְכָאן, לָא עָאלִין וְלָא תָּאָבִין לְגַבֵּיהּ. וְרָזָא דָּא (שמות כ״ג:ט״ו) וְלֹא יֵרָאוּ פָנַי רֵיקָם.</p>\n<p>וְכַד תָּבִין לְגַבֵּי הַהוּא אֲתָר, וְעָאלִין תַּמָּן, כְּדֵין אִקְרֵי הַהוּא אֲתָר מֶלֶךְ. וּמֶלֶךְ לָא אִתְקְרֵי, בַּר כַּד אִינּוּן מִתְקָרְבִין לְגַבֵּיהּ, וּמִתְבָּרְכָן. וּמַלְכָּא אֵימָתַי אִקְרֵי מֶלֶךְ. כַּד רַבְרְבָנוֹי אַתְיָין לְגַבֵּיהּ עֲתִירִין, מִסְתַּפְּקָן בְּכָל מַה דְּאִצְטְרִיכוּ, בְּלָא חֶסְרוֹנָא, כְּדֵין אִיהוּ מֶלֶךְ. מֶלֶךְ לְתַתָּא, כַּד אִלֵּין מְעַטְּרָן לֵיהּ בְּסִפּוּקָא, בְּעִטְרִין קַדִּישִׁין. וְהָכָא אִקְרֵי מֶלֶךְ. וּמַאן אִיהוּ. הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ וְצִוָנוּ. וּבְגִין דְּאִיהוּ עָלְמָא דְּלָא אִתְגַּלְיָיא לְבַר, וְאִיהוּ סָתִים, קָרֵי לֵיהּ הָכִי בְּאֹרַח סָתִים. וְעַל דָּא לָא אִקְרֵי, אֶלָּא בְּאֹרַח סָתִים.</p>\n<p>וּלְעוֹלָם יְמִינָא אַתָּה, כְּמָה דְּאִתְּמַר. וְעַל דָּא כֹּהֵן, כָּפִיף לְגַבֵּי הַהוּא אֲתָר, בְּרֵישָׁא וּבְסוֹפָא. וְעָלְמָא תַּתָּאָה, כַּד אִתְקָשַׁר לִימִינָא, וְאִתְדַּבָּק בֵּיהּ, קָרֵי מִתַּתָּא לְעֵילָּא בָּרוּךְ, וְלָא אִקְרֵי בָּרוּךְ, בַּר בְּרָזָא דִּמְקוֹרָא דְּאִתְדְּבַק בַּהֲדֵיהּ (ביה), וְעָיִּיל בֵּיהּ, וְאַמְלֵּי לֵיהּ. אַתָּה, רָזָא דְּהַהוּא כֹּהֵן, לְאִתְדַּבְּקָא בַּהֲדֵיהּ, וְעַל דָּא, בִּצְלוֹתָא בַּר נָשׁ כּוֹרֵעַ בְּבָרוּך, דְּאִיהוּ עָלְמָא כָּפוּף לְגַבֵּי עֵילָּא, וְדָא אִיהוּ שִׁנּוּי בֵּין בָּרוּךְ דִּצְלוֹתָא, וּבֵין בָּרוּךְ דִּשְׁאַר בִּרְכָאן. וְכֹלָּא בְּרָזָא עִלָּאָה אִיהוּ, לְאַרְקָא בִּרְכָאן לְכָל עָלְמִין.</p>\n<p>בָּרוּךְ דִּצְלוֹתָא, בַּר נָשׁ כּוֹרֵעַ בֵּיהּ בְּבִרְכּוֹי, וְגָחִין רֵישָׁא בְּאַתָּה, בְּגִין דְּאַתָּה אִקְרֵי רֹאשׁ. וְעַל דָּא כֹּהֵן נָטִיל בָּרֹאשׁ, וְאִיהוּ רֹאשׁ תָּדִיר. וּבְּגִין כָּךְ כְּרִיעָה בְּבָרוּך. וְגָחִינוּ דְּרֵישָׁא בְּאַתָּה. וְכֹהֵן בְּכָל אֲתָר דְּאִקְרֵי אַתָּה, גָּחִין בִּצְלוֹתָא. מֶלֶךְ בָּתַר דְּגָחִין, תּוּ לָא זָקִיף, מַאי טַעְמָא. קוּדְשָׁא בְּרִיךְ הוּא אָמַר לָהּ לְסִיהֲרָא, זִילִי אַזְעִירִי גַּרְמִיךְ, וְתוּ לָא זַקְפָא. וּבְגִין דָּא, בִּרְכָתָא דְּבַּר נָשׁ בָּרִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא, אִתְּעַר לְאַרְקָא בִּרְכָאן מִלְּעֵילָּא לְעָלְמִין כֻּלְּהוּ, כְּמָה דְּאִתְּמַר. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>כְּתִיב, (ישעיהו ס״ג:ט״ז) כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם וְגוֹ'. תָּנֵינָן, לְזִמְנָא דְּאָתֵי אַמְרִין לֵיהּ לְיִצְחָק וְכוּ', בְּגִין דִּשְׂמָאלָא אִתְכְּלִיל בִּימִינָא, אֲבָל יְמִינָא מְנָלָן דְּאִקְרֵי אָב. דִּכְתִּיב וַיְּשִׂמֵהוּ לוֹ לְאָב וּלְכֹהֵן, וְאַף עַל גַּב דִּלְעֵילָּא אִקְרֵי אָב, וַאֲפִילּוּ לִנְהוֹרָא דְּלָא נָהִיר בְּשַׁעֲתָא דְּאִתְדְּבַק בִּימִינָא אִקְרֵי אַתָּה, כְּמָה דְאַתְּ אָמֵר (שם) אַתָּה יְיָ' אָבִינוּ גּוֹאֲלֵנוּ וְגוֹ'.</p>\n<p>אַדְּהָכִי, סָבָא אִזְדְּמַן לְגַבֵּיהּ, וְאָמַר, רַעְיָא מְהֵימָנָא, תַּקִּין פָּתוֹרָא לְמָארָךְ, לֵיהּ וּלְמָטְרוֹנִיתָא. מִכָּל מִינֵי עִדּוּנִין, לְקַיְּימָא בֵּיהּ (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ'. וְהָא עַד כְּעַן כֻּלְּהוּ מִתְעַנְּגֵי מִפָּתוֹרָא דְּמַלְכָּא. הֲדָא הוּא דִכְתִיב, (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְּלַחְמִי. וְדָא נַהֲמָא דְּאוֹרַיְיתָא דְּבִכְתָב, וְיֵינָא דְּאוֹרַיְיתָא דִּבְעַל פֶּה. וְתַמָּן כַּמָה מַטְעַמִּים מִינֵי טַעֲמֵי תּוֹרָה, דִּמְתִּיקִין, מִכָּל מַאֲכָלִין וְעִדּוּנִין דְּעָלְמָא, וּדְמַלְכָּא.</p>\n<p>קָם רַעְיָא מְהֵימָנָא פָּתַח וְאָמַר, אַהֲרֹן כַּהֲנָא קוּם מִשֵּׁינָתָךְ, לְמִדְבַּח תּוֹרִין וְעָאנִין וְאִמְרִין וְעוֹפִין, וְכָל מִינִין דִּצְרִיכִין לִסְעוּדָתָא דְּמַלְכָּא. וְלֶחֶם הַפָּנִים, דְּאִינּוּן לָקֳבֵל תְּרֵין לוּחֵי דְּאוֹרַיְיתָא, (שמות ל״ב:ט״ו) דְּמִזֶּה וּמִזֶּה הֵם כְּתוּבִים. זֶה: תְּרֵיסָר אַנְפִּין. דְּאִינּוּן: (במדבר ו) יְבָרֶכְךָ יְיָ', יָאֵר יְיָ', יִשָּׂא יְיָ'. זֶה תִּנְיָינָא, אֲדֹנָ\"י אֲדֹנָ\"י אֲדֹנָ\"י. דְּאִינּוּן תְּרֵיסָר חֵיוָן, דְּאִתְּמַר בְּהוֹן, (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּן, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן, וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וְאִתְּמַר עָלַיְיהוּ, (שם) אַרְבָּעָה פָּנִים לְאֶחָת (להם). וְהַאי אִיהוּ, (ישעיה ו) וְקָרָא זֶה אֶל זֶה וְאָמַר, לָקֳבֵל עֶשְׂרִים וְאַרְבַּע סִפְרֵי תּוֹרָה. וְהַאי אִיהוּ זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ'. מָאנִין דְּפָתוֹרָא דְּמַלְכָּא, אִינּוּן מָארֵי מַתְנִיתִין, מָארֵי צְלוֹתִין, דְּתָקִינוּ לוֹן לָקֳבֵל קָרְבְּנִין.</p>"],[9520012672,"<p>פָּתַח וְאָמַר, (שמות כ״ה:כ״ג) וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. תָּא חֲזִי, מִנְהָגִין טָבִין וְשַׁפִּירָן הֲווֹ נַהֲגֵי מָארֵי דִּסְעוּדָתָא דְּמַלְכָּא, לְאַחֲזָאָה דְּאִינּוּן מִבְּנֵי פָּתוֹרָה דְּמַלְכָּא. חַד (חדא), רַבְרְבָא מִבְּנֵי סְעוּדָתָא, נָטִיל יְדוֹי בְּזִמְנָא דְיֵיעַלוּן (דייעול) לִסְעוּדָתָא לְהָסֵב, גָּדוֹל מֵסֵב בָּרֹאשׁ, תִּנְיָינָא תְּחוֹתֵיהּ, וּתְלִיתָאָה תְּחוֹת תִּנְיָינָא. וְאִלֵּין אִתְקְרִיאוּ ג' מִטּוֹת, לָקֳבֵל תְּלַת אֲבָהָן, וְלָקֳבֵל <Nonei></i> כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים. מִכָּאן וְאֵילָךְ, לֵית לוֹן סֵדֶר, אֶלָּא כָּל הַקּוֹדֵם זָכָה.</p>\n<p>תִּנְיָינָא, בַּעַל הַבַּיִת בּוֹצֵעַ, כְּדֵי שֶׁיִבְצַע בְּעַיִן יָפָה. וּמַשְׁלִים בִּרְכָתָא, וּלְבָתַר בּוֹצֵעַ. וְאוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, דְּאֵין הַמְסוּבִּין רַשָׁאִין לִטְעוֹם, עַד שֶׁיִטְעוֹם הַמְּבָרֵךְ. וְלֵית הַבּוֹצֵעַ רַשָׁאי לִטְעוֹם, עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַמְסוּבִּין. וְאִם רְעוּתֵיהּ לְחַלֵּק כָּבוֹד, הָרְשׁוּת בִּידֵיהּ. וְעוֹד אוֹקְמוּהָ, דְּאוֹרֵחַ מְבָרֵךְ, בְּגִין דִּיבָרֵךְ לְבַעַל הַבַּיִת.</p>\n<p>וְאֹרַח רָזָא, בַּעַל הַבַּיִת בּוֹצֵעַ, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ קַו הָאֶמְצָעִי. וּבְשַׁבָּת צָרִיךְ לִבְצוֹעַ מִשְּׁנֵי כִּכָּרוֹת, דְּאִינּוּן ה' ה'. בַּעַל הַבַּיִת, דָּא ו' דְּאֶמְצָעִיתָא. (וכגוונא דא ובגין דא) וּבְגִין דְּלָא לְאִתְחֲזָאָה כְּרַעַבְתָּנוּתָא, יָכִיל לְמִבְצַע בָּהּ לְכָל חַד וְחַד כַּבֵּיצָה. מַאי כַּבֵּיצָה. י' וְי'. אִינּוּן נְקוּדִין דִּשְׁמָא קַדִּישָׁא, אִתְקְרֵי פִּרוּרֵי בְּכַזַּיִת. וְאִלֵּין לָקֳבֵל טִפִּין דְּזֶרַע, וּמַאן דִּמְזַלְזֵל בְּהוֹן, וְזָרִיק לוֹן בַּאֲתָר דְּלָא אִצְטְרִיךְ, עֲנִיּוּתָא קָא רָדִיף אֲבַּתְרֵיהּ, וְאָזִיל נָע וָנָד. הֲדָא הוּא דִכְתִיב, (איוב ט״ו:כ״ג) נוֹדֵד הוּא לַלֶּחֶם אַיֵּה. וְלֵית לֶחֶם אֶלָּא תּוֹרָה, וְהוּא צווֵֹחַ אַיֵּה מַאן דִּמְרַחֵם עָלֵיהּ, וְלָא יִשְׁכַּח.</p>\n<p>וּפִרוּרִים בְּכַזַּיִת, אִינּוּן בְּצַדִּיק, דְּאִיהוּ כַּתִישׁ כְּתִישׁוּ מֵאִינּוּן זֵיתִים. וְאוֹרֵחַ מְבָרֵךְ, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק חַי עָלְמִין, וּבְגִין דָּא אוֹרֵחַ מְבָרֵךְ.</p>"],[9520012673,"<p>אַדְּהָכִי, הָא בּוּצִינָא קַדִּישָׁא אָתָא לְגַבֵּיהּ. וְאָמַר, רַעְיָא מְהֵימָנָא, יוֹמָא חַד אֲזִילְנָא אֲנָא וְחַבְרַיָּיא לְאַכְסַנְיָא חֲדָא, וַהֲוָה תַּמָּן יַנוּקָא חֲדָא. קָם וְתָקִין לָן מְנַרְתָּא וּפָתוֹרָא אִיהוּ מִגַּרְמֵיהּ, כְּאִלּוּ הֲוָה מֵעֶשְׂרִין שְׁנִין, וְלָא הֲוָה אֶלָּא מִבֶּן חָמֵשׁ שְׁנִין. וְתָקִין פָּתוֹרָא מִכָּל מִינֵי מַאֲכָל וּמִשְׁתֶּה. אָמַר, הָא אוֹקְמוּהָ רַבָּנָן דְּבַעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ, אֲבָל (איוב ל״ב:ו׳) צָעִיר אֲנִי לְיָמִים וְאַתֶּם יְשִׁישִׁים עַל כֵּן זָּחַלְתִּי וָאִירָא מֵחַוּוֹת דֵּעִי אֶתְכֶם. עַד דְּאֶטּוֹל רְשׁוּת מִכֶּם. אָמַר לֵיהּ, אֵימָא בְּרִי מַלְאָכָא דַּיְיָ'.</p>\n<p>אָמַר לָן, אַתּוּן בָּעִיתוּן לֶחֶם תַּפְנוּקֵי בְּלָא קְרָבָא, אוֹ לֶחֶם בִּקְרָבָא. דְּהָכִי אוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, שְׁעַת אֲכִילָה שְׁעַת מִלְחָמָה. וְאִי בָּעִיתוּ לְמֶהֱוֵי קְרָבָא עָלֵיהּ, לֵית חַד אָכִיל, אֶלָּא מַאן דְּנָצַח קְרָבָא, אִיהוּ אָכִיל וּבוֹצֵעַ לְכֻלְּהוּ. אָמְרוּ לֵיהּ חַבְרַיָּיא, בְּרִי אַנְתְּ זְעֵיר, וַעֲדַיִין לָא יַדְעַת אֵיךְ מְגִיחֵי גַּבְרִין רַבְרְבִין בְּחַרְבָּא, בְּנִעְנוּעָ דְּחַרְבָּא. בְּרוֹמְחָא, בְּקַשְׁתָּא, בְּגִירִין דְּקַשְׁתָּא, בְּקִירְטָא, בְּאַבְנִין דְּקִירְטָא.</p>\n<p>אָמַר לְהוּ, (מלכים א כ׳:י״א) אַל יִתְהַלֵּל חוֹגֵר כִּמְפַתֵּחַ. דְּהָא וַדַּאי בְּקְרִיאַת שְׁמַע אוֹקְמוּהָ, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע עַל מִטָּתוֹ, כְּאִילּוּ אוֹחֵז חֶרֶב פִּיפִיּוֹת, דִּכְתִּיב, (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. וְנִעְנוּעָא דְּחַרְבָּא, צָרִיךְ לְנַעְנְעָא לֵיהּ לְשִׁית סִטְרִין, כְּמָה דְּאוּקְמוּהָ, כְּדֵי שֶׁתַּמְלִיכוּהוּ עַל הַשָּׁמַיִם וְעַל הָאָרֶץ, וְעַל ד' רוּחוֹת הָעוֹלָם. וְדָא ו', גּוּף הַחֶרֶב. י', רֹאשׁ הַחֶרֶב. ה\"ה, תְּרֵי פִּיּוֹת. נַרְתְּקָא דְּחַרְבָּא, אֲדֹנָי.</p>\n<p>רוּמְחָא, רמ\"ח בְּקְרִיאַת שְׁמַע, עִם שִׁית תֵּיבִין דְּיִחוּדָא, הָא רוֹמַ\"ח. מָגֵ\"ן עִם חַרְבָּא, מִיכָאֵל גַּבְרִיאֵל נוּרִיאֵל שַׁמָּשִׁין דְּג' אֲבָהָן. קֶשֶׁת דְּזָרִיק חִצִּים, וְכָל זֶרַע דְּאֵינוֹ יוֹרֶה כַּחֵץ אֵינוֹ מוֹלִיד. קִירְטָא, דָּא קְרִיאַת שְׁמַע. ה' אֲבָנִין דְּקִירְטָא, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ'. לָקֳּבְלַיְיהוּ, (שמואל א י״ז:מ׳) וַיִּקַּח דָּוִד חֲמִשָּׁה חַלּוּקֵי אֲבָנִים מִן הַנַּחַל. וְכַד שַׁוֵּי לְהוֹן בְּקִירְטָא, דְּאִיהִי שָׂפָה, וְאִיהִי שְׁכִינְתָּא, אִתְעָבִידוּ חַד כֻּלְּהוּ ה', וְקָטִיל לִפְלִשְׁתָּאָה.</p>\n<p>וְעַד כְּעַן זָרִיקְנָא הַאי אַבְנָא לְסָמָאֵל, דְּאִיהוּ אֶבֶן מָצוֹר, וְהָרַסְנָא מָצוֹר דִּילֵיהּ, וְאַשְׁפַּלְנָא לֵיהּ לְתַתָּא. וּבְגִין דָּא אֲמֵינָא לְכוֹן, אַל יִתְהַלֵּל חוֹגֵר כִּמְפַתֵּחַ. כְּעַן יִתְבָּרֵר לְכוֹן, דַּאֲנָא יְדַעְנָא אֵיךְ מַגִיחִין גֻּבְרִין רַבְרְבִין בְּסַיְיפִין, בְּרוּמְחָא, בְּקַשְׁתָּא, בְּקִירְטָא. תַּוַּוהְנָא וְלָא יָכִילְנָא לְמַלְּלָא קַמֵּיהּ, אָמְרוּ לֵיהּ רַבָּנָן, כְּעַן נֶחֱזֵי מַאן יְהֵא מָרְוָוח נַהֲמָא, דְּאִיהוּ לֶחֶם הַמּוֹצִיא.</p>\n<p>פָּתַח וְאָמַר, (במדבר ט״ו:י״ט) וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ תָּרִימוּ תְּרוּמָה לַיְיָ'. בְּמַאי (נ\"א בהאי) אַתְרִימָת שְׁכִינְתָּא, דְּאִיהִי ה' דְּהַמּוֹצִיא, דְּאוֹקִימוּ עָלָהּ מָארֵי מַתְנִיתִין, כָּל הַבּוֹצֵעַ, צָרִיךְ לְדַקְדֵּק בְּה'. אֶלָּא וַדַּאי הָא אוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, מוֹץ וְתֶבֶן פְּטוּרִין מִן הַמַּעֲשֵׂר. וְכַד הִיא בְּמוֹץ וְתֶבֶן, אִיהִי בְּבֵית אֲסוּרִין, וְלֵית לָהּ רְשׁוּ לְאָרָמָא לְגַבֵּי מ', לְמֶעְבַּד עִמָּהּ מַ\"ה. וְהַאי אִיהוּ תְּרוּמָה, תּוֹרָ\"ה דְּאִיהִי ה' חוּמָשֵׁי תּוֹרָה, דְּבָהּ (שמות כ״ד:י״ח) וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְגוֹ'.</p>\n<p>וּבְמוֹץ וְתֶבֶן דְּחִטָּה, עָלֵיהּ אוּקְמוּהָ רַבָּנָן, (קפ\"ח ע\"ב) אִילָן שֶׁאָכַל אָדָם הָרִאשׁוֹן חִטָּה הֲוָה. קָרִיב ח\"ט, דְּאִיהוּ מוֹץ וְתֶבֶן, לְאָת ה'. וְאִסְתְּלִיק מִנֵּיהּ י', דְּאִיהוּ עִשׂוּר דִּילָהּ. וּבְגִין דָּא כַּד אִיהוּ בְּמוֹץ וְתֶבֶן (שלה), דְּאִינּוּן לָקֳבֵל עָרְלָה וּפְרִיעָה, פָטוּר מִן הַמַּעֲשֵׂר. וְלֵית רְשׁוּ לְאָת י', לְחַבְּרָא בְּאָת ה', דְּאִינּוּן אִישׁ וְאִשָּׁה. וּבְגִין דָּא, כָּל הַבּוֹצֵעַ צָרִיךְ <Nonei></i> לְדַקְדֵּק בָּ-ה'. וְצָרִיךְ לְמִבְצַע מֵאֲתָר דְּבִשׁוּלוֹ יָפֶה, בְּגִין דְּבִשׁוּל אִיהוּ גֶּמֶר פְּרִי, וְדָא ו'.</p>"],[9520012674,"<p>וַעֲשָׂרָה דְּבָרִים צָרִיךְ אָדָם לְמֶעְבַּד בִּסְעוּדָתָא. חַד, נְטִּילַת יָדַיִם. תִּנְיָינָא לְתַקְּנָא שְׁתֵּי כִּכָּרוֹת לְשַׁבָּת. תְּלִיתָאָה, לְמֵיכַל תְּלַת סְעוּדָתִין, וּלְאוֹסָפָא מֵחוֹל עַל הַקֹּדֶשׁ. רְבִיעָאָה, לְאַנְהָרָא פָּתוֹרָא בִּשְׁרָגָא. כְּמָה דְּאוּקְמוּהָ, שֻׁלְחָן בַּצָּפוֹן, וּמְנוֹרָה בַּדָרוֹם. וְצָרִיךְ הֲסֵבָּה, כְּמָה דְּאוֹקְמוּהָ הֵסֵבּוּ אֶחָד מְבָרֵךְ לְכֻלָּם.</p>\n<p>וּבְשַׁבָּת, בְּכָל מִלּוֹי, צָרִיךְ לְאִתּוֹסְפָא מֵחוֹל עַל הַקֹּדֶשׁ, בֵּין בְּמַאֲכָלָיו, וּמִשְׁתָּיו, בֵּין בִּלְבוּשׁוֹי, בֵּין בַּהֲסֵבַּתֵיהּ. דְּצָרִיךְ לְתַקְּנָא לֵיהּ מֵסִבָּהּ שַׁפִּירָא, בְּכַמָּה כָּרִים וּכְסָתוֹת מְרֻקְּמָן, מִכָּל דְּאִית בְּבֵיתֵיהּ, כְּמַאן דְּתַקִּין חוּפָּה לְכַלָּה. דְּשַׁבְּתָא אִיהִי מַלְכְּתָא, וְאִיהִי כַּלָּה. וּבְגִין דָּא הֲווֹ נַפְקֵי מָארֵי מַתְנִיתִין עֶרֶב שַׁבָּת לְאַקְדְּמוּתִי לְאָרְחָא, וַהֲווּ אַמְרֵי בֹּאִי כַּלָּה בֹּאִי כַּלָּה. וּצְרִיכִין לְאַתְּעָרָא שִׁירָה וְחֶדְוָה לְפָתוֹרָה לְגַבָּהּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא דְּאִית רָזָא אָחֳרָא. כְּגַוְונָא דְּצָרִיךְ לְקַבְּלָא גְּבִירְתָּהּ, בְּכַמָּה נְהוֹרִין דִּשְׁרָגִּין בְּשַׁבָּת, וּבְכַמָּה עִנּוּגִין, וּלְבוּשִׁין שַׁפִּירִין, וּבֵיתָא מְתֻקְּנָא, בְּכַמָּה מָאנֵי דְּתִקּוּנָא, בַּהֲסֵבָּהּ יָפָה לְכָל חַד וְחַד. וּבְהַאי חֶדְוָה וְתִקּוּנָא, גַּרְמִין דְּאִשְׁתְּאָרַת שִׁפְחָה בִּישָׁא בַחֲשׁוֹכָא, בְּרַעֲבוֹן, בְּבִכְיָה, בְּהֶסְפֵּד. בִּלְבוּשִׁין אוּכָמִין כְּאַרְמַלְתָּא. דְּאִי מְלֵאָה זוֹ, חַרֵבָה זוֹ.</p>\n<p>יֵצֶר טוֹב, מַטְרוֹנִיתָא קַדִּישָׁא. מַלְכוּת הַקֹּדֶשׁ דְּנַחְתָּא בְּשַׁבָּת. כְּלִילָא מֵעֶשֶׂר סְפִירָן. מְעַטְּרָא בְּשֶׁבַע שְׁמָהָן שֶׁאֵינָן נִמְחָקִין. בְּכַמָּה מַרְכְּבוֹת דְּחֵיוָון. וּבְכַמָּה חַיָּילִין וּמַשְׁרְיָין. וּמַלְכָּא נָפִיק לָקֳבְלָא בְּכַמָּה מַשִׁרְיָין. וְאִשְׁתָּאֲרַת יֵצֶר הָרָע שִׁפְחָה בִּישָׁא בַּחֲשׁוֹכָא, כְּאַרְמַלְתָּא בְּלֹא בַּעְלָהּ בְּלָא מֶרְכָּבוֹת.</p>\n<p>וְאִלֵּין דְּאִתְּמַר עָלַיְיהוּ, לַמְזַבְּחִין וְלַמְקַטְרִין לִמְלֶכֶת הַשָּׁמַיִם וְלַמַזָּלוֹת אֲשֶׁר לֹא צִוִּיתִי, הוּא פּוּלְחָנָא דְּשִׁפְחָה בִּישָׁא, דְּשַׁלְטֵי בְּעַרְבֵי שַׁבָּתוֹת וְעַרְבֵי לֵילֵי רְבִיעִיּוֹת. מַה הֲווֹ אִלֵּין עַבְדִּין. הֲווֹ נַטְלִין לְבוּשִׁין אוּכָמִין, וְחַשְׁכָאן נְהוֹרִין, וְעַבְדִין הֶסְפְּדָא בְּלֵילֵי שַׁבָּתוֹת כְּדֵי לְאִשְׁתַּתְּפָא בַּהֲדָהּ כְּמָה דְּאִיהִי שַׁרְיָא, כִּי (קהלת ז׳:י״ד) גַּם זֶה לְעוּמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>\n<p>בָּתַר דְּחָאבוּ יִשְׂרָאֵל, וְאִתְחָרַב בֵּי מַקְדְּשָׁא, אִתְּמַר בִּשְׁכִינְתָּא אִימָּא קַדִּישָׁא, (איכה א׳:א׳) אֵיכָה יָשְׁבָה בָדָד הָעִיר רַבָּתִי עָם הָיְתָה כְּאַלְמָנָה, וּמְכַבִּין בְּלֵיל תִּשְׁעָה בְּאָב נְהוֹרִין וּשְׁרָגִין, וְעַבְדִין הֶסְפֵּד, וְיַתְבִין כַּאֲבֵלִים לְאִשְׁתַּתְּפָא בְּדוֹחֲקָא דִּשְׁכִינְתָּא. בְּגִין דְּאִינּוּן גַּרְמוּ לָהּ כָּל הַהוּא תְּבִירוּ.</p>\n<p>חֲמִשָׁאָה, כּוֹס דְּוַיְכֻלּוּ. שְׁתִּיתָאָה, לְמֶהֱוֵי עַל פָּתוֹרָא מִלֵּי דְּאוֹרַיְיתָא. שְׁבִיעָאָה, לְאַרְכָאָה עַל פָּתוֹרָא, בְּגִין דַּעֲנִיִּים יֵיתוּן עַל פָּתוֹרֵיהּ. תְּמִינָאָה, נְטִילַת יָדַיִם בְּמַיִם אַחֲרוֹנִים. תְּשִׁיעָאָה, בִּרְכַּת הַמָּזוֹן. עֲשִׁירָאָה, כּוֹס דִּבְרָכָה. וְצָרִיךְ לְאַחְזְרָא עָלַיְיהוּ, וּלְתַקְּנָא לוֹן בְּרָזָא קַדִּישָׁא, דְּאִיהִי כְּלוּלָה מֵעֶשֶׂר סְפִירָאן, וְאִיהוּ פָּתוֹרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִסִּטְרָא דִּגְבוּרָה. וּבְגִין כַּךְ אוֹקְמוּהָ רַבָּנָן, שֻׁלְחָן בַּצָּפוֹן.</p>\n<p>חַד (עיין לעיל ברעיא מהימנא פרשת פנחס רמ\"ה ע\"א. כוונת י' דברים של שולחן שבת) נְטִילַת יָדַיִם, דְּהָכִי אוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, יָדַיִם מְזוּהֲמוֹת פְּסוּלוֹת לַבְּרָכָה, בְּגִין דְּאִינּוּן שְׁנִיוֹת לַטּוּמְאָה, דְּאִיהוּ אַב הַטּוּמְאָה. דְּאִיהוּ רִאשׁוֹן כַּד אִינּוּן מְסֻאֲבוֹת, וְכַד אִינּוּן טְהוֹרוֹת אִינּוּן שְׁנִיוֹת לַבְּרָכָה. דִּבְרָכָה לָא שַׁרְיָא אֶלָּא עַל טַהֲרָה. כַּהֲנָא דְּאִיהוּ אִישׁ טָהוֹר, אִישׁ חֶסֶד, שַׁרְיָא עָלֵיהּ בִּרְכָתָא. הֲדָא הוּא דִכְתִיב, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ'. וּבְגִין דָּא, (במדבר ו׳:כ״ג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל וְגוֹ'. וְאוֹקְמוּהָ, כָּל כֹּהֵן הַמְּבָרֵךְ, מִתְבָּרֵךְ. וְשֶׁאֵינוֹ מְבָרֵךְ, אֵין מִתְבָּרֵךְ. וְאוֹקְמוּהָ מָארֵי מַתְנִיתִין, כָּל בְּרָכָה שֶׁאֵין בָּהּ אַזְכָּרָה וּמַלְכוּת לָאו שְׁמֵיהּ בְּרָכָה. מַלְכוּת אֲדֹנָי.</p>\n<p>וְעוֹד, נְטִילַת יָדַיִם צָרִיךְ לִיטוֹל לוֹן עַד פִּרְקָא, דְּגָזְרוּ עָלֵיהּ י\"ד פִּרְקִין, בְּהַהוּא שַׁעֲתָא שַׁרְיָא יַד יְיָ' עָלֵיהּ, וְאִיהִי יַד דִּבְרָכָה מִסִּטְרָא דְּחֶסֶד דְּבֵיהּ חָכְמָה בְּיַד יְמִינֵיהּ. וְאִיהִי יַד דִּקְדוּשָּׁה, מִסִּטְרָא דִּגְבוּרָה, וְשַׁרְיָיא בְּדִינָא. (נ\"א וידא דשמאלא) וְאִיהִי יַד דְּיִחוּדָא, מִסִּטְרָא דְּתִפְאֶרֶת, דְּשַׁרְיָא בְּי\"ד פִּרְקִין דְּגוּפָא, דְּאִינּוּן שְׁנֵים עָשָׂר פִּרְקִין בִּתְרֵין דְּרוֹעִין, וּתְרֵין שׁוֹקִין. וּתְרֵין בְּגוּפָא וּבְרִית.</p>\n<p>וּתְלַת זִמְנִין י\"ד, אִיהוּ מ\"ב, יי\"י, מִן י\"ד י\"ד, י\"ד, רָמוּז יְבָ\"רֶכְךָ יָ\"אֵר יִ\"שָּׂא, מִן הוי\"ה הוי\"ה הוי\"ה. ד' ד' ד' מִי\"ד י\"ד י\"ד, אִינּוּן רְמִיזִין בַּאֲדֹנָ\"י אֲדֹנָ\"י אֲדֹנָ\"י. וְאָמַר הַנָּבִיא עָלַיְיהוּ, (ירמיהו ז׳:ד׳) הֵיכַל יְיָ' הֵיכַל יְיָ' הֵיכַל יְיָ' הֵמָּה. וְהַאי נְטִילָא בְּיַד דְּאִתָּתְקְנָת.</p>\n<p>וְכָל סְטָר מִג' אַנְפֵּי חֵיוָן, דְּאִינּוּן יְיָ' יְיָ' יְיָ'. וּמִתְּלַת גַּדְפֵּי חֵיוָן, דְּאִינּוּן ד' ד' ד', כֻּלְּהוּ צָרִיךְ לְמֶהֱוֵי מִכֹּחַ <Nonei></i> אָדָם. וְאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. כֹּחַ דִּילֵיהּ, יוֹ\"ד וָא\"ו דָּלֶ\"ת, הֵ\"א אָלֶ\"ף, וָא\"ו אָלֶ\"ף וָא\"ו, הֵ\"א אָלֶ\"ף. וּמַטְרוֹנִיתָא לָא שַׁרְיָא בְּכֹחַ דִּילֵיהּ, בְּפִרְקִין דְּאֶצְבְּעָן, עַד דְּאִתְעֲבָר מִנַּיְיהוּ זוּהֲמָא, שִׁפְחָה בִּישָׁא פְּסוּלָה, אִנְתּוּ דְּפָסוּל. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, יָדַיִם מְזוּהֲמוֹת פְּסוּלוֹת לַבְּרָכָה.</p>\n<p>וְאִינּוּן מַיִם לְדַכְּאָה יַד, דְּשַׁרְיָיא תַּמָּן יַד יְיָ'. יַד יְיָ', דָּא מַיִם דְּאוֹרַיְיתָא. דְּעַמֵּי הָאָרֶץ אִינּוּן שֶׁרֶץ, מַה מוֹעִיל לוֹן טְבִילָה, וְהַשֶּׁרֶץ שִׁפְחָה בִּישָׁא בִּידֵיהוֹן, בְּגֶזֶל דְּבִידֵיהוֹן. בְּגֶזֶל דְּבִרְכָּאן דְּגַזְלִין לְקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יַדְעֵי לְבָרְכָא, וְלָא יַדְעֵי מַאי אִיהִי בְּרָכָה, וּמַאי אִיהִי זוּהֲמָא.</p>\n<p>מִיַּד כְּשֶׁשָּׁמְעוּ מִלִּין אִלֵּין חַבְרַיָּיא וַאֲנָא עִמְּהוֹן, לָא יָכִילְנָא לְמִסְבַּל דְּיַשְׁלִים עַשְׂרָה מִלִּין דִּבְרָכָה, וְאִשְׁתְּטַחְנָא לְגַבֵּיהּ. וּבְוַדַּאי לֵית בַּר נָשׁ דְּיֵימָא מִלִּין אִלֵּין, אֶלָּא אַנְתְּ. דְּאַנְתְּ הוּא כְּגַוְונָא דְּד' מְחִיצוֹת דְּגַּן עֵדֶן. דְּבַּר נָשׁ עָאל בְּהוֹן (נ\"א דכד אנת) בִּמְחִיצַּת יְנוּקִין, וְאִתְעָבִיד תִּינוֹק. וּבִמְחִיצַת נְעָרִים, וְאִתְעָבִיד נַעַר. וּבִמְחִיצַת בַּחוּרִים, וְאִתְעָבִיד בָּחוּר. וּבִמְחִיצַת זְקֵנִים, וְאִתְעָבִיד זָקֵן. וּבְּגִין כָּךְ אִתְּמַר עָלָךְ, (תהילים ל״ג:י״ד) 'מִמְכוֹן 'שִׁבְתּוֹ 'הִשְׁגִּיחַ אֶל כָּל יוֹשְבֵי הָאָרֶץ. וְאַנְתְּ הוּא דְּאִתְּמַר עָלָךְ, (בראשית ו׳:ג׳) בְּשַׁגַּם הוּא בָּשָׂר, בְּדָרָא דְּדוֹר הַפְלָגָה הֲוֵית. וּבְכָל דָּרָא וְדָרָא בְּגִלְגּוּלָא. כְּגַלְגַּל דְּמִתְהַפֵּךְ לְכַמָּה גַּוְונִין. וְלָא נִגְלֵת, אֶלָּא בְּדָרָא דְּאִתְיְיהִיב בֵּיהּ אוֹרַיְיתָא עַל יָדָךְ.</p>\n<p>מִיַּד דְּאִתְכְּנִישַׁת מֵעָלְמָא, אַנְתְּ הוּא כְּשִׁמְשָׁא דְּנָהִיר בְּכָל דָּרָא וְדָרָא, דְּכַד אִתְכְּנַשׁ שִׁמְשָׁא בְּלֵילְיָא, נָהִיר בְּסִיהֲרָא, וּבְשִׁתִּין רִבּוֹא כֹּכָבַיָא. הָכִי אַתְּ (אנת), דְּאַנְתְּ נָהִיר בְּשִׁתִּין רִבּוֹא בְּכָל דָּרָא וְדָרָא. וְהַאי אִיהוּ דְּקָא רָמַז קֹהֶלֶת, (קהלת א׳:ד׳) דּוֹר הוֹלֵךְ וְדוֹר בָּא. וְאוֹקְמוּהָ רַבָּנָן, אֵין דּוֹר פָּחוּת מִשִּׁשִׁים רִבּוֹא. וְעוֹד אוּקְמוּהָ, הַדּוֹר שֶׁהוֹלֵךְ הוּא שֶׁבָּא, לְקַיֵּים (שם) מַה שֶׁהָיָה הוּא שֶׁיִּהְיֶה. מִכָּאן וְאֵילָךְ, אַשְׁלִים עַשְׂרָה דְּבָרִים דְּפָתוֹרָא בְּאִתְגַּלְיָיא. אָמַר רַעְיָא מְהֵימָנָא, בּוּצִינָא קַדִּישָׁא זַכָּאָה חוּלָקָךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא גַּלֵּי לָךְ, מַה דְּלָא גַּלֵּי לְכָל נָבִיא וְחוֹזֶה, וְלָא לְמַאן וּלְמַאן.</p>\n<p>תִּנְיָינָא, לְמִבְצַע עַל שְׁנֵי כִּכָּרוֹת בְּשַׁבָּת, דְּאִינּוּן רְמִיזִין בִּתְרֵי לוּחֵי אוֹרַיְיתָא, דְּאִתְיְיהִיבוּ בְּשַׁבָּת זוּגוֹת. דִּבְיוֹמָא תְּלִיתָאָה נַחְתּוּ, דְּבֵיהּ תְּרֵי זִמְנֵי טוֹב, וּבְשַׁבָּת אִתְיְיהִיבַת, תְּרֵין נוּקְבִין לִתְרֵין טָבִין. וְאַף עַל גַּב דְּאוֹקְמוּהָ דְּשֵׁדִים מְמֻנִן עַל זוּגוֹת, כְּמָה דְּאוֹקְמוּהָ שְׁנֵי בֵּיצִים, שְׁנֵי אֱגוֹזִים. הֲלָכָה לְמֹשֶׁה מִסִּינַי שְׁלוּחֵי מִצְוָה אֵינָן נִזוֹקִין.</p>\n<p>וְאִי תֵּימָא, וְהָא תָּנֵינָן, אֵין מַתְחִילִין בַּשֵּׁנִי, וְאֵין מְסַיְּימִין בְּד', דְּהַיְינוּ בְּב' ד' עִם עֶרֶב רַב, דְּלָא הֲווֹ שְׁלוּחֵי מִצְוָה, דְּלָא אִתְגָּיְּירוּ לְשֵׁם שָׁמַיִם, וּלְבָתַר דְּאִתְעַבָּרוּ מֵעָלְמָא, מָנֵּי קוּדְשָׁא בְּרִיךְ הוּא לְנַטְלָא (שמות ל״ד:א׳) שְׁנֵי לוּחוֹת אֲבָנִים כָּרִאשׁוֹנִים, וְאָמַר, (שם) וְכָתַבְתִּי עַל הַלּוּחוֹת אֶת הַדְּבָרִים אֲשֶׁר הָיוּ עַל הַלּוּחוֹת וְגוֹ'.</p>\n<p>וּתְרֵין כִּכָּרוֹת בְּשַׁבָּת, רְמִיזִין לִתְרֵין יוֹדִין יְאֲהדוָֹנָהִי. דַּאֲדֹנָי אִיהִי יְחִידָה מִבַּעְלָהּ בְּשִׁית יוֹמִין דְּחוֹל, וּבְשַׁבָּת נָחִית לְגַבָּהּ. וּבְגִין דָּא בְּשַׁבָּת, כָּל נִשְׁמָתִין וְרוּחִין וְנַפְשִׁין נָפְקִין וְנַחְתִּין זוּגוֹת, וְאֵין שָׂטָן וְאֵין מַזִּיק שַׁלִּיט בְּיוֹמָא דְּשַׁבְּתָא. וַאֲפִילּוּ גֵּיהִנָּם לָא שַׁלִּיט, וְלָא אוֹקִיד בְּשַׁבָּת. וּבְגִין דָּא, (שמות ל״ה:ג׳) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. וְדָא אֵשׁ נוּכְרָאָה, אֶלָּא אֵשׁ דְּקָרְבְּנָא, אֵשׁ דִּקְדוּשָּׁה. וְלֵית לְאַרְכָאָה בִּבְצִיעָא דִּלְהוֹן, דְּהָא אִתְּמַר לְעֵילָּא.</p>\n<p>תְּלִיתָאָה לְמֵיכַל שְׁלֹשָׁה סְעוּדָתִין בְּשַׁבָּת, כְּמָה דְּאוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, דְּאָמַר חַד מִינַיְיהוּ, יְהֵא חֶלְקִי עִם גּוֹמְרֵי שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, דְּאִינּוּן שְׁלִימוּ דִּשְׁבַע בִּרְכָאן דִּצְלוֹתָא, לְאַשְׁלְמָא בְּהוֹן לְעֶשֶׂר. וְרָזָא דְּעֹנֶג, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וּמַאן דְּלָא מְקַיֵּים לוֹן, וְאִית לֵיהּ רְשׁוּ לְקַיְּימָן, אִתְהַפָּךְ לֵיהּ לְנֶגַע צָרַעַת. וּבְגִין דְּלָא יֵיתֵי לְהַאי, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, לְוּוּ עָלַי וַאֲנִי פּוֹרֵעַ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ'.</p>\n<p>רְבִיעָאָה, לְאַנְהָרָא פָּתוֹרָא בִּמְנַרְתָּא. כְּמָה דְּאוֹקְמוּהָ קַדְמָאִין, שֻׁלְחָן בַּצָּפוֹן, מְנוֹרָה בַּדָרוֹם, דְּפָתוֹרָא דְּקוּדְשָׁא בְּרִיךְ הוּא הָכִי צְרִיכָא לְמֶהוֵי. חֲמִישָׁאָה, כּוֹס דְּוַיְכֻלּוּ. כּוֹ\"ס, בְּחֶשׁבוֹן אֱלֹהִים. וַיְכֻלּוּ ע\"ב, דְּכָלִיל לוֹן כַּלָּה קַדִּישָׁא, דְּהַאי כּוֹס מָלֵּא יֵינָא דְּאוֹרַיְיתָא, צָרִיךְ לְאַסְהֲדָא עַל עוֹבָדָא דִּבְרֵאשִׁית.</p>\n<p>שְׁתִיתָאָה, לְמֶהֱוֵי עַל פָּתוֹרָא דִּבְרֵי תּוֹרָה, דְּהָכִי אוֹקְמוּהָ מָארֵי מַתְנִיתִין, ג' שֶׁאָכְלוּ עַל שֻׁלְחָן אֶחָד וְלָא אָמְרוּ עָלָיו דִּבְרֵי תּוֹרָה וְכוּ'. וְרָזָא דְּמִלָּה, בְּגִין דְּהָא אוֹקְמוּהָ שֻׁלְחָן בַּצָּפוֹן, וְאוֹרַיְיתָא אִתְיְיהִיבַת מִימִינָא. לְחַבְּרָא יְמִינָא דְּאִיהוּ רַחֲמֵי, בִּשְׂמָאלָא דְּאִיהוּ דִּינָא. דְּאוֹרַיְיתָא אִיהִי יְיָ' מִימִינָא, פָּתוֹרָא אֲדֹנָי מִשְּׂמָאלָא, וְצָרִיךְ לְחַבְּרָא לוֹן. דִּבְגִין דְּפָתוֹרָא מִשְּׂמָאלָא, אוֹקְמוּהָ רַבָּנָן דְּמַתְנִיתִין, קָשִׁין מְזוֹנוֹתָיו <Nonei></i> שֶׁל אָדָם כִּקְרִיעַת יַם סוּף. וּבְגִין כַּךְ, צָרִיךְ תַּלְמִיד חָכָם לְזַמְּנָא עִמֵּיהּ, לְמַאן דְּיִשְׁתְּדַּל בְּפִתְגָּמֵי אוֹרַיְיתָא.</p>\n<p>שְׁבִיעָאָה, לְאַרְכָאָה עַל פָּתוֹרָא, בְּגִין עֲנִיִּים. וּבְגִין דָּא, כָּל הַמַּאֲרִיךְ עַל שֻׁלְחָנוֹ מַאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָיו. וּבְּגִין כָּךְ (משלי י׳:ב׳) וּצְדָקָה תַּצִּיל מִמָּוֶת. דְּעָנִי חָשׁוּב כַּמֵּת, וְאִיהוּ מְחַיֶּה לֵיהּ, אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא מְחַיֶּה לֵיהּ.</p>\n<p>וְעוֹד בְּאוֹרַח רָזָא, דְּכֻלְּהוּ עֲנִיִּים מִסִּטְרָא דְּאָת ד', דְּאִתְּמַר בָּהּ (תהילים קט״ז:ו׳) דַּלּוֹתִי וְלִי יְהוֹשִׁיעַ. וְאוֹת ד' דְּאֶחָד, דְּצָרִיךְ לְאַרְכָאָה בָּהּ, הֲדָא הוּא דִכְתִיב לְהַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ, וּבְגִין דָּא, צָרִיךְ לְאַרְכָאָה עַל פָּתוֹרָא, דְּאִיהִי ד', כְּלִילָא מְד' רַגְלִין דְּפָתוֹרָא. בְּגִין יְקָרָא דְּאָת דָּלֶי\"ת, צָרִיךְ לְאַרְכָאָה עַל פָּתוֹרָא, בְּגִין עֲנִיִּים.</p>\n<p>וּבְגִינֵיהּ אוֹקְמוּהָ רַבָּנָן, דְּבִקֵּשׁ קוּדְשָׁא בְּרִיךְ הוּא מִדָּה יָפָה לְיִשְׂרָאֵל, וְלָא אַשְׁכַּח כְּמִדָּה דְּדַלּוּת. וְאַקְשׁוּ עָלָהּ, בְּגִין דְּאוֹקְמוּהָ קַדְמָאֵי, כְּחוּשְׁבָן מִינֵי מִיתוֹת דְּאִינּוּן כְּחוּשְׁבָן תּוֹצָאוֹת, וְחֶסְרוֹן כִּיס קָשֶׁה מִכּוּלָן, וְאֵיךְ אַמְרִין אִינּוּן, דְּלָא אַשְׁכַּח לְיִשְׂרָאֵל מִדָּה יָפָה כַּעֲנִיּוּתָא.</p>\n<p>אֶלָּא, בְּגִין (דכל עמא ולישנא), דְּעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת (ישעיהו ח׳:כ״א) וְהָיָה כִּי יִרְעַב וְהִתְקַצַּף וְקִלֵּל בְּמַלְכּוֹ וּבֵאלֹהָיו וּפָנָה לְמָעְלָה. אֲבָל יִשְׂרָאֵל, אִינּוּן קַיָּימָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי מִדָּה, וְלָא אַכְחִישִׁין בֵּיהּ. וּבְגִין דָּא, בְּמִּדָּה דָּא יִתְפָּרְקוּן. הֲדָא הוּא דִכְתִיב, (שמואל ב כ״ב:כ״ח) וְאֶת עַם עָנִי תּוֹשִׁיעַ. וְעָנִי לִישָׁנָא דְּעִנּוּי, דְּאֲפִילּוּ אִית לֵיהּ לְבַּר נָשׁ עוּתְרָא, וְאִיהוּ בְּמַרְעִין וּבְמַכְתְּשִׁין, עָנִי אִתְקְרֵי, אוֹ דְּדַחֲקִין לֵיהּ בְּגִינֵיהּ, וְצַעְרִין לֵיהּ כָּל יוֹמָא. כָּל שֶׁכֵּן מַאן דְּאִיהוּ רַשׁ מִנֵּיהּ, וְאִיהוּ הוֹלֵךְ מֵאֲתָר לַאֲתָר.</p>\n<p>וְעוֹד אִית עָנִי, דְּאִסְתְּלָּק מִנֵּיהּ דַּעְתֵּיהּ, כְּגוֹן אִיּוֹב. דְּאִתְּמַר בֵּיהּ, (איוב ל״ד:ל״ה) אִיּוֹב לֹא בְדַעַת יְדַבֵּר. אוּף הָכִי אִיהִי ד', דְּאִיהִי שְׁכִינְתָּא, כַּד אִסְתַּלָּק מִנָּהּ א\"ח דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִקְרֵי דַּעַת. וְהַאי לֵית לֵהּ חוֹבִין בְּמִלָּה דְּיֵימָא. וְעוֹד, א\"ח אִיהוּ תּוֹרָה, כָּלִיל תרי\"ג פִּקּוּדִין הֲדָא הוּא דִכְתִיב, (שמות ג׳:ט״ו) זֶה שְׁמִי לְעוֹלָם וְגוֹ'. שְּׁמִ\"י עִם י\"ה שס\"ה. זִכְרִי עִם ו\"ה רמ\"ח. וּבְגִין דָּא אוֹקְמוּהָ, אֵין עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְוֹת דִּשְׁאַר עָנִי לָאו אִיהוּ אֶלָּא עִנּוּי. וְאָת ד' מִן אֲדֹנָי, אוּף הָכִי אִיהִי עָנִי בְּלָא יְהוָֹ\"ה.</p>\n<p>תְּמִינָאָה, מַיִם אַחֲרוֹנִים דְּתָקִינוּ לוֹן, בְּגִין מֶלַח סְדוֹמִית, הַמְּסַמֵּא אֶת הָעֵינַיִם. אֲמַאי אִקְרוּן חוֹבָה. אֶלָּא בְּאֹרַח רָזָא, סַם הַמָּוֶת שַׁרְיָא עַל יְדוֹי מְזוּהָמִין, דְּעַבְדֵּי בְּהוּ בְּרָכָה. וְעַל כּוֹס דִּמְבָרְכֵי עָלֵיהּ בְּלֹא טָהֳרָה, אִקְרֵי טָמֵא. וּמַה כּוֹס דְּשׁוֹתִין בּוֹ, טָמֵא לְבָרְכָה עַד דַּהֲווֹ מְטָהֲרֵי לֵיהּ בְּהַדָּחָה מִלְּגוֹ וּמִלְּבַר. כָּל שֶׁכֵּן יְדוֹי. וּבְגִין דָּא, מַיִם אַחֲרוֹנִים חוֹבָה. וְרָזָא דְּמִלָּה, (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם: אֵלּוּ מַיִם רִאשׁוֹנִים. וִהְיִיתֶם קְדוֹשִׁים: אֵלּוּ מַיִם אַחֲרוֹנִים. כִּי קָדוֹשׁ: זֶה שֶׁמֶן עָרֵב. לָקֳבֵל, קָדשׁ קָדשׁ קָדשׁ יְיָ' צְבָאוֹת. וּבְגִין דָּא וְהִתְקַדִּשְׁתֶּם וְגוֹ', לְאִשְׁתְּמוֹדְעָא דְּאַתּוּן בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם.</p>\n<p>תְּשִׁיעָאָה, כּוֹס דִּבְרָכָה. וְאוֹקְמוּהָ מָארֵי דְּמַתְנִיתִין, עֲשָׂרָה דְּבָרִים נֶאֶמְרוּ בְּכוֹס דִּבְרָכָה וְאִלֵּין אִינּוּן. עִטּוּ\"ר. עִטּוּ\"ף. הַדָּחָ\"ה. שְׁטִיפָ\"ה. חַ\"י. מָלֵ\"א. וּמְקַבְּלוֹ בִּשְׁתֵּי יָדָיו. וְנוֹתְנוֹ בַּיָּמִין. וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח. וְנוֹתֵן עֵינָיו בּוֹ. וּמְשַׁגְּרוֹ בְּמַתָּנָה לְאַנְשֵׁי בֵּיתוֹ. וְעַכְשָׁיו, אֵין לָנוּ אֶלָּא אַרְבָּעָה שֶׁהֵן הַדָּחָה. וּשְׁטִיפָה. חַי. מָלֵּא. וְיֵשׁ אוֹמְרִים חַי מִן הֶחָבִית, וְיֵשׁ אוֹמְרִים חַי, הַכּוֹס שָׁלֵם. שֶׁשְּׁבִירָתוֹ זוֹ הִיא מִיתָתוֹ.</p>\n<p>כּוֹס עַל דֶּרֶךְ הַחָכְמָה, הוּא אֱלֹהִים. וְהוּא (מלא בי\"ה והם) וְהָכָא שָׁלֵם, כֹּ\"ס בְּלָא ו' כְּמוֹ כֵּס שֶׁהוּא פָּגוּם וְחָסֵר בְּלָא אָלֶף, כֵּן הוּא חָסֵר בְּלָא וָי\"ו, וְהוּא פָּגוּם. הַכִּסֵּ\"א כֵּן עוֹלֶה בְּגִימַטְּרִיָא כּוֹס.</p>\n<p>כּוֹס הִיא הֵ\"א, וְצָרִיךְ עֲשָׂרָה דְּבָרִים, כְּנֶגֶד י'. וְהֵם: עִטּוּ\"ר בְּסוֹד הָעַטָרָה, עֲטֶרֶת תִּפְאֶרֶת. וְזֶהוּ סוֹד עִטּוּר, שֶׁאָמְרוּ זִכְרוֹנָם לִבְרָכָה מְעַטְּרוֹ בַּתַּלְמִידִים, וְהִיא עֲטֶרֶת הַבְּרִית. עִטּוּ\"ף, (תהילים ק״ב:א׳) תְּפִלָּה לְעָנִי כִּי יַעֲטוֹף. שֶׁכָּל הַבְּרָכוֹת וְהַתְּפִלוֹת מִתְעַטְּפִים, עַד שֶׁתַּעֲלֶה תְּפִלַּת הֶעָנִי.</p>\n<p>הַדָּחָ\"ה וּשְׁטִיפָ\"ה, כְּמוֹ (ויקרא ט״ז:י״ט) וְטִהֲרוֹ וְקִדְּשׁוֹ. הַטָּהֲרָה מִיָּמִין הַחֶסֶד. וְהַקְדוּשָּׁה מִשְּׂמֹאל דִּגְבוּרָה. כּוֹס דִּבְרָכָה מַלְכוּת מִצַּד בִּינָה הַנִקְרֵאת אֱלֹהִים. וְנִקְרָא עֲטָרָה מִצַּד הַכֶּתֶר. חַ\"י, מִצַּד יְסוֹד, הַנִּקְרָא שָׁלוֹם, שֶׁנֶּאֱמַר (ישעיהו נ״ד:י׳) וּבְרִית שְׁלוֹמִי לֹא תָמוּט אָמַר מְרַחֲמֵךְ יְיָ'. מָלֵּא, מִצַּד תִפְאֶרֶת. מְקַבְּלוֹ בִּשְׁתֵּי יָדָיו, ה' ה'.</p>\n<p>וְנוֹתְנוֹ בַּיָּמִין, כִּי ה' עֶלְיוֹנָה לָחֶסֶד, ה' שְׁנִיָה לַגְּבוּרָה. וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח, בְּסוֹד יוֹ\"ד כִּי סִלּוּק ה' הוּא יוֹ\"ד. וְנוֹתֵן עֵינָיו בּוֹ, שֶׁהֵם בְּסוֹד יְאֲהדוָֹנָהִי. יְיָ' (ד\"א יו\"ד) מֵאִיר בְּבַת עַיִן. ידִֹוִ\"ד בִּשְׁלֹשָׁה צִבְעֵי הָעַיִן. אֲדֹנָי מְאִירָה בִּשְׁנֵי כְּרוּבֵי הָעַיִן, וְאִישׁוֹנֵי עַפְעַפֵּי הָעַיִן. וּמְשַׁגְּ\"רוֹ בְּמַתָּנָה לְאַנְשֵׁי <Nonei></i> בֵּיתוֹ. הִיא בִּינָה, שֶׁנֶּאֱמַר בָּהּ, יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ.</p>\n<p>עֲשִׁירָאָה, בִּרְכַּת מְזוֹנָא, הָא אוֹקְמוּהָ רַבָּנָן, בִּשְׁלֹשָׁה, צָרִיךְ כּוֹס. וְרָזָא דְּמִלָּה, בְּגִין דְּאִיהִי (ירמיהו ב׳:ב׳) אַהֲבַת כְּלוּלוֹתָיִךְ, דְּאִינּוּן אֲבָהָן, בַּכֹּ\"ל מִכֹּ\"ל כֹּ\"ל. וְלֵית לְאַרְכָאָה יַתִּיר.</p>\n<p>בִּרְכַּת הַמָזוֹן מִּן הַתּוֹרָה מִנַיִן. שֶׁנֶּאֱמַר, וְאָכַלְתָּ וְשָׂבָעְתָּ וְגוֹ'. וְשָׁנִינוּ בַּבְּרַיְיתָא, וּבֵרַכְתָּ זוּ בִּרְכַּת הַזָן. אֶת ה' אֱלֹהֶיךָ זוּ בִּרְכַּת הַמָזוֹן. עַל הָאָרֶץ, זוּ בִּרְכַּת הָאָרֶץ. הַטוֹבָה, זוּ בּוֹנֶה יְרוּשָׁלָיִם. וְכֵן הוּא אוֹמֶר, (דברים ג׳:כ״ה) הָהָר הַטוֹב הַזֶה וְהַלְבָנוֹן. אֵין לִי אֶלָא לְאַחֲרָיו, לְפָנָיו מִנַיִן. שֶׁנֶּאֱמַר אֲשֶׁר נָתַן לָךְ, מִשָׁעָה שֶׁנָתַן לְךָ, חַיָיב אַתָּה לְבָרְכוֹ.</p>\n<p>וְדָרְשׁוּ חַכָמִים זִכְרוֹנָם לִבְרָכָה, מֹשֶׁה תִּיקֵן לָהֶם לְיִשְׂרָאֵל בִּרְכַּת הַזָן, בְּשָׁעָה שֶׁיָרַד לָהֶם הַמָן. יְהוֹשֻעַ תִּיקֵן לָהֶם בִּרְכַּת הָאָרֶץ, בְּשָׁעָה שֶׁהֶכנִיסָן לָאָרֶץ. דָוִד וּשְׁלֹמֹה תִּקְנוּ בּוֹנֶה יְרוּשָׁלָיִם. עוֹד נִמְצָא בְּפָּרָשַׁת הַמָן, רֶמֶז לְבִּרְכַּת מָזוֹן בַּמָן עַצְמוֹ, שֶׁנֶּאֱמַר (שמות ט״ז:י״ב) וּבַבֹּקֶר תִּשְׂבְּעוּ לֶחֶם וִידַעְתֶּם כִּי אֲנִי ה' אֱלֹהֵיכֶם.</p>"],[9520012675,"<p>אָמַר רִבִּי שִׁמְעוֹן, רָזָא דְּאִינוּן שֶׁבַע זַיִינִין דִּרְשִׁימִין בִּתְּפִלִין, דְּהוּא ז' שִׁבְעִין (נ\"א שבשינין), דִּרְמִיזִין לְז' אוּנֵי דְּרֵיאָה דְּבַּר נָשׁ, דִּבְּהוֹן שָׁאִיב רוּחָא, וּמִנֵיה מַפִּיק צוּצִיתָא דְּנוּר, דְּדָלִיק מִפּוּמֵיה. וְעוֹד דְּאִינוּן רֶמֶז לְשִׁבְעָה יוֹמֵי וּשְׁבוּעֵי דְּמִפֶּסַח לַעֲצֶרֶת. וְעוֹד דְּאִינוּן רְמִיזִין לְשִׁבְעָה קְנֵי מְנֹרָתָא, דְּאִית עֲלַיְיהוּ שֶׁבַע בּוּצִינֵי קַדִישִׁין. וְעוֹד דְּאִינוּן רְמִיזִין לְשִׁבְעָה כֹּכְבֵי לֶכֶת, דְּאִינוּן מְנַהֲרֵי בִּרְקִיעָא. וְעוֹד דְּאִינוּן רְמִיזִין לְשִׁבְעָה מַדְרֵגִין, דְּעָלְמָא עֲלַיְיהוּ קַיְימָא. וְאִינוּן יְסוֹדָא וְשֹׁרְשָׁא וְעִיקָרָא דְּכֹּלָא. וְעֲלֵיהוֹן אֲמְרֵי חַבְרַיָיא, כָּל מַאן דְּבָּעִי לְאַנְחָא תְּפִלִין דְּרֵישָׁא, מִבָּעֵי לֵיה לְאִסְתַּכְּלָא בְּאִינוּן תְּרֵי שִׁינִין, דְּאִינוּן רְמִיזִין לְאִינוּן ז' זַיְינִין, דְּאִית בְּהוֹן רֶמֶז רָזִין סְתִּימִין, עֲמִיקִין רְמִיזִין ע\"כ.</p>"],[9520012676,"<p>כִּי יְיָ' אֱלֹהֵיכֶם הוּא אֱלֹהֵי הָאֱלֹהִים וַאֲדֹנֵי הָאֲדֹנִים הָאֵל הַגָדוֹל וְגו'. תַּנֵינָן, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. אִלֵין לָאו אִינוּן כְּאִינוּן כְּרוּבִים, אִינוּן אַנְפֵּי רַבְרְבִין, כְּרוּבִים אַנְפֵּי זוּטְרֵי, כְּרַבְיָא. פְּנֵי אָדָם, כָּל דְיוּקְנָא כְּלִילָן בְּהוּ, בְּגִין דְּאִינוּן אַנְפֵּי רַבְרְבִין, וּמִתְּצַיְירִין בְּהוּ צִיוּרִין גְלִיפִין, בְּגִלוּפֵי שְׁמָא דִּמְפֹרָש, בְּד' סִטְרִין, מִזְרָ\"ח מַעֲרָ\"ב צָפוֹ\"ן דָרוֹ\"ם.</p>\n<p>מִיכָאֵ\"ל רָשִׁים בִּרְשִׁימוּ לִסְטַר דָרוֹם, וְכָל אַנְפִּין מִסְתַּכְּלִין לְגַבֵּי פְּנֵי אָדָ\"ם, פְּנֵי אַרְיֵ\"ה פְּנֵי נֶשֶׁ\"ר פְּנֵי שׁוֹ\"ר. אָדָם אִיהוּ דְכַר וְנוּקְבָא, וְלֹא אִתְּקְרֵי אָדָם בַּר הָכִי. וּמִנֵיה אִתְּצַיְירִין צִיוּרִין, (תהילים ס״ח:י״ח) דְּרֶכֶב אֱלֹהִים רִבּוֹתַיִם אַלְפֵי שִׁנְאָן.</p>\n<p>שִׁנְאָן, כְּלָלָא דְּכֻּלְהוּ צִיוּרֵי, שׁוֹ\"ר, נֶשֶׁ\"ר, אַרְיֵ\"ה, ן' דָא אִיהוּ אָדָם. פְּשִׁיטוּ דְּאִתְּכְלִיל כְּחָדָא, בְּרָזָא (דדכר) דְכַר וְנוּקְבָא. וְכֻּלְהוּ אַלְפִין וְרִבְבָן, כֻּלְהוּ נָפְקִין מֵהַנֵּי רָזָא שִׁנְאָן. מֵהַנֵּי דְיוּקְנִין מִתְּפַּרְשָׁן כָּל חַד וְחַד בְּסִטְרַיְיהוּ, כְּמָה דְּאִתְּחַזֵי לוֹן.</p>\n<p>אִלֵין אִינוּן דְּקָא מְשַׁלְבָן חַד בְּחַד, וְכָּלִיל חַד בְּחַד, לְמֶהֱוֵי כֹּל חַד כָּלִיל בְּחַבְרֵיה, שׁוֹ\"ר נֶשֶׁ\"ר אַרְיֵ\"ה אָדָ\"ם, אִתְנַהֲגָן בְּרָזָא דְּאַרְבַּע שְׁמָהָן גְלִיפָן סַלְקִין לְאִתְנַהֲגָא וּלְאִסְתַּכְּלָא.</p>\n<p>סַלִיק לְאִתְנַהֲגָא וּלְאִסְתַּכְּלָא שׁוֹר לְאַנְפֵּי אָדָם, סָלִיק שְׁמָא אַחֲרָא, מִתְעַטְרָא מְחָקְקָא בְּרָזָא דִּתְּרֵין גְוָונִין, וְאִיהוּ אֵל. כְּדֵין אִתְהֲדַר לְאַחוֹרָא, וְכֻּרְסְיָיא חָקִיק וְגָלִיף לֵיה, וְאִתְרְשִׁים לְאִתְנַהֲגָא בְּרָזָא דִּשְׁמָא דָא.</p>\n<p>וְסַלִיק לְאִתְנַהֲגָא וּלְאִסְתַּכְּלָא נֶשֶׁר לְאַנְפֵּי אָדָם, סָלִיק שְׁמָא חָדָא, מִתְעַטְּרָא מִתְנַהֲגָא בְּרָזָא דִּתְּרֵין אַנְפִּין וּגְוָונִין, לְאִתְנַהֲגָא לְאִסְתַּלְקָא בִּסְלִיקוּ בְּעִטוּרָא, וְאִיהוּ גָדוֹל, כְּדֵין אִתְהֲדַר לְאַחוֹרָא, וְכֻּרְסְיָיא חָקִיק וְגָלִיף לֵיה, ואִתְרְשִׁים לאִתְנַהֲגָא בְּרָזָא דִּשְׁמָא דָא.</p>\n<p>סַלִיק לְאִתְנַהֲגָא וּלְאִסְתַּכְּלָא אַרְיֵה לְאַנְפֵּי אָדָם, סַלִיק שְׁמָא חָדָא מִתְעַטְּרָא מְחָקְקָא בְּרָזָא דִּתְּרֵין אַנְפִּין וּגְוָונִין, לְאִתְתַּקְפָא וּלְאִתְקַשְׁרָא בְּתוּקְפֵיה, וְאִיהוּ גִּבּוֹר. כְּדֵין אִתְהֲדַר לְאֲחוֹרָא, וְכֻּרְסְיָיא חָקִיק וְגָלִיף לֵיה, וְאִתְרְשִׁים לְאִתְנַהֲגָא בְּרָזָא דִּשְׁמָא דָא.</p>\n<p>אָדָם אִסְתָּכַּל בְּכֻּלְהוּ, וְכֻּלְהוּ סַלְקִין וּמִסְתַּכְּלִין בֵּיה, כְּדֵין כֻּלְהוּ אִצְטַיְירָן בִּגְלוּפַיְיהוּ בְּצִיוּרָא דָא, בְּרָזָא דִּשְׁמָא חַד, דְּאִקְרֵי נּוֹרָא. וּכְדֵין כְּתִיב עֲלַיְיהוּ, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. כֻּלְהוּ כְּלִילָן בְּהַאי דִּיוּקְנָא, וְהַאי דִּיוּקְנָא כָּלִיל לוֹן.</p>\n<p>וְעַל רָזָא דָא, אִתְּקְרֵי קוּדְשָׁא בְּרִיךְ הוּא, הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא. דְּהָא שְׁמָהָן אִלֵין גְלִיפִין אִינוּן לְעֵילָא, בְּרָזָא דִּרְתִּיכָא עִלָאָה, כְּלִילָא בְּאַרְבַּע אַתְּוָון ידוד, דְּאִיהוּ שְׁמָא דְּכָּלִיל כָּל דִּיוּקְנִין, אִלֵין מְחָקְקָן גְלִיפִין בְּכֻּרְסַיָיא, וְכֻּרְסַיָיא גְלִיפָא מְרַקְמָא בְּהוּ. חַד לִיְמִינָא, וְחַד לִשְׁמָאלָא, וְחַד לְקַמָא, וְחַד לְאַחוֹרָא. רְשִׁימָא בְּד' סִטְרִין דְּעַלְמָא.</p>\n<p>כֻּרְסְיָיא כַּד סַלְקָא, רְשִׁימָא בְּאַרְבַּע דִּיוּקְנִין אִלֵין. אִלֵין אַרְבַּע שְׁמָהָן עִלָאִין, נָטְלִין לְהַאי כֻּרְסְיָיא. וְכֻּרְסְיָיא אִתְכְּלֵל בְּהוּ, עַד דְּנָקְטָא וְלָקְטָא אִינוּן עִנוּגִין וְכִּסוּפִין, נָחֲתָא מַלְיָיא כְּאִילָנָא דְּמַלֵי עַנְפִין לְכָל סְטַר, וּמַלְיָיא אִיבִין. כֵּיוָן דְּנָחֲתָא, נְפָקוּ אִלֵין ד' דִּיוּקְנִין, מְצוּיָרִין בְּצִיוּרַיְיהוּ, גְלִיפִין מְנַהֲרָן, נְצִיצָן מְלַהֲטָן, וְאִינוּן זַרְעִין זַרְעָא עַל עָלְמָא.</p>"],[9520012677,"<p><Noneb>רעיא מהימנא</b><br> <Nonei></i> (דברים ט״ז:י״ח) שׁוֹפְטִים וְשׁוֹטְרִים תִּתֶּן לְךָ בְּכָל שְׁעָרֶיךְ אֲשֶׁר יְיָ' אֱלֹהֶיךָ נוֹתֵן לְךָ וְגוֹ'. בְּפִקּוּדָא דָּא, מָנֵי שׁוֹפְטִים וְשׁוֹטְרִים. וְעוֹד (תהילים ע״ה:ח׳) כִּי אֱלֹהִים שׁוֹפֵט, כִּי י' (מ', מניה) יוֹ\"ד דְּחוּשְׁבָּנֵיהּ כ', כֶּתֶר (בתר) הָכָא, כ' אֱלֹהִים שׁוֹפֵט, זֶה יַשְׁפִּיל ה\"א ה\"א (ה\"ה), וְזֶה יָרִים דָּא (ו\"ו) ו' ו'.</p>"],[9520012678,"<p>פִּקּוּדָא בָּתַר דָּא, לָדוּן בְּסַיִיף. לָדוּן בְּחֶנֶק. לָדוּן בְּדִין סְקִילָה. לָדוּן בְּדִין שְׂרֵיפָה. לָדוּן בְּסַיִיף לְמַאן, לְסָמָאֵל. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ד:ה׳) כִּי רִוְּתָה בַשָׁמַיִם חַרְבִּי הִנֵּה עַל אֱדוֹם תֵּרֵד.</p>\n<p>חֶרֶב דְּקוּדְשָׁא בְּרִיךְ הוּא, י' רֵישָׁא דְּחַרְבָּא. ו' גּוּפָא דְּחַרְבָּא. הֵ\"א הֵ\"א, תְּרֵין פִּיפִיּוֹת דִּילָהּ. צֶדֶק צֶדֶק תִּרְדּוֹף, חַתְכִין תְּרֵין דִּינִין, דִּינָא מִפִּי בֵּית דִּין דִּלְעֵילָּא, וְדִינָא מִפִּי בֵּית דִּין דִּלְתַּתָּא. וּמֵהָכָא אִשְׁתְּמוֹדָע, אֵין אָדָם נוֹקֵף אֶצְבָּעוֹ מִלְּמַטָּה עַד שֶׁנִּתַּן לוֹ רְשׁוּת מִלְּמַעְלָה.</p>\n<p>נַרְתְּקָא דְּחַרְבָּא אֲדֹנָי. תַּמָּן אִשְׁתְּכַח דִּינָא. בְּקְרִיאַת שְׁמַע ידוד. חַרְבָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, עָלָהּ אִתְּמַר (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. בְּצַדִּיק חַי עָלְמִין, כָּלִיל חַ\"י בִּרְכָאן, דְּבֵיהּ אֲדֹנָי שְׂפָתַי תִּפְתָּח וּפִי, בֵּיהּ עָאל חַרְבָּא בְּנַרְתִּיקָהּ, (אסתר ז׳:י׳) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וּמִתְחַבְּרִין תְּרֵין שְׁמָהָן יְאֲהדוָֹנָהִי.</p>\n<p>לָדוּן בְּחֶנֶק, זַרְקָא. תַּמָּן קַו, י' כְּרִיכָא בֵּיהּ, וְקַו, ו' דְּאִתְפַּשְּׁטָא מִנֵּיהּ. בֵּיהּ תָּפִיס לְסָמָאֵל, (במדבר י״ג:כ״ג) וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם. מַאי מוֹט דְּהַהוּא רָשָׁע. אָדָם דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, מַ\"ה, וְד' אַתְוָון ידוד, הֲרֵי תִּשְׁעָה וְאַרְבָּעִים, כְּחוּשְׁבָּן תִּשְׁעָה וְאַרְבָּעִים אַתְוָון, דְּאִינּוּן בְּשִׁית תֵּיבִין דְּיִחוּדָא עִלָּאָה, וּבְשִׁית תֵּיבִין דְּיִחוּדָא תַּתָּאָה, דְּאִינּוּן ו' ו', וְהַאי הוּא וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם, בְּפִרוּדָא מִנַּיְיהוּ, בְּלָא א' בְּאֶמְצַע וָ\"ו, דְּלֵית יִחוּדָא לְסִטְרָא אַחֲרָא, אֶלָּא וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם, סָמָאֵל וּבַת זוּגֵיהּ, עוֹלָם הַנִפְרָדִים.</p>\n<p>בְּחֶבֶל דְּיֵחָנֵק בָּהּ, אֲחִידָן הֵ\"א הֵ\"א, בְּה' אֶצְבְּעָאן דְּיַד יְמִינָא, וּבְה' דְּיַד שְׂמָאלָא. ו' חֶבֶל. י' חֲנִיקָא דִּלְהוֹן. שְׁמָא דַּיְדוָֹ\"ד, מִיתָה לְסָמָאֵ\"ל וְנָחָשׁ, וְחַיִּים לְיִשְׂרָאֵל. (עיין בראשית כ\"ב ע\"ב) וּבְגִין דָּא (דברים ל״ב:ל״ט) רְאוּ עַתָּה כִּי אֲנִ\"י אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי. אֲנִי אָמִית לֵאלֹהִים אֲחֵרִים בִּשְׁמִי, וּלְכָל דְּלָא הֵימְנוּ בִּי. וַאֲחֲיֶּה לְאִינּוּן דְּהֵימְנִין וְנַטְרִין פִּקּוּדִין דִּילִי.</p>\n<p>לָדוּן בִּסְקִילָה לְסָמָאֵל, בְּאֶבֶן דְּאִיהִי יוֹ\"ד, זָרִיק לָהּ (צדיק) לְגַבֵּיהּ, בַּחֲמֵשׁ אֶצְבְּעָאן דְּאִינּוּן ה', וּבַקָּנֶה דִּדְרוֹעָא דְּאִיהוּ ו', וּבַכָּתֵף דְּתַמָּן ה'. וְזָרִיק לָהּ לְגַבֵּיהּ מַחֲשָׁבָה, דְּאִיהוּ שְׁמָא מְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א.</p>\n<p>לָדוּן בִּשְׂרֵפָה לְסָמָאֵל. עֵצִים לְאַדְלְקָא בְּהוֹן נוּרָא. זַכָּאָה אִיהוּ גּוּפָא דְּאִיהוּ עֵץ, וְאֵבָרִים דִּילֵיהּ עֵצִים, לְאוֹקְדָא בְּהוֹן אֶשָּׁא, דְּאִיהוּ נֵר מִצְוָה, בְּכָל אֵבֶר, לְאוֹקְדָא לְסָמָאֵל, בִּשְׁכִינְתָּא עִלָּאָה, בְּעֵץ דְּאִיהוּ תִּפְאֶרֶת, וּבְכָל עֵצִים דַּאֲחִידָן בֵּיהּ. דִּבְזִמְנָא דְּאֵשׁ עַל גָּבוֹהַּ נָחִית הֲוָה, עַל גַּבֵּי עֵצִים דְּקָרְבְּנָא, (במדבר א׳:נ״א) וְהַזָּר הַקָּרֵב יוּמָת, דְּאִתּוֹקַד בֵּיהּ. הֲדָא הוּא דִכְתִיב, (ויקרא ו׳:ה׳) וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ. זַכָּאָה אִיהוּ מַאן דְּאָחִיד בְּאִילָנָא דְּחַיֵּי, בְּגוּפֵיהּ, בְּאֵבָרִים דִּילֵיהּ, נֵר כָּל עַנְפָא וְעַנְפָא נֵר מִצְוָה ברמ\"ח פִּקּוּדִין דִּילֵיהּ.</p>\n<p>כַּד אֲחִידָן בֵּיהּ תַּרְוַויְהוּ, יִתְקְיָּים (שמות ג׳:ב׳) וַיַּרְא וְהִנֵּה הַסְּנֶה בּוֹעֵר בָּאֵשׁ וְהַסְּנֶה אֵינֶנּוּ אוּכָּל. וְסָמָאֵל וְנָחָשׁ וְכָל מְמָנָן דִּילֵיהּ, דְּאִינּוּן קוֹצִין, אִתּוֹקָדוּ. וַעֲנְפִין דִּסְנֶה, וְאִיבָּא דִּילֵיהּ, וְעָלִין דִּילֵיהּ, לָא אִתּוֹקָדוּ. דָּא אַחְזֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר בּוּצִינָא קַדִּישָׁא, וַדַּאי יִשְׂרָאֵל אִינּוּן עֵצִים יְבֵשִׁים בְּאוֹרַיְיתָא, בְּגִין דַאֲחִידוּ בְּאֵשׁ דְּהֶדְיוֹט, לָאו אִינּוּן כַּדְּקָא חֲזִי, לְמֶעְבַּד בְּהוֹן נִיסָא, מִיַּד דְּאַנְתְּ נְחִיתַת עָלַיְיהוּ בְּאוֹרַיְיתָא, בְּגִינָךְ נָחַת עָלַיְיהוּ אִילָנָא דְּחַיֵּי, וּמִצְוָה דְּאִיהוּ נֵר יְיָ' וַאֲחִידַת בְּהוֹן וְיֵהוֹן חַיִּין. וְאוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, אִתּוֹקְדָן בְּהַהוּא נֵר. וְהַאי אִיהוּ דְּאָמַר נָבִיא, (ירמיהו מ״ו:כ״ז) וְאַתָּה אַל תִּירָא עַבְדִי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי אִתְּךָ אָנִי וְגוֹ'.</p>"],[9520012679,"<p>(ארבעים יכנו וגו' ר\"פ ע\"ב) <Nonei></i> (דברים י״ט:ט״ו) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ לְכָל עָוֹן וְגוֹ'. עַל פִּי שְׁנֵי עֵדִים אוֹ עַל פִּי שְׁלֹשָׁה עֵדִים יָקוּם דָּבָר. פִּקּוּדָא דָּא, לְהָעִיד עֵדוּת בְּבֵּית דִּין, דְּלָא יַפְסִיד חַבְרֵיהּ מָמוֹנָא בְּגִינֵיהּ, אִי אִית לֵיהּ עֵדוּת בַּהֲדֵיהּ. וְלֵית סַהֲדוּתָא פָּחוּת מִתְּרֵין, הֲדָא הוּא דִכְתִיב עַל פִּי שְׁנַיִם עֵדִים וְגוֹ' יָקוּם דָּבָר, לֹא יָקוּם עַל פִּי עֵד אֶחָד. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מָתְנִיתִין, מִי מֵעִיד עַל הָאָדָם, קִירוֹת בֵּיתוֹ. וְלֹא עוֹד אֶלָּא אַנְשֵׁי בֵּיתוֹ מְעִידִין עָלָיו. מַאי קִירוֹת בֵּיתוֹ. אִינּוּן קִירוֹת לִבּוֹ. (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, וְאוֹקְמוּהָ רַבָּנָן, מְלַמֵּד שֶׁהִתְפַּלֵל חִזְקִיָּהוּ מִקִּירוֹת לִבּוֹ.</p>\n<p>אַנְשֵׁי בֵּיתוֹ, אִינּוּן רמ\"ח אֵבָרִים דִּילֵיהּ. דְּהָכִי אוּקְמוּהָ מָארֵי מָתְנִיתִין, רָשָׁע עֲוֹנוֹתָיו חֲקוּקִים עַל עַצְמוֹתָיו. וְהָכִי צַדִּיק, זָכִיוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. וּבְּגִין כָּךְ אָמַר דָּוִד (תהלים לט) כָּל עַצְמוֹתַי תֹּאמַרְנָה. וּבְגִינֵהּ אִתְּמַר, וּמִי מְעִידִין עַל הָאָדָם קוֹרוֹת בֵּיתוֹ. גַּרְמִין בְּנוּיִין עַל מוֹחָא דְּאִיהוּ מַיָּא. וְעָלַיְיהוּ קָא רָמִיז, (תהילים ק״ד:ג׳) הַמְקָרֶה בַמַיִם עֲלִיּוֹתָיו, הַמְקָרֶה לָשׁוֹן קוֹרוֹת.</p>\n<p>וַאֲמַאי בְּגַרְמִין יַתִּיר מִבִּשְׂרָא וְגִידִין וּמִשְׁכָא. בְּגִין דְּגַרְמִין אִינּוּן חִוָּורִין, וּכְתִיבָא אוּכָּמָא, לָא אִשְׁתְּמוֹדְעָא אֶלָּא מִגּוֹ חִוָּורוּ. כְּגַוְונָא דְּאוֹרַיְיתָא, דְּאִיהִי חִוָּורוּ מִלְּגָאו, אוּכָם מִלְּבַר. אוּכָם וְחִוָּור, חֹשֶׁךְ וְאוֹר. וְאִית חֹשֶׁךְ תְּכֵלֶת, וְאִתְּמַר בֵּיהּ (תהילים קל״ט:י״ב) גַּם חֹשֶׁךְ לֹא יַחֲשִׁיךְ מִמֶּךָּ. וּתְכֵלֶת אוּכָם, אִיהוּ נוּקְבָּא לְגַבֵּי חִוָּורוּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא דְּגוּפָא עַל גַּרְמִין עָתִיד לְמֵיקָם. וּבְגִין דָּא זַכְווֹי וְחוֹבוֹי חָקוּקִין עַל גַּרְמִין דִּילֵיהּ, וְאִם יִזְכֶּה יְקוּם גּוּפָא עַל גַּרְמִין דִּילֵיהּ. וְאִי לָאו, לָא יְקוּם, וְלָא יְהֵא לֵיהּ תְּחִיַּית הַמֵּתִים. וְלָא עוֹד, אֶלָּא תְּרֵין סָהֲדִין אִינּוּן עַל בַּר נָשׁ, עַיִן רוֹאָה וְאוֹזֶן שׁוֹמַעַת, וּבֵּית דִּין סוֹפֵר, וְדָן חוֹבוֹי. וְלֹא עוֹד, אֶלָּא שִׁמְשָׁא וְסִיהֲרָא סָהֲדִין עַל בַּר נָשׁ, כְּמָה דְּאוֹקְמוּהָ (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. מַאי בַּכֶּסֶה. בְּיוֹמָא דְּסִיהֲרָא מִתְכַּסָה. וַאֲמַאי מִתְכַּסֵּת. בְּגִין דְּכַד מָטֵי רֹאשׁ הַשָּׁנָה, יֵיתֵי סָמָאֵל לְמִתְבַּע דִּינָא לִבְנוֹי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְהוּא יֵימָא לֵיהּ דְּיֵיתֵי סָהֲדִין. וְהוּא יֵיתֵי לְשִׁמְּשָׁא עִמֵּיהּ. אָזַל לְמַיְיתֵי סִיהֲרָא, וְהִיא מִתְכַּסָא. בְּאָן אֲתָר מִתְכַּסֵּת. אֶלָּא סְלִיקַת, לְהַהוּא אֲתָר, דְּאִתְּמַר בֵּיהּ בַּמְכוּסֶּה מִמָּךְ אַל תַּחְקוֹר, לְפַיְּיסָא לֵיהּ עַל בְּנָהָא.</p>\n<p>וְהַאי הוּא דְּאָמַר קְרָא, תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. לַאֲתָר דְּבֵיהּ סְלִיקַת שְׁכִינְתָּא, דְּאִתְּמַר בֵּיהּ וּבַמְכוּסֶּה מִמָּךְ אַל תַּחְקוֹר. וְחוֹבִין בְּאִתְכַּסְיָיא, תַּמָּן צָרִיךְ לְמֵידָן בֵּינוֹ לְבֵין קוֹנוֹ. וְחוֹבִין דְּאִתְגַּלְיָיא דְּעָבַד לוֹן, אִתְּמַר (משלי כ״ח:י״ג) מְכַסֶּה פְּשָׁעָיו לֹא יַצְלִיחַ. דִּשְׁכִינְתָּא מִסִּטְרָא דְּכֶתֶר אִיהִי עָלְמָא דְּאִתְכַּסְּיָא, וְאוֹקְמוּהָ מָארֵי מָתְנִיתִין, דְּצָרִיךְ בַּר נָשׁ לְחַבְּרָא לָהּ לְהַהוּא אַתְרָא. בְּהַהוּא זִמְנָא מָטֵי זִמְנָא דְּרַחֲמֵי, וְאַעְבַּר דִּינָא. וּבְגִין דָּא לְחַבְרֵיהּ אָמַר לְזַכָּאָה לֵיהּ בְּעֵדוּתֵיהּ, אֲבָל לְרָשָׁע אֵין מְזַכִּין לוֹ.</p>\n<p>וְעוֹד, קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ סָהֲדִין עַל בַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (דברים א) הֲעִדוֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֶת הַשָּׁמַיִם, הַהוּא דְּאִתְּמַר בֵּיהּ (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְאֶת הָאָרֶץ, הַהוּא דְּאִתְּמַר בָּהּ (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי. וְעוֹד, תְּרֵין סָהֲדִין: עַמּוּדָא דְּאֶמְצָעִיתָא, וְצַדִּיק. וְאִינּוּן ע\"ד, מִן שְׁמַ\"ע אֶחָד. עֵד, מִן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>\n<p>עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה עֵדִים יוּמַת הַמֵּת, דָּא סָמָאֵל, מֵת מֵעִקָרוֹ (במדבר י״ג:כ״ג) וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם. לֹא יוּמַת עַל פִּי עֵד אֶחָד, דְּלָא יְהֵא לֵיהּ חוּלָקָא בְּאֵל אֶחָד.</p>\n<p>כִּי יָקוּם עֵד חָמָס בְּאִישׁ וְגוֹ' וְדָרְשׁוּ הַשּׁוֹפְטִים הֵיטֵב וְגוֹ', וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם וְגוֹ'. פִּקּוּדָא דָּא לִדְרוֹשׁ וְלַחֲקוֹר הָעֵדִים בְּז' חֲקִירוֹת, קוֹדֶם דְּיָדִין לֵיהּ בְּעוֹנְשָׁא דְּמוֹתָא, בְּשֶׁבַע חֲקִירוֹת, שֶׁבַע לָקֳבֵל (זכריה ד׳:י׳) שִׁבְעָה אֵלֶּה עֵינֵי יְיָ' הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. בְּהוֹן (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי שֶׁבַע.</p>"],[9520012680,"<p>פִּקּוּדָא בָּתַר דָּא, לַעֲשׂוֹת לְעֵד זוֹמֵם כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו. תְּרֵין סַהֲדֵי שִׁקְרָא דְּאִינּוּן סָמָאֵל וְנַחַשׁ, אִי יֵיתוּן לְאַסְהֲדָא סָהֲדוּתָא דְּשֶׁקֶר עַל יִשְׂרָאֵל, דְּטָעוּ בֵּין ו' לְז' דְּאִינּוּן אַתְוָון זוּ. וְהַאי אִיהוּ (ישעיהו מ״ג:כ״א) עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ.</p>\n<p>וְלָא יִתְיַיחֵד ו' עִם ז', אֶלָּא בִּשְׂרֵפַת חָמֵץ, דְּבֵין ו' לְז'. וְאַף עַל גַּב דְּמִדְּאוֹרַיְיתָא אִיהוּ עַד סוֹף שִׁית, גָּזְרוּ רַבָּנָן, אוֹכְלִין כָּל אַרְבַּע, וְתוֹלִין כָּל חָמֵשׁ, וְשׂוֹרְפִין בִּתְחִלַּת שֵׁשׁ. וְאוֹלְפִי מָארֵי מַתְנִיתִין מִסַהֲדוּתָא דְּשַׁעְתֵּי דְּחָמֵץ, לְסַהֲדוּתָא דִּבְדִיקוֹת דְּסָהֲדֵי, דְּהַהוּא דְּהָרַג אֶת הַנֶּפֶשׁ. וְכֹלָּא מְפֹרָשׁ בְּמַתְנִיתִין. וִיקֻיָים בְּהוֹן, אֲרֵי בְּפִתְגָּמָא דְּחָשִׁיבוּ מִצְרָאֵי לְמֵידָן וְכוּ'. וְהַאי אִיהוּ וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם. <Nonei></i></p>"],[9520012681,"<p><Nonei></i>פִּקּוּדָא בָּתַר דָּא, לְקַבֵּל בֵּית דִּין הַגָּדוֹל עָלַיְיהוּ, בִּינָה, מִסִּטְרָא דִּגְדוּלָה אִקְרֵי אֱלֹהִים, בֵּית דִּין הַגָּדוֹל, רַב בְּדִינוֹי, וְרַב בְּזַכְווֹי, כְּגַוְונָא דְּאִתְּמַר שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ בְּפִקּוּדָא, שׂוֹם לְעֵילָּא, תָּשִׂים לְתַתָּא. הָכִי לְקַבֵּל עָלֵיהּ בֵּית דִּין רַבְרְבָא, אַף עַל גַּב דְּקַבִּיל עָלֵיהּ בֵּית דִּין זְעֵירָא. בֵּית דִּין זְעֵירָא, בֵּית דִּין שֶׁל שְׁלֹשָׁה, מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה. בֵּית דִּין רַבְרְבָא, מֵאִלֵּין סַנְהֶדְּרֵי גְּדוֹלָה.</p>\n<p>אָמַר בּוּצִינָא קַדִּישָׁא, שִׁבְעִים סַנְהֶדְּרֵי גְּדוֹלָה הֲווֹ, וְאַנְתְּ רַבְרְבָא עַל כֻּלְּהוּ, (שמות י״ח:כ״ב) וְהָיָה כָּל הַדָּבָר הַגָּדוֹל יָבִיאוּ אֵלֶיךָ וְכָל הַדָּבָר הַקָּטֹן יִשְׁפְּטוּ הֵם. אֵלּוּ. (הם סנהדרי גדולה, סנהדרי קטנה). סַנְהֶדְּרֵי גְּדוֹלָה מִסִּטְרָא דִּשְׁכִינְתָּא עִלָּאָה, סַנְהֶדְּרֵי קְטַנָּה מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה.</p>\n<p>מֹשֶׁה שׁוּשְׁבִינָא דְּמַלְכָּא, אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא. וְעִמְּהוֹן שִׁבְעִין וּתְרֵין סַנְהֶדְרִין, כְּמִנְיַן חֶסֶד, וּמֵהָכָא סַנְהֶדְּרֵי גְּדוֹלָה. סַנְהֶדְּרֵי קְטַנָּה, מִסִּטְרָא דִּשְׂמָאלָא, (בראשית א׳:ט״ז) אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה.</p>\n<p>וּבְגִין דָּא, תִּפְאֶרֶת אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם, דְּאִתְּמַר בֵּיהּ (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ. אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה, (שם) וּבַלַּיְלָה שִׁירֹה עִמִּי. שִׁיר דִּלְוִיִּים, וְדָא יְסוֹד. (שמואל א כ׳:ל״א) בֶּן יִשַׁי חַי עַל הָאֲדָמָה. דְּתָקִּין עֶשֶׂר מִינֵי תְּהִלִּים, בְּשִׁירָה. וְאִיהוּ צַדִּיק לִשְׂמָאלָא, אֶת הַמָאוֹר הַקָּטֹן, וְדָא שְׁכִינְתָּא, דְּאַתְנְטִילַת מִשְּׂמָאלָא. ע\"כ (יתרו כ\"ג, כבד את אביך וכו') כי תצור אל עיר וכו' עד בהאי עלמא נדפס בפרשת בלק דף קצ\"ו ע\"א.</p>"],[9520012682,"<p><Noneb>רעיא מהימנא</b><br>(דברים כ״ב:י״ט) וְעָנְשׁוּ אוֹתוֹ מֵאָה כֶסֶף וְגוֹ'. פִּקּוּדָא דָּא, לָדוּן בְּדִין מוֹצִיא שֵׁם רָע. הֲדָא הוּא דִכְתִיב, וְעָנְשׁוּ אוֹתוֹ מֵאָה כֶסֶף וְנָתְנוּ לַאֲבִי הַנַּעֲרָה כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. רַבָּנָן, וְהַאי אִיהוּ בָּתַר נִשּׂוּאִין, דְּאָמַר לָא מָצָאתִי לְבִתְּךָ בְּתוּלִים, וְלָאו כָּל שֵׁם רָע שָׁקוּל, דִּמְרַגְלִים דְּאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא, אִתְעֲנָשׁוּ בְּגִינָהּ, וּמִיתוּ וְלָא זָכוּ לָהּ. וְאִתְּתָא קַרְקַע אִיהִי בְּאַרְעָא, כְּמָה דְּאוּקְמוּהָ, אֶסְתֵּר קַרְקַע עוֹלָם הָיְתָה.</p>\n<p>וְאִי תֵּימְרוּן שׁוּם בִּישׁ עָלָהּ, דְּאִסְתְּאָבַת בַּאֲחַשְׁוֵרוֹשׁ, וְזָכְתָה לְאִתְלַבְּשָׁא בָּהּ רוּחָא דְּקֻדְשָׁא. הֲדָא הוּא דִכְתִיב, (אסתר ה׳:א׳) וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. הָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים. וְרוּחָא דְּקֻדְשָׁא שְׁכִינְתָּא הֲוַת, דְּאִיהִי שֵׁם דְּאִתְלַבְּשַׁת בְּאֶסְתֵּר.</p>\n<p>אֲבָל רַבָּנָן, וַוי לְאִינּוּן דְּאַכְלִין תֶּבֶן תְּבֵל דְּאוֹרַיְיתָא (חמור דאורייתא דאתחשיב ח'כם מ'ופלא ו'רב ר'בנן) וְלָא יָדַע בְּסִתְרֵי דְּאוֹרַיְיתָא, אֶלָּא קַלִין וַחֲמוּרִין דְּאוֹרַיְיתָא, קָלִין תֶּבֶן דְּאוֹרַיְיתָא, חוּמְרָא דְּאוֹרַיְיתָא, חִטָּה, חֵט ה', אִילָנָא דְּטוֹב וְרָע.</p>\n<p>לֵית דַּרְכָּא דְּמַלְכָּא וּמַטְרוֹנִיתָא, לְמִרְכַּב עַל חֲמָרָא, אֶלָּא עַל סוּסְוָון. הֲדָא הוּא דִכְתִיב, (חבקוק ג׳:ח׳) כִּי תִרְכַּב עַל סוּסֶיךָ מַרְכְּבוֹתֶיךָ יְשׁוּעָה. דְּאֵין מְזַלְזְלִין בְּמַלְכוּתָא, לְמִרְכַּב מַטְרוֹנִיתָא עַל חֲמָרָא. כָּל שֶׁכֵּן מַלְכָּא, לֵית דֵּין אֲתָר הֶדְיוֹט עֶבֶד, דְּאָרְחֵיהּ לְמִרְכַּב עַל חֲמָרָא. וּבְגִין דָּא כְּתִיב בֵּיהּ בְּמָשִׁיחַ, (זכריה ט׳:ט׳) עָנִי <Nonei></i> וְרוֹכֵב עַל חֲמוֹר. עָנִי אִיהוּ תַּמָּן בְּסִימָן, עֵרוּבִין נִדָּה יְבָמוֹת, וּשְׁאַר מַתְנִיתִין בִּכְלָל. וְלָא אִתְקְרֵי תַּמָּן מֶלֶךְ, עַד דְּרָכִיב בְּסוּסְיָא דִּילֵיהּ כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>קוּדְשָׁא בְּרִיךְ הוּא כַּד אִיהוּ לְבַר מֵאַתְרֵיהּ, לָאו אִיהוּ מֶלֶךְ. וְכַד אִתְהַדָּר לְאַתְרֵיהּ, (זכריה יד) וְהָיָה יְיָ' לְמֶלֶךְ. וְהָכִי יִשְׂרָאֵל, אִתְּמַר בְּהוֹן, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. כְּגַוְונָא דְּאַבָּא, אִינּוּן בְּנוֹי. לָאו אִינּוּן בְּנֵי מְלָכִים, עַד דִּיהַדְרוּן לְאַרְעָא דְּיִשְׂרָאֵל. וְאִי תֵּימָא דְּהֶדְיוֹט דָּא, אַף עַל גַּב דְּאִיהוּ הֶדְיוֹט לְגַבֵּי מָארֵיהּ, עָלֵיהּ אִתְּמַר, אַל תְּהִי בִּרְכַּת הֶדְיוֹט קַלָהּ בְּעֵינֶיךָ. וְהֶדְיוֹט דָּא לְגַבֵּי מַלְכָּא עֶבֶד מְטַטְרוֹן. וְאָדָם קַדְמָאָה דְּלָא נָטַר יְקָר דְּיָהֲבוּ לֵיהּ, נַחְתּוּ לֵיהּ לְמֵיכַל עִם חֲמוֹרִים (חמריה), וְאָמַר אֲנִי וַחֲמוֹרִי נֹאכַל בְּאֵבוּס אֶחָד. וְיִשָּׂשׂכָר בְּהַאי חֲמָרָא, זָכָה לְאִתְקְרֵי (בראשית מ״ט:י״ד) יִשָּׂשׂכָר חֲמוֹר גָּרֶם.</p>\n<p>וְרַבָּנָן מָארֵי מָתְנִיתִין, מַטְרוֹנִיתָא אִתְּמַר בָּהּ (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, בָּתַר דְּאִתְלַבְּשָׁא בֵּיהּ אֶסְתֵּר, שְׁלִיטַת אֶסְתֵּר עַל אֲחַשְׁוֵרוֹשׁ וְאוּמָתֵיהּ. וְאִתְּמַר בְּהוּ (אסתר ט׳:ט״ז) וְהָרוֹג בְּשׂוֹנְאֵיהֶם. וְאִי תֵּימָא דְּאִתְיָיחַד עִמָּהּ. אַף עַל גַּב דַּהֲווֹ בְּבֵיתָא חֲדָא, חַס וְשָׁלוֹם. אֶלָּא, כְּגַוְונָא דְּיוֹסֵף, דְּאִתְּמַר בֵּיהּ, (בראשית ל״ט:ט״ז) וַתַּנַח בִּגְדוֹ אֶצְלָהּ, וְלָא לְבוּשׁוֹ, אֶלָּא בִּגְדוֹ, לִישָׁנָא (ישעיה כד) דְּבוֹגְדִים בָּגָדוּ.</p>\n<p>וְהָכָא סִתְרָא רַבְרְבָא. וּבְגִין דָּא, אֶסְתֵּר, לִישָׁנָא דְּסִתְרָאָהּ, (תהילים ל״ב:ז׳) אַתָּה סֵתֶר לִי, שְׁכִינְתָּא אַסְתִּירַת לָהּ מֵאֲחַשְׁוֵרוֹשׁ, וְיָהִיב לֵיהּ שִׁידָה בְּאַתְרָהּ, וְאִתְהַדְּרַת אִיהִי בִּדְרוֹעֵיהּ דְּמָרְדְּכַי. וּמָרְדְּכַי דְּהֲוָה יָדַע שְׁמָא מְפֹרָשׁ, וְשִׁבְעִין לָשׁוֹן, עֲבַד כָּל דָּא בְּחָכְמְתָא. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, דְּאֲפִילּוּ בְּלָא דָּא, אִית לֵיהּ לְבַּר נָשׁ קוֹדֶם דְּיִתְיָחֵד עִם אִתְּתֵיהּ, לְמַלְּלָא עִמָּהּ, בְּגִין דְּשֶׁמָא שִׁידָה אִתְחַלְּפָא בְּאִתְּתֵיהּ.</p>\n<p>וְדָא בְּאִתְּתָא מֵאִילָנָא דְּטוֹב וָרָע, אֲבָל אִם הִיא מִשְׁכִינְתָּא, לֵית לָהּ שִׁנּוּי, הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ו׳) אֲנִי יְיָ' לֹא שָׁנִיתִי. אֲנִי, דָּא שְׁכִינְתָּא. וְלֵית לָהּ דְּחִילוּ מִכָּל סִטְרִין אַחֲרָנִין. הֲדָא הוּא דִכְתִיב, (ישעיהו מ׳:י״ז) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ.</p>\n<p>וּבְאַתְרָא דִּשְׁכִינְתָּא תַּמָּן, כַּמָה סְגוּלוֹת תַּמָּן. וּבְגִין דְּאֶסְתֵּר אִתְלַבְּשַׁת שְׁכִינְתָּא בָּהּ, חַזְיָא הֲוַת לְמֶעְבַּד עִמָּהּ כַּמָה סְגוּלוֹת (ס\"א צומות). כְּגַוְונָא דְּשָׂרָה, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לָהּ, בְּגִין שְׁכִינְתָּא דַּהֲוַת עִמָּהּ, נָטִיר לָהּ מִפַּרְעֹה, וַאֲפִילּוּ לְבוּשָׁהּ וְתַכְשִׁיטֶיהָ בְּכֻלְּהוּ שַׁוֵּי קוּדְשָׁא בְּרִיךְ הוּא סְגוּלוֹת, בְּגִין שְׁכִינְתָּא. וּבְגִין דָּא, אָתָא פַּרְעֹה לְסַנְדָּלָא, מָחָא לֵיהּ עִמֵּיהּ. וְהָכִי נָמֵי בְּכָל תַּכְשִׁיטִין דִּילָהּ. בְּכָל תַּכְשִׁיט וְתַכְשִׁיט דְּהֲוָה נָגַע בֵּיהּ, מָחֵי לֵיהּ, עַד דְּאִתְפְּרַשׁ מִנָּהּ הַהוּא טָמֵא, וְאַחְזָר לָהּ לְבַעְלָהּ.</p>\n<p>וְאִי בְּתַכְשִׁיטִין דִּילָהּ כַּךְ, כָּל שֶׁכֵּן מַאן דְּנָגַע בְּגוּפָא. וַאֲפִילּוּ בְּאֶצְבַּע דִּילָהּ, לְסִטְרָא דְּיִחוּדָא, (במדבר א׳:נ״א) וְהַזָּר הַקָּרֵב יוּמָת. דְּקוּדְשָׁא בְּרִיךְ הוּא לָא יְהִיב לֵיהּ רְשׁוּ לְמִקְרַב גַּבָּהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן.</p>\n<p>וּבְגִין דָּא, לָא כָּל שֵׁם רָע שָׁקוּל. מְרַגְּלִים דְּאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא דְּיִשְׂרָאֵל מִיתוּ. מַאן דְּאַפִּיק שׁוּם בִּישׁ עַל שְׁכִינְתָּא, כָּל שֶׁכֵּן דְּלַקְיָין בְּנִשְׁמָתְהוֹן. דְּאִלֵּין דְּאַפִּיקוּ שׁוּם בִּישׁ עַל אַרְעָא, לָקוּ בְּגוּפַיְיהוּ, וּמִיתַת גַּרְמַיְיהוּ מִיתוּ. אֲבָל מַאן דְּאַפִּיק שׁוּם בִּישׁ עַל שְׁכִינְתָּא, נִשְׁמְתָא דִּלְהוֹן לָקְאָהּ. וְהַאי לְמַאן דְּיָדַע רָזָא דָּא, וְעֵינוֹי פַּתְחִין. אֲבָל מַאן דְּעֵינוֹי סְתִימִין, לֵית לֵיהּ עוֹנְשָׁא כָּל כַּךְ.</p>\n<p>וּמַה דְּרַבָּנָן דְּמַתְנִיתִין שַׁוְיָין קַמַּיְיהוּ, דְּאִתְּתָא אֲנוּסָה מוּתֶּרֶת לְבַעְלָהּ. וַדַּאי אִיסוּר וְהֶיתֵּר דְּמַתְנִיתִין לָא מְמַלֵּל אֶלָּא בְּמִילֵיהּ דְּבַּר נָשׁ, וְאִתְּתָא דְּאִיהִי מֵאִילָנָא דְּעֵץ הַדַּעַת טוֹב וָרָע. אֲבָל אִתְּתָא דְּאִיהִי מֵאִילָנָא דְּחַיֵּי, לָאו לָהּ דִּינָא כְּאִלֵּין, (דאינון מאילנא דעץ הדעת טוב ורע) דְּהַהוּא דְּאִילָנָא דְּחַיֵּי, צַדִּיק וְטוֹב לוֹ. וּבְגִינֵיהּ אִתְּמַר, (משלי י״ב:כ״א) לֹא יְאוּנֶּה לַצַּדִּיק כָּל אָוֶן, וְלָא לְבַת זוּגוֹ צַדֶּקֶת. וְאוֹלִיפְנָא מִשָׂרָה בְּבֵיתָא דְּפַרְעֹה, דְּלָא הֲוָה לֵיהּ רְשׁוּ לְמִקְרַב בַּהֲדָהּ.</p>\n<p>וּמַאן דְּאִיהוּ צַדִּיק וְרָע לוֹ, הַאי דְּאִיהוּ מֵאִילָנָא דְּטוֹב וָרָע, דְּכֵיוָן דְּרָע עִמֵּיהּ, (קהלת ז) אֵין צַדִּיק אֲשֶׁר לֹא יֶחטָא בְּהַהוּא רָע, בָּתַר דְּאִיהוּ עִמֵּיהּ. רָשָׁע וְטוֹב לוֹ, דְּאִתְגַּבָּר יֵצֶר הָרָע עַל יֵצֶר טוֹב, אִתְּמַר וְטוֹב לוֹ, טוֹב אִיהוּ תְּחוֹת רְשׁוּתֵיהּ, וּבְגִין דְּרָע שַׁלִּיט עַל טוֹב, רָשָׁע אִיהוּ, דְּהַהוּא דְּאִתְגַּבָּר נָטִיל שְׁמָא. רָשָׁע וְרָע לוֹ, אֵל אַחֵר סָמָאֵל, וְרָע לוֹ, סַם הַמָּוֶת דִּילֵיהּ עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, (תהילים ל״ד:כ״ב) תְּמוֹתֵת רָשָׁע רָעָה. וּבְגִין דָּא, אֲנוּסָה לָאו אִיהִי, אֶלָּא אִי אִית בָּהּ תַּעֲרוֹבֶת בְּהַהִיא נִשְׁמְתָא, דְּטוֹב וָרָע.</p>\n<p>וְאוֹרַיְיתָא דְּאִתְבְּרִיאַת (נ\"א דאתייהיבת), אִתְּבָּרוּ לוּחִין דִּילָהּ, דְּאִינּוּן מְשׁוּלִים לַבְּתוּלִים. וְקוּדְשָׁא בְּרִיךְ הוּא הֲדַר יָהִיב לוֹן לְיִשְׂרָאֵל, לְנַטְרָא לָהּ, אוֹרַיְיתָא דְבְּעַל פֶּה אִתְקְרִיאַת הֲלָכָה לְמֹשֶׁה מִסִּינַי. וְחָתָן דִּידָהּ, תָּבַר בְּתוּלִים דִּילָהּ. וּמַאן דְּאַפִּיק שׁוּם בִּישׁ עָלָהּ, דְּיֵימָּא דְּהָא הַהִיא אוֹרַיְיתָא לָאו אִיהִי דָּא, דְּהָא לוּחִין דִּילָהּ אִתְּבָּרוּ. קוּדְשָׁא בְּרִיךְ הוּא יֵימָּא לֵיהּ, דְּאִיהוּ אֲבִי הַנַּעֲרָה. בַּת, דְּאִיהוּ בְּתֵיבַת בְּרֵאשִׁית, אִיהִי בְּרַתָּא דְּמַלְכָּא, קוּדְשָׁא בְּרִיךְ הוּא אָמַר וּפָרְשׂוּ הַשִּׂמְלָה, וְאִתְפַּתְחַת יְרִיעָה מִסֵפֶר תּוֹרָה, וְיֶחֶזּוּן דְּאִתְּמַר בֵּיהּ, (שמות ל״ד:א׳) פְּסָל לְךָ שְׁנֵי לוּחוֹת אֲבָנִים כָּרִאשׁוֹנִים וְכָתַבְתִּי עַל הַלּוּחוֹת אֶת הַדְּבָרִים אֲשֶׁר הָיוּ עַל <Nonei></i> הַלּוּחוֹת הָרִאשׁוֹנִים אֲשֶׁר שִׁבַּרְתָּ.</p>\n<p>מִיַּד קָם אֵלִיָּהוּ, וְכָל מָארֵי מְתִיבְתָּא, וּבָרִיכוּ לֵיהּ, וְאָמְרוּ סִינַי סִינַי, הָכִי אִתְחַזְיָיא לְמִשְׁמַע מִלִּין דִּילָךְ וְלִשְׁתּוּק, אֲבָל בִּרְשׁוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, אֲנָא בָּעֵי לְמַלְּלָא מִלָּה לְגַבָּךְ, לִיקָרָא דִּילָךְ. אָמַר לֵיהּ אֵימָא.</p>\n<p>פָּתַח וְאָמַר, רַעְיָא מְהֵימָנָא, הַאי כַּלָּה דִּילָךְ, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לָהּ לְאַבְרָהָם לְגַדְּלָא לָהּ לְגַבָּךְ, וּבְגִין דְּאִיהוּ נָטִיר לָהּ, אִתְקְרִיאַת בְּרָתֵיהּ. הֲדָא הוּא דְאִתְּמַר, בַּת הָיְתָה לוֹ לְאַבְרָהָם וּבַכֹּל שְׁמָהּ. וּבָהּ קִיֵּים כָּל אוֹרַיְיתָא כֻּלָּהּ, וַאֲפִילּוּ עֵירוּבֵי תַּבְשִׁילִין. הֲדָא הוּא דִכְתִיב, (בראשית כ״ו:ה׳) וַיִּשְׁמוֹר מִשְׁמַרְתִּי וְגוֹ'. וְאִיהוּ הֲוָה לְגַבָּהּ אוֹמֵן, כְּגוֹן (אסתר ב׳:ז׳) וַיְהִי אוֹמֵן אֶת הֲדַסָּה. וְקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לֵיהּ בְּגִינָהּ, הֲדָא הוּא דִכְתִיב, (בראשית כ״ד:א׳) וַיְיָ' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְגַדִּיל לָהּ מִכָּל מִדּוֹת טָבִין, וְגָמִיל לָהּ חֶסֶד, וְסָלִיק לָהּ בִּגְדּוּלָה בְּמִדַּת חֶסֶד דְּאַבְרָהָם, וַהֲוָה בֵּיתֵיהּ בְּגִינָהּ פָּתוּחַ לָרְוָוחָה, לְמִגְמַל חֶסֶד עִם כָּל בָּאֵי עוֹלָם.</p>\n<p>וּבְגִין דְּאִיהוּ גָּמִיל חֶסֶד עִמָּהּ, כַּד בְּנוֹי דְּאַבְרָהָם הֲווֹ מְמוּשְׁכָּנִין בְּכַמָּה חוֹבִין בְּמִצְרַיִם, אָמַר קוּדְשָׁא בְּרִיךְ הוּא לָךְ רַעְיָא מְהֵימָנָא, זִיל וְגָמִיל טִיבוּ, לְמַאן דְּגָמִיל לֵיהּ עִמָּךְ, דְּדָא כַּלָּה דִּילָךְ, יְהִיבַת לָהּ לֵיהּ, לְגַדְּלָא לָהּ בְּמִדּוֹת טָבִין, וְאִיהוּ גָּדִיל לָהּ בִּתְלֵיסָר מְכִילָן דְּרַחֲמֵי, דִּרְמִיזִין בִּתְלַת תֵּיבִין וָה\"וּ אֲנִ\"י וָה\"וּ, דְּאִינּוּן וָא\"ו. דְּכָלִיל בְּהוֹן ע\"ב שְׁמָהָן, כְּמִנְיַן חֶסֶד. דִּבְהוֹן הֲוָה אִתְגַּבָּר אַבְרָהָם עַל ע\"ב אוּמִין וּבְכַלָּה דִּילָךְ, הֲוָה לֵיהּ סְגוּלָה בְּע\"ב שְׁמָהָן, וַהֲוָה נָצַח לְכָל אוּמָה וְלִישָׁן.</p>\n<p>וּבְגִין דָּא, (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּבוֹקֵעַ מַיִם, דְּיַמָּא קַרְעַת לֵיהּ קֳדָם בְּנוֹי, בִּתְרֵיסַר קְרָעִין, בְּחוּשְׁבָּן וָ\"ו, וּבִזְכוּת א' (ס\"א ובגינה) עַבְרַת (ס\"א עבדת) יַמָּא יַבֶּשְׁתָּא. וּבָהּ טוּבְּעוּ מִצְרַיִם, דְּלָא מֵהֵימְנִין בְּוָא\"ו דְּאִיהוּ אֶחָד. וּלְזִמְנָא דְּאָתֵי, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, יִתְקַיֵּים בְּיִשְׂרָאֵל זַרְעָא דְּאַבְרָהָם. וּבָךְ יִתְקַיֵּים, (דאנת) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ (זרע דאברהם) וּבוֹקֵעַ מַיִם דְּאוֹרַיְיתָא קֳדָמֵהוֹן, לְמֶהֱוֵי לָךְ שֵׁם עוֹלָם. וְתַמָּן תַּרְוִיחַ כַּלָּה דִּילָךְ.</p>\n<p>וּבְגִין דְּבַת דָּא, אִתְיְיהִיבַת לְיִשְׂרָאֵל, דְּאִיהִי הֲלָכָה דִּילָךְ, מִסִּטְרָא דִּשְׂמָאלָא, הֲלָכָה לְמֹשֶׁה מִסִּינַי. דְּהָא מִסִּטְרָא דִּימִינָא, ה' הֲלָכָה דִּילָךְ, מִסִּטְרָא דִּשְׁמָא דְּאַבְרָהָם. י' דְּיִצְחָק. וְכֹלָּא הֵ\"י מִן אֱלֹהִים. וְאַנְתְּ וָא\"ו, מָלֵא דִּילָהּ, שְׁלֵימוּת דִּילָהּ, כּוֹס מָלֵּא. בְּקַדְמִיתָא כֵּ\"ס יָ\"הּ, וּלְבַסּוֹף כּוֹס מָלֵּא בִּרְכַּת יְיָ'.</p>\n<p>וּבְגִין דְּאִתְיְיהִיבַת לְיִשְׂרָאֵל עַל יְדָךְ, דְּאִינּוּן מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, אִית לְגַלָּאָה אֲמַאי אִתְיְיהִיבַת לוֹן דְּהָא וַדַּאי אַבְרָהָם הָא אִתְּמַר אֲמַאי אִתְיְיהִיבַת לֵיהּ. וְאַנְתְּ גְּמִילַת חֶסֶד עִם בְּנוֹי, כְּגַוְונָא דְּגָמִיל הוּא עִמְּךָ. לְיִצְחָק יָהַב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לֵיהּ וּלְזַרְעֵיהּ, לְנַטְרָא (נ\"א לעטרא) לָהּ מֵאִילָנָא דְּטוֹב וָרָע. וְעַבְדּוּ לָהּ כַּמָה גְּדָרִין, וַחֲתִּיכוּ לָהּ כַּמָה לְבוּשִׁין, דְּאִינּוּן לְבוּשֵׁי דַּהֲבָא, בְּכַמָּה פְּסָקוֹת. וַהֲווּ חוֹלְקִין וּמַקְשִׁין עָלַיְיהוּ עַל אִלֵּין פְּסָקוֹת, לְתַקְּנָא לָהּ בְּכַמָּה פִּרוּקִין, לְקַשֵּׁט לָהּ בְּכַמָּה מִינֵי קִשּׁוּטִין, לְשַׁבָּתוֹת וְיָמִים טוֹבִים, לְמֶהֱוֵי מְקֻשָּׁטָא לְגַבָּךְ בְּזִמְנָא דְּתֵיתֵי לְגַבָּהּ בְּפוּרְקָנָא בַּתְרַיְיתָא, דְּאִתְּמַר בָּהּ (קהלת א) מַ\"ה שֶּׁ\"הָיָה ה\"וּא. (חסר כאן)</p>\n<p>וּבְגִין דְּאִינּוּן גָּרְמוּ לָךְ, וַעֲבִידוּ עִמָּךְ טָבִין, אַנְתְּ סְבִילַת בְּגִינַיְיהוּ כַּמָה מַכְתְּשִׁין, בְּגִין דְּלָא יִתְקְטִיל מָשִׁיחַ בֶּן יוֹסֵף, דְּאִתְּמַר בֵּיהּ (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל, מִזַּרְעָא דְּיוֹסֵף, דְּאִתְּמַר בֵּיהּ (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. וּבְגִין דְּלָא יִתְחַלֵּל הוּא וְזַרְעֵיהּ בֵּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, בְּחוֹבֵיהּ דְּיָרָבְעָם דְּעֲבַד עֲבוֹדָה זָרָה, הֲוָה הוּא לְאִתְחַלְּלָא בְּעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת הוּא וְזַרְעֵיהּ, בְּגִין דְּיָרָבְעָם בֶּן נְבָט מִזַּרְעֵיהּ אִיהוּ, בְּגִינֵיהּ אִתְּמַר בָּךְ, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ וְגוֹ', וּבַחֲבוּרָתוֹ נִרְפָּא לָנוּ.</p>\n<p>וְיִשְׂרָאֵל בְּגִין דְּאִינּוּן כְּלִילָן יְמִינָא וּשְׂמָאלָא, תַּמָּן הֵ\"י דִּילָךְ בִּשְׁלִימוּ הֲוָה, אִית לָךְ לְאִתְיַחֲדָא עִמָּהּ בֵּינַיְיהוּ. וּבְגִין דְּאִתְּמַר בָּךְ, כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל, אִתְּמַר בָּךְ וְלוֹ תִהְיֶה לְאִשָּׁה, לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו, בְּגָלוּתָא לָא יָכִיל לְמִפְרַשׁ לֵיהּ מִנָּהּ כָּל יוֹמוֹי.</p>\n<p>וְאֵיךְ הוּא שֵׁם רָע דְּאַפִּיקַת עַלָהּ. אֶלָּא בָּתַר דְּאִתְיְיהִיבַת אִיהִי לְיִשְׂרָאֵל, כָּל מַאן דְּאַפִּיק שׁוּם בִּישׁ עַל יִשְׂרָאֵל, כְּאִילּוּ אַפִּיק עָלָהּ. וְשׁוּם בִּישׁ הֲוָה, דְּאַמָרְת לְקוּדְשָׁא בְּרִיךְ הוּא, (שמות ל״ב:י״א) לָמָה יְיָ' יֶחרֶה אַפְּךָ בְּעַמֶּךָ. וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר, וְכִי אַנְתְּ אַפִּיק שׁוּם בִּישׁ עַל יִשְׂרָאֵל דְּעַבְדּוּ יַת עֶגֶל, לֵךְ רֵד כִּי שִׁחֵת עַמְּךָ. עֶרֶב רַב וַדַּאי, דְּאַנְתְּ גַּיְירַת לוֹן עַבְדוּ יַת עֶגְלָא. וּבְגִין דָּא כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל וְלוֹ תִהְיֶה לְאִשָּׁה.</p>\n<p>קָם רַעְיָא מְהֵימָנָא, נָשִׁיק לֵיהּ בְּאַנְפּוֹי, וְעַל עֵינוֹי וּבָרִיךְ לֵיהּ, וְאָמַר לֵיהּ, תְּהֵא מְבֹרַךְ מִפּוּמָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, בְּכָל מִדָּה וּמִדָּה דִּילֵיהּ, וּבְעֶשֶׂר סְפִירָן דִּילֵיהּ, וּבְכָל שְׁמָהָן דִּילֵיהּ, וּבְכָל מָארֵי מְתִיבְתָּאן, וּבְכָל מַלְאָכִין. וְעָנּוּ כֻּלְּהוּ וְאָמְרוּ אָמֵן. וְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ הוֹדוּ בְּבִרְכָתֵיהּ. אֵלִיָּהוּ, קוּם אַפְתַּח פּוּמָךְ בְּפִקּוּדִין עִמִּי, דְּאַנְתְּ הוּא עוֹזֵר דִּילִי, מִכָּל <Nonei></i> סִטְרָא, דְּהָא עֲלָךְ אִתְּמַר בְּקַדְמִיתָא, (במדבר כח) פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, בֶּן אַהֲרֹן וַדַּאי, בֶּן אָח דִּילִי הוּא, (משלי י״ז:י״ז) וְאָח לְצָרָה יִוָּלֵד. (נשא קכ\"ד ע\"א פקודא לדון בדיני סוטה)</p>"],[9520012683,"<p>כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה אֲשֶׁר לֹא אוֹרָשָׂה וְגוֹ'. פִּקּוּדָא דָּא, לָדוּן בִּמְפַתֶּה חַמִשִׁים כֶּסֶף. הֲדָא הוּא דִכְתִיב, כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה אֲשֶׁר לֹא אוֹרָשָׂה. אִלֵּין יִשְׂרָאֵל, מִסִּטְרָא דִּשְׁכִינְתָּא אִתְקְרִיאוּ בַּת. וּתְפָשָׂהּ וְשָׁכַב עִמָּהּ וְנִמְצָאוּ וְנָתַן לַאֲבִי הַנַּעֲרָה חֲמִשִּׁים כֶסֶף וְלוֹ תִהְיֶה לְאִשָּׁה לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו. רַבָּנָן וְכָל מָארֵי מְתִיבְתָּא, אִישׁ, אִלֵּין יִשְׂרָאֵל, מִסִּטְרָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּתְפָשָׂהּ, בְּקִשּׁוּרָא דִּתְפִילִּין. וּתְפָשָׂהּ, בְּכַנְפֵי מִצְוָה. אֲשֶׁר לֹא אוֹרָשָׂה, בַּת יְחִידָה, דָּא נְשָׁמָה. וְשָׁכַב עִמָּהּ, בִּצְלוֹתָא דִּשְׁכִיבָא, בְּהַשְׁכִּיבֵנוּ. וְנָתַן לַאֲבִי הַנַּעֲרָה חֲמִשִּׁים כָּסֶף, כ\"ה כ\"ה אַתְוָון דְּיִחוּדָא.</p>\n<p>קוּם רַעְיָא מְהֵימָנָא, דְּוַדַּאי מַאן דְּאִשְׁתְּדַל בַּהֲלָכָה שֶׁלֹּא לִשְׁמָהּ, וְרָוַוח הֲלָכָה, וַדַּאי בִּתְפִישָׂה אִיהִי לְגַבֵּיהּ. וְעִם כָּל דָּא אוֹקְמוּהָ, לְעוֹלָם יַעֲסוֹק אָדָם בַּתּוֹרָה אֲפִילּוּ שֶׁלֹּא לִשְׁמָהּ, שֶׁמִתּוֹךְ שֶׁלֹּא לִשְׁמָהּ בָּא לִשְׁמָהּ. וְהַאי הֲלָכָה מִסִּטְרָא דְּנַעַר טוֹב, דְּאִתְפְּרַשׁ מֵאִילָנָא דְּטוֹב וָרָע, דְּאִיהוּ אִיסוּר וְהֶיתֵּר, טוּמְאָה וְטָהֲרָה, כָּשֵׁר וּפָסוּל. וְעַל שֵׁם נַעַר, אִתְקְרִיאַת אִיהִי נַעֲרָה. דְּעָתִיד לְקַיֵּים בָּהּ, (איוב ל״ח:י״ג) וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה, דְּאִינּוּן אִיסוּר טָמֵא וּפָסוּל, סָמָאֵל וּמַשִּׁרְיָיתֵיהּ.</p>\n<p>דָּבָר אַחֵר כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה, אִלֵּין יִשְׂרָאֵל, דִּכְתִּיב, (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאוֹהֲבֵהוּ, נַעַר מִסְּטָר דִּמְטַטְרוֹ\"ן. וְאֵין אִישׁ אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, שֶׁנֶּאֱמַר (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה. כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה, בְּתוּלַת יִשְׂרָאֵל, דְּאִתְּמַר בָּהּ (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. (הושע ב׳:ט״ז) הִנֵּה אָנֹכִי מְפַתֶּיהָ וְהוֹלַכְתִּיהָ הַמִּדְבָּר, וּלְבָתַר אַפְתַּח לוֹן חַמְשִׁין תַּרְעִין דְּחֵירוּ, דְּאִינּוּן חַמְשִׁין תַּרְעִין דְּרַחֲמֵי, מִסִּטְרָא דְּאַבְרָהָם אֲבוּהוֹן. וְהַאי אִיהוּ וְנָתַן לַאֲבִי הַנַּעֲרָה חֲמִשִּׁים כָּסֶף, וְכֶסֶף מִדַּרְגָּא דְּחֶסֶד, דַּרְגָּא דְּאַבְרָהָם.</p>\n<p>דִּבְמִפְקָנוּ דְּמִצְרַיִם, חַמְשִׁין תַּרְעִין דְּחֵירוּ אַפְתַּח לוֹן, מִסִּטְרָא דְּדִינָא דִּשְׂמָאלָא, דְּאִיהוּ אֲדֹנָי, דְּתַמָּן (בראשית ט״ו:י״ד) דָּן אָנֹכִי. קֹדֶם דִּינָא דָּן אָנֹכִי, וּלְבָתַר נַפְקוּ. אֲבָל בְּפוּרְקָנָא בַּתְרַיְיתָא, (ישעיהו נ״ד:ז׳) וּבְרַחֲמִים גְּדוֹלִים, מִסִּטְרָא דְּאַבְרָהָם, וּגְדוּלָּה דַּרְגָּא דְּאַבְרָהָם, דְּבִינָה, תַּמָּן אִיהִי יַד הַגְּדוֹלָה, תַּמָּן אִיהִי נ' כָּסֶף. וּלְבָתַר לֹא יוּכַל שַׁלְחָהּ בְּגָלוּתָא כָּל יָמָיו, בְּגִין דְּלוֹ תִהְיֶה לְאִשָּׁה, כְּמָה דְּאִתְּמַר (הושע ב׳:כ״א) וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם. וּקְרָא אַחֲרִינָא, (ישעיהו נ״ד:ה׳) כִּי בוֹעֲלַיִךְ עוֹשַׂיִךְ יְיָ' צְבָאוֹת שְׁמוֹ. (ישעיהו ס״ב:ד׳) לֹא יֵאָמֵר לָךְ עוֹד עֲזוּבָה. דְּאַף עַל גַּב דִּשְׁכִינְתָּא אִיהִי בְּגָלוּתָא, קוּדְשָׁא בְּרִיךְ הוּא לָא זָז מִנָּהּ.</p>"],[9520012684,"<p>פִּקּוּדָא בָּתַר דָּא, לִישָׂא אֲנוּסָתוֹ. דְּוַדַּאי אֲנוּסָה אִית מִתְּרֵין סִטְרִין, אֲנוּסָה בִּרְחִימוּ דִּילֵיהּ לְגַבָּהּ, וְאִיהִי לָא רְחִימַת לֵיהּ. וְאִית אֲנוּסָה דִּרְחִימַת אִיהִי לֵיהּ, וּדְחִילַת לְאִזְדַּוְּוגָא עִמֵּיהּ בְּלָא קִדּוּשִׁין וּבְרָכָה, וְאִיהִי לָא בָּעָאת אִם הִיא הֶדְיוֹטָא לְגַבֵּיהּ, וְלוֹ תִּהְיֶה לְאִשָּׁה.</p>\n<p>בְּסִתְרֵי תּוֹרָה, אִית לָן לְהַמְשִׁיל מָשָׁל, נִשְׁמְתָא אִית דְּאִיהִי מַטְרוֹנִיתָא. וְנִשְׁמְתָא אִית, דְּאִיהִי אָמָה. כְּגוֹן (שמות כ״א:ז׳) וְכִי יִמְכּוֹר אִישׁ אֶת בִּתּוֹ לְאָמָה. וְנִשְׁמְתָא אִית, דְּאִיהִי שִׁפְחָה הֵדְיוֹטָא דְּבַּר נָשׁ. אוּף הָכִי, אִית דְּאִיהוּ עֶבֶד שִׁפְחָה לְגַבֵּי נִשְׁמְתָא. וּלְזִמְנִין נִשְׁמְתָא אַזְלָא בְּרָזָא דְּגִלְגּוּלָא, הֲדָא הוּא דִכְתִיב, (בראשית ח׳:ט׳) וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ לְכַף רַגְלָהּ, וְיֵצֶר הָרָע רָדִיף אֲבַּתְרָהָא, לְאַעֲלָא בְּגוּפָא, דְּאִיהוּ שִׁפְחָה לְגַבֵּי יֵצֶר הָרָע. אִיהוּ שֵׁד יְהוּדִי. וְנִשְׁמְתָא י', אַמָּה הָעִבְרִיָּה. וּבָהּ הַהוּא שֵׁד, אִתְהַדָּר שַׁדַּי, דְּנָטִיר לָהּ לְהַהִיא נִשְׁמְתָא, וְתָב בָּהּ בְּתִיּוּבְתָּא, וּמְבָרֵךְ בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא בְּבָרוּך. וּמְקַדֵּשׁ בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּקָדשׁ קָדשׁ קָדשׁ. וּמְיַחֵד עִמָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּקְרִיאַת שְׁמַע.</p>\n<p>מַה דְּהֲוָה אִיהוּ שֵׁד, אִתְהַדָּר מַלְאָךְ דִּידֵיהּ מְטַטְרוֹן, (רוחא מניה) וְאִתְהַדָּר שַׁדַּי דְּהָכִי סָלִיק (מטטרון) בִּמְטַטְרוֹן, בְּחוּשְׁבַּן שַׁדַּי. וּמִיַּד יִתְקְיָּים בֵּיהּ, וְלוֹ תִהְיֶה לְאִשָּׁה לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו. וְאִי לָא חָזַר בְּתִיוּבְתָּא, אִיהִי לְגַבֵּיהּ מִשְׁתַּעְבְּדָא בְּחוֹבִין דְּעַבְדַּת, וְיִתְקְיָּים בֵּיהּ (שמות כ״א:ד׳) הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדוֹנֶיהָ. וְאִתְּמַר בְּהַהוּא שֵׁד בַּעַל חוֹבֵיהּ, וְהוּא יֵצֵא בְּגַפּוֹ. וְהַאי שֵׁד, אִיהוּ כְּמַטֶּה דְּמֹשֶׁה, דְּאִתְהַפָּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָחָשׁ לְמַטֶּה, הָכִי הַאי שֵׁד, אִתְהַפָּךְ מִשֵׁד לְמַלְאָךְ, וּמִמַלְאָךְ לְשֵׁד, כְּפוּם עוֹבָדוֹי דְּבַר נָשׁ.</p>\n<p>וְעַל שֵׁם שֵׁדִים דְּאָתוּ מֵהַאי, אוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּאִית מִנְּהוֹן כְּמַלְאָכֵי הַשָּׁרֵת, וְאִינּוּן תַּלְמִידֵי חֲכָמִים דְּיַדְעִין מַאי דְּהֲוָה, וּמַה דְּעָתִיד לְמֶהֱוֵי. וְאִינּוּן בְּדִּיוּקְנַיְיהוּ בְּאַרְעָא, אִינּוּן מָארֵי פִּילוֹסוֹפְיָא, אִצְטַגְנִינֵי יִשְׂרָאֵל, דְּיַדְעִין מַאי דְּהֲוָה, וּמַאי דְּעָתִיד לְמֶהוֵי, מֵאוֹתוֹת דְּחַמָּה וְסִיהֲרָא, לָקוּתָא דִּלְהוֹן, וְכָל כֹּכָב וּמַזָּל, וּמָה אַחְזֵי בְּעָלְמָא.</p>\n<p>וְאִית מִנְּהוֹן <Nonei></i> כַּבְּהֵמָה, פָּרִין וְרָבִין כַּבְּהֵמָה, דִּיּוּקְנָא דִּלְהוֹן לְתַתָּא אִינּוּן עַמֵּי הָאָרֶץ, וְאוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּאִינּוּן שֶׁקֶץ, וּבְנוֹתֵיהוֹן שֶׁרֶץ. וְעַל בְּנוֹתֵיהֶן נֶאֱמַר, (דברים כ״ז:כ״א) אָרוּר שׁוֹכֵב עִם כָּל בְּהֵמָה. וְאִינּוּן שׂוֹנְאִים לְתַּלְמִידֵי חֲכָמִים מָארֵי מִשְׁנָה, דְּאִינּוּן מַלְאֲכֵי הַשָּׁרֵת מַמָּשׁ. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, עַל בַּר נָשׁ אִי יְהֵא (מלאכי א) כְּמַלְאַךְ יְיָ' צְבָאוֹת תּוֹרָה יְבַקְשׁוּ מִפִּיהוּ, וְאִי לָאו לֹא יְבַקְשׁוּ תּוֹרָה מִפִּיהוּ.</p>"],[9520012685,"<p>וְאִית אַחֲרָנִין מָארֵי סִתְרֵי תּוֹרָה, מָארֵי מִדּוֹת, דְּאִינּוּן יָרְתִין נִשְׁמָתִין מִסִּטְרָא דְּמַלְכוּתָא קַדִּישָׁא, דְּאִיהוּ כְּלִילָא מֵעֶשֶׂר סְפִירָן. דְּמַאן דְּיָרִית לָהּ, וְזָכֵי לָהּ, זָכֵי לְעֶשֶׂר סְפִירָן בְּלָא פִּרוּדָא, עֶשֶׂר וְלָא תְּשַׁע, דְּאִי הֲווֹ יָרְתִין לְמַלְכוּתָא יְחִידָאָה, הֲווֹ תְּשַׁע בְּפִרוּדָא מִנָהּ, בְּגִין דְּלֵית תַּמָּן פִּרוּדָא, אָמַר בַּעַל סֵפֶר יְצִירָה עֶשֶׂר וְלֹא תֵּשַׁע.</p>\n<p>וְאִי תֵּימָא דִּסְלִיקַת לְעֵילָּא מֵעֶשֶׂר. שְׁמָא מְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, הָא עֶשֶׂר, יוֹ\"ד דְּמִתְיַיחֵד בָּהּ, וְלָא סְלִיק לְעֵילָּא מֵעֶשֶׂר. וּבְגִין דָּא י', וְלָא י\"א. אֲבָל מַאן דִּמְחַבֵּר יוֹ\"ד, דְּאִיהִי אוֹת בְּרִית, בְּשִׁפְחָה. וּמַטְרוֹנִיתָא כְּלִילָא מִי', בְּשֵׁד דְּעֲבוֹדָה זָרָה סָמָאֵ\"ל אִתְּדָּן בַּגֵיהִנָּם.</p>\n<p>דְּמַאן דְּיָרִית בְּרַתָּא דְּמַלְכָּא מַלְכוּת, לָא זָכֵי לָהּ, אֶלָּא בְּרָא דְּמַלְכָּא, דְּאִתְקְרֵי (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל, דְּמִסְטְרָא דָּא אִתְקְרִיאוּ יִשְׂרָאֵל בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם, וּמַלְכוּת דָּא דַּאֲצִילוּת.</p>\n<p>וְאִית לְקַבְּלָהּ מַלְכוּת דִּבְרִיאָה, וְאִיהִי מַלְכוּת לְמַלְאָכִים דִּבְרִיאָה. וְאִיהִי נַעֲרָה דְּמַטְרוֹנִיתָא, מְשַׁמְּשָׁא דִּילָהּ, וְאִיהִי דִּיּוּקְנָא דִּגְבִירְתָּא דִּילָהּ, כְּלוּלָה מִי'. הַאי בְּחוֹבִין דְּיִשְׂרָאֵל, יָכִילַת לְאִתְחַלְּלָא בֵּין אוּמִין דְּעָלְמָא. אֲבָל מַלְכוּת דַּאֲצִילוּת דְּקוּדְשָׁא בְּרִיךְ הוּא, עָלָהּ אִתְּמַר (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים, לָא יָהִיב לָהּ לְמַאן דִּמְחַלֵּל שַׁבָּתוֹת וְיָמִים טוֹבִים, אֶלָּא לְמַאן דְּאִיהוּ בְּרָא דְּמַלְכָּא, וְנָטִיר אוֹרַיְיתָא וּפִקּוּדִין, בִּדְחִילוּ וּרְחִימוּ דְּמָארֵיהּ, וְלָא עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא כְּבֵן דְּאִיהוּ מְחוּיָב לְמֶעְבַּד צִוּוּיֵיהּ דַּאֲבוֹי, דְּעָלֵיהּ אִתְּמַר (שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ. אֶת אָבִיךָ דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאֶת אִמֶּךָ דָּא שְׁכִינְתָּא. וְעִם כָּל דָּא, מַאן דִּמְחַלֵּל נַעֲרָה דְּמַלְכָּא, אִתְחֲשִׁיב לֵיהּ כְּאִלּוּ מְחַלֵּל מַטְרוֹנִיתָא דִּילֵיהּ.</p>\n<p>וְרַבָּנָן, כָּל שֵׁדִין לָאו אִינּוּן שְׁקוּלִין, וְלָא כָּל עַבְדִּין דִּשְׁכִינְתָּא, דִּכְתִּיב בָּהּ, (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. אִית לָהּ כַּמָה נַעֲרוֹת עִבְרִיּוֹת, וּשְׁפָחוֹת עִבְרִיּוֹת. וְאִית לָהּ עֲבָדִים וּשְׁפָחוֹת נָכְרִיּוֹת, בְּגִין דְּלָא יִשְׁתְּכַּח מַלְכוּתָא אָחֳרָא בְּעָלְמָא, בְּזִמְנָא דְּאִיהִי שַׁלְטָא.</p>"],[9520012686,"<p>וְאִלֵּין שְׁפָחוֹת נָכְרִיּוֹת, מִסִּטְרָא דְּסַם הַמָּוֶת, נוּקְבָּא דְּסָמָאֵל. דְּשִׁפְחָה הֲוַת לְמַטְרוֹנִיתָא. נוּקְבָּא וְסָמָאֵל אֵל אַחֵר, עֶבֶד הֲוָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לְבָתַר דַּעֲבִידוּ גַּרְמַיְיהוּ אֱלוֹהוּת, וְקוּדְשָׁא בְּרִיךְ הוּא עָתִיד לְאַעְבָּר לוֹן מֵעָלְמָא, וּלְמִמְחֵי לוֹן.</p>\n<p>וְאִי תֵּימְרוּן, אִי בְּנֵי נָשָׁא עַבְדִּין לוֹן אֱלֹהוּת, וְלָא בִּרְעוּתָא דִּלְהוֹן, אֲמַאי אִתְעֲנָשׁוּ. אֶלָּא כַּד הֲווֹ דּוֹר הַמַּבּוּל וְדוֹר הַפְלָגָה יַדְעֵי בְּהוֹן, וַהֲווּ מְקַטְרְגִין (נ\"א מקטרין) לוֹן, וְסַגְדִּין לוֹן, וּבְהַהוּא חֵילָא דַּהֲווֹ מְקַטְרְגִין (נ\"א מקטרין) לוֹן, וְסַגְדִּין לוֹן, הֲווֹ נַחְתֵּי לְגַבַּיְיהוּ, וְעַבְדֵי רְעוּתַיְיהוּ, וּמְמַלְּלָן בְּהוֹן בְּאִינּוּן צוּלְמִין, הָא אִתְעָבִידוּ אֱלוֹהוּת וְעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. בְּגִין דָּא, קוּדְשָׁא בְּרִיךְ הוּא עָתִיד לְאַעְבְּרָא לוֹן, וְיִמְחֵי לוֹן מֵעָלְמָא, צוּלְמִין דִּלְהוֹן דַּהֲווֹ פַּלְחִין בְּהוֹן, וְאִשְׁתַּאֲבוּ מִנְּהוֹן רוּחִין וְצוּלְמִין.</p>\n<p>וְכַד אִית בְּעָלְמָא עֵרֶב רַב, נַחְתִּין לְאִתְגַּשְּׁמָא בְּהוֹן, וְקוּדְשָׁא בְּרִיךְ הוּא יַעְבַּר לוֹן מִן עָלְמָא, הֲדָא הוּא דִכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאִי תֵּימְרוּן, בְּזִמְנָא דְּגָלוּתָא בַּתְרָאָה, לֵית עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דְּלָא יַדְעִין בְּנֵי עָלְמָא בְּהוֹן. וְאִינּוּן דְּיַדְעִין בְּעֵרֶב רַב תַּמָּן, אִשְׁתְּכַח לוֹן דְּמַכְעִיסִין לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְיִשְׂרָאֵל בֵּינַיְיהוּ, וְעֵרֶב רַב מַצְלִיחִין בְּהוֹן, לְקַיֵּים מַאי דִּכְתִּיב, (דברים ז׳:י׳) וּמְשַׁלֵּם לְשׂוֹנְאָיו אֶל פָּנָיו לְהַאֲבִידוֹ.</p>\n<p>קָמוּ כֻּלְּהוּ תַּנָאִין וַאֲמוֹרָאִין וּבָרִיכוּ לְרַעְיָא מְהֵימָנָא, וְאָמְרוּ לֵיהּ סִינַי סִינַי, מַאן יָכִיל לְמַלְּלָא קֳדָמָךְ, דְּאַנְתְּ בְּדִיּוּקְנָא דְּמָארָךְ, דִּבְזִמְנָא דְּמַלִּיל בְּטוּרָא דְּסִינַי, כָּל חֵיוָן דְּמַלְאָכִין, וְחֵיוָן דְּכֻרְסְיָיא, וְעִלָּאִין וְתַתָּאִין, שַׁתְקוּ, וְלָא אִשְׁתְּכַח דִּבּוּר אָחֳרָא אֶלָּא דִּילֵיהּ. וּבְגִין דְּאַתְּ בְּרֵיהּ בְּדִיּוּקְנָא דִּילֵיהּ, צָרִיךְ לְמִשְׁמַע כֻּלְּהוּ מָארֵי מְתִיבְתָּא מִלִּין מִפּוּמָךְ, אַל תִתֵּן שְׁתִיקָה לְמִלּוּלָךְ. (קרח קע\"ח ע\"ב כל פטר רחם)</p>"],[9520012687,"<p>כִּי יִקַּח אִישׁ אִשָּׁה חֲדָשָׁה לֹא יֵצֵא בַּצָּבָא וְגוֹ'. וְשִׂמַּח אֶת אִשְׁתּוֹ אֲשֶׁר לָקָח. פִּקּוּדָא (טו) דָּא, חָתָן לְמֶחְדֵּי בְּאִתְּתֵיהּ שַׁתָּא חַד, דִּכְתִּיב נָקִי יִהְיֶה לְבֵיתוֹ שָׁנָה אֶחָת. וְאִינּוּן י\"ב יַרְחִין אִינּוּן מִדִילָהּ. דְּהָא שָׁנָה אִיהִי כַּלָּה, וְלֵית כַּלָּה בַּר בְּי\"ב יַרְחִין, דִּכְתִּיב, (מלכים א ז׳:מ״ד) עוֹמֵד עַל שְׁנֵים עָשָׂר בָּקָר. וְהוֹאִיל וְלֵית תִּקּוּנָא דְּכַלָּה, בַּר בְּי\"ב, אִצְטְרִיךְ חָתָן לְמֶחְדֵּי לָהּ, וּלְבֵיתָה, לָהּ וּלְתִקּוּנָהָא, כְּגַוְונָא דִּלְעֵילָּא. וְעַל דָּא יַעֲקֹב כְּתִיב בֵּיהּ, (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. אַבְנֵי הַמָּקוֹם י\"ב הֲווֹ, וּמַאן דְּחַדֵּי לְכַלָּה, חַדֵּי לְעוֹלֵימְתָהָא, <Nonei></i> וְעוּלֵימָתָן י\"ב הֲווֹ. וְכֹלָּא אִיהוּ רָזָא דְּשָׁנָה. בְּגִין כַּךְ אִצְטְרִיךְ לְחָתָן לְמֶחְדֵּי בְּאִתְּתֵיהּ שָׁנָה אֶחָת.</p>\n<p>וְהָא אוֹקִימְנָא, דְּחֶדְוָה דָּא, לָאו דִּילֵיהּ הִיא, אֶלָּא דִּילָהּ. דִּכְתִּיב וְשִׂמַּח אֶת אִשְׁתּוֹ. וְיִשְׂמַח אֶת אִשְׁתּוֹ לָא כְּתִיב, אֶלָּא וְשִׂמַּח, יַחְדֵּי לְכַלָּה. כְּגַוְונָא דָּא, לָאו חֵדוּ לְכַלָּה, בַּר בְּגוּפָא וְתִקוּנָהָא. וּמַאן חַדֵּי לוֹן. צַדִּיק. וְעַל דָּא נָקִי יִהְיֶה לְבֵיתוֹ. נָקִי, דְּלָא יַעֲמוֹל בְּמִלֵּי דְּעָלְמָא, דִּיהֵא בֵּיהּ רַעֲוָא לְמֶחְדֵּי לָהּ. נָקִי מִכֹּלָּא. נָקִי לְמַסִּין וּלְאַרְנוּנִין וְגוּלְגַלְתִּין. נָקִי דְּלָא יִפּוּק לְחֵילָא לְאַגָחָא קְרָבָא. לְאִשְׁתַּכְּחָא חֶדְוָה עֵילָּא וְתַתָּא, וּלְאַתְעֲרָא חֶדְוָה לְעֵילָּא. זַכָּאִין עַמָּא קַדִּישָׁא, דְּמָארֵיהוֹן חַדֵּי בְּהוֹן, זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.</p>"],[9520012688,"<p>(פקודא י\"ו למיהך בר נש באורחוי דקודשא בריך הוא, פקודא י\"ז לאורחא וכו' פ\"ה ע\"ב) (דברים כ״ד:ט״ו) בְּיוֹמוֹ תִּתֵּן שְׂכָרוֹ וְגוֹ'. פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, פִּקּוּדָא בָּתַר דָּא, לָתֵת שְׂכַר שָׂכִיר בִּזְמַנּוֹ. הֲדָא הוּא דִּכְתִיב, בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ. מָארֵי מְתִיבְתָאן עִלָּאֵי וְתַתָּאֵי, שְׁמָעוּ. מְטַטְרוֹן אִיהוּ שְׂכַר שָׂכִיר, מֵחַ\"י עָלְמִין, שְׁלִיחַ דִּילֵיהּ, לְקַבְּלָא חַ\"י בִּרְכָאן דִּצְלוֹתָא, בְּכָל יוֹמָא, תְּלַת זִמְנִין. וּבְגִין דָּא, בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ, דָּא צְלוֹתָא דְּשַׁחֲרִית. וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ, דָּא צְלוֹתָא דְּמִנְחָה, דְּאִי עָבַר יוֹמוֹ, בָּטֵל קָרְבָּנוֹ. כִּי עָנִי הוּא (דצדיק) וַדַּאי, עָנִי הוּא בְּגָלוּתָא, לֵית לֵיהּ מִדִּילֵיהּ, אֶלָּא מַאי דְּיַהֲבִינָן לֵיהּ בִּצְלוֹתָא, בְּגִין דָּא צְלוֹתָא תְּפִלָּה דִּילֵיהּ, (תהילים ק״ב:א׳) תְּפִלָּה לְעָנִי כִּי יַעֲטוֹף, בַּעֲטִיפַת צִיצִית, תְּפִלָּה דְּיָד אִיהִי.</p>\n<p>וְאֵלָיו הוּא נוֹשֵׂא אֶת נַפְשׁוֹ, דָּא תְּפִלַּת עַרְבִית, דְּאִיהִי אֱמוּרִים וּפְדָרִים, שִׁיּוּרִין דְּקָרְבְּנִין דְּיוֹמָא. וְאִינּוּן כְּגוֹן פֶּרֶט הַכֶּרֶם, (ויקרא י״ט:י׳) וּפְאַת שָׂדְךָ, דְּעָלַיְיהוּ אִתְּמַר, שִׁיְּרֵי מִצְוָה מְעַכְּבִין אֶת הַפּוּרְעָנוּת. לֶעָנִי וְלַגֵּר תַּעֲזוֹב אוֹתָם, דְעַמּוּדָא דְּאֶמְצָעִיתָא בַּר מֵאַתְרֵיהּ, גֵּר אִתְקְרֵי. וּבְגִין דָּא, אֲנָא דְּדַרְגָּא דִּילִי עַמּוּדָא דְּאֶמְצָעִיתָא, קָרֵינָא גַּרְמָאי גֵּר בְּגָלוּתָא קַדְמָאֵי. הֲדָא הוּא דִכְתִיב, (שמות ב׳:כ״ב) גֵּר הָיִיתִי בְּאָרֶץ נָכְרִיָּה, דְּאִיהוּ בְּגָלוּתָא רְבִיעָא בְּגִינַיְיהוּ.</p>\n<p>שָׁאִילוּ לֵיהּ מָארֵי מַתְנִיתִין, רַעְיָא מְהֵימָנָא, הָא פִּקּוּדָא דָּא הֲווֹ מְקַיְּימִין יִשְׂרָאֵל בְּאַרְעָא דְּיִשְׂרָאֵל (או לא). אָמַר לוֹן, בְּגִין לְאִתְעָרָא רַחֲמֵי, עַל אִלֵּין דְּמִתַרְכֵי מֵאַתְרַיְיהוּ. דְּבַר נָשׁ כַּד אִיהוּ לְבַר מֵאַתְרֵיהּ, גִּיּוֹרָא אִתְקְרֵי, כָּל שֶׁכֵּן עַל נִשְׁמָתִין דְּאַזְלִין עַרְטִילָאִין מֵהַהוּא עָלְמָא, וְאַתְיָין לְעָלְמָא דֵּין. בְּגִינַיְיהוּ, הַאי אִיהוּ דְּאָמַר קְרָא, (משלי כ״ז:ח׳) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ, דָּא נִשְׁמְתָא, דִּשְׁכִינְתָא לָא זָזָה מִנָהּ. כֵּן אִישׁ, דְּאִתְּמַר בֵּיהּ (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, נוֹדֵד מִמְּקוֹמוֹ, דְּאִיהוּ נָע וָנָד מֵאַתְרֵיהּ, דְּאִיהוּ עָלְמָא דְּאָתֵי, בִּינָה. וָנָד אֲבַּתְרָהּ בְּעָלְמָא דֵּין, עַד דְּתַשְׁלִים יוֹמִין דְּאִתְחַיְּיבַת לְמֵיזַל לְבַר מֵאַתְרָהָא. וְאִיהוּ נָטִיר לָהּ, עַד דְּיַחֲזִיר לָהּ לְאַתְרָהָא. וְאוֹמֵי דְּלָא יַחֲזוֹר אִיהוּ לְאַתְרֵיהּ, עַד דְּיַחֲזִיר לָהּ לְאַתְרָהָא. וּמַאן דְּחָזַר בְּתִיּוּבְתָא, כְּמַאן דְּאַחְזָר לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא לְאַתְרָהָא. וְדָא רָזָא דְּפוּרְקָנָא, דְּאָמַר (תהילים צ״ה:ז׳) הַיּוֹם אִם בְּקוֹלוֹ תִשְׁמָעוּ.</p>\n<p>אָמְרוּ מָארֵי מַתְנִיתִין דִּמְתִיבְתָא עִלָּאָה וְתַתָּאָה, רַעְיָא מְהֵימָנָא, אֲנָן שְׁלִיחָן דְּמָארֵי עָלְמָא לְגַבָּךְ, זַכָּאָה חוּלָקָךְ, דְּאַנְתְּ בַּעַל תְּשׁוּבָה, שָׁקוּל לְשִׁתִּין רִבְוָון דְּיִשְׂרָאֵל, וְאַנְתְּ הַדְרַת לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ לְאַתְרֵיהּ, עֵילָּא וְתַתָּא. וּבְגִינָךְ יִתְפָּרְקוּן יִשְׂרָאֵל וְיַחְזְרוּן לְאַתְרַיְיהוּ. וְלֵית חֵילָא לַמְּשִׁיחִין. לְמִפְרַק לְיִשְׂרָאֵל, בַּר מִינָּךְ. וּבְגִינָךְ אִינּוּן מִתְעַכְּבִין. אַשְׁלִים מִלִּין יְקָרִין אִלֵּין, דְּעָלַיְיהוּ אִתְּמַר, (תהילים י״ט:י״א) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים מִדְּבַשׁ וְנוֹפֶת צוּפִים.</p>\n<p>אָמַר לוֹן, מָארֵי מְתִיבְתָאן, בְּגִין הַאי שָׂכִיר, דְּאִיהוּ עֶבֶד, דְּאָתֵי לְקַבְּלָא תְּלַת צְלוֹתִין, תַּקִּינוּ מָארֵי מַתְנִיתִין דִּלְכוֹן, לְמֶהֱוֵי בַּר נָשׁ, בִּתְלַת בִּרְכָאן קַדְמָאִין, כְּעֶבֶד דִּמְסַדֵּר שְׁבָחִין קַמֵּי מָארֵיהּ. וּבְאֶמְצָעִיּוֹת, כְּעֶבֶד דִּמְקַבֵּל פְּרָס מִמָּארֵיהּ. וּבְבַתְרָאֵי, כְּעֶבֶד דְּנָטַל פְּרָס מִמָּארֵיהּ, וְאָזִיל לֵיהּ.</p>\n<p>וּבְגִין דָּא, עֶבֶד אַבְרָהָם, וְרִבְקָה, אִיהוּ אַמְתַּלָּא לְהַאי, כַּד קוּדְשָׁא בְּרִיךְ הוּא, יִשְׁלַח לִמְטַטְרוֹן דְּאִיהוּ עַבְדָּא דִּילֵיהּ, בְּגִין צְלוֹתָא אִיהוּ יֵימַר לְגַבֵּיהּ, (בראשית כ״ד:ה׳) אוּלַי לֹא תֹאבֶה הָאִשָּׁה לָלֶכֶת אַחֲרַי. כְּלוֹמַר, אוּלַי צְלוֹתָא לָא בָּעֵי לְמֵיזָל אֲבַתְרָאי. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְנִקִּיתָ מִשְּׁבוּעָתִי זֹאת. דְּחָכְמָה אִיהוּ אַבָּא, דְּנָחִית בְּצַדִיק, לְנַטְרָא שְׁכִינְתָּא בְּגָלוּתָא, וּמִתַּמָּן שָׁלַח בְּגִינָהּ.</p>\n<p>אָמַר לֵיהּ הַהוּא שָׁלִיחַ, הַב לִי סִימָנִין, לְאִשְׁתְּמוֹדְעָא בִּצְלוֹתָא, דְּתַּמָּן בְּרַתָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וְהָיָה הַנַּעֲרָה אֲשֶׁר אוֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה וְאָמְרָה שְׁתֵה. <Nonei></i> וְאִם לָאו, אֶלָּא דְּאַשְׁכַּח כָּל אֵבָרִין דְּגוּפָא מַלְיָין חוֹבִין, וְלָא אַשְׁכָּחַת בֵּיהּ אֵבֶר (נ\"א באפי אברהם) לְשַׁרְיָיא בֵּיהּ תּוֹרָה, דְּאִיהוּ בְּדִיּוּקְנָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְלָא מִצְוָה, דְּאִיהוּ דִּיּוּקְנָא דְּרִבְקָה, דְּהֲוָה (שיר השירים ב) שׁוֹשַׁנָּה בֵּין הַחוֹחִים, דְּאִינּוּן רְשָׁעִים גְּמוּרִים. מָנֵּי לְעַבְדֵיהּ מְטַטְרוֹן, (בראשית כ״ד:ו׳) הִשָּׁמֶר לְךָ פֶּן תָּשִׁיב אֶת בְּנִי שָׁמָּה, דְּאִיהוּ רוּחָא דְּקוּדְשָׁא, דְּהָא מִצְוָה אִיהוּ נַפְשָׁא, רוּחָא אִיהוּ תּוֹרָה.</p>"],[9520012689,"<p>וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, לֹא הַמִּדְרָשׁ הוּא הָעִיקָר אֶלָּא הַמַּעֲשֶׂה. וּבַאֲתָר אַחֲרָא אָמְרוּ, כָּל שֶׁיִרְאַת חֶטְאוֹ קוֹדֶמֶת לְחָכְמָתוֹ, חָכְמָתוֹ מִתְקַיֶּימֶת וְכוּ'. יִרְאַת חֶטְאוֹ, אִימָּא עִלָּאָה, תְּשׁוּבָה. חָכְמָה, אַבָּא עִלָּאָה. כַּד אַקְדִּים ה' זְעֵירָא, דְּאִיהִי מִצְוָה, שַׁרְיָא עָלֵיהּ תּוֹרָה, דְּאִיהוּ ו'. וְכַד אַקְדִּים יִרְאָה לַחָכְמָה, דְּאִיהִי ה' עִלָּאָה, שַׁרְיָיא עָלֵיהּ חָכְמָה, דְּאִיהִי י'. וְאִקְרֵי בֵּן. וּמִכָּאן, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם.</p>\n<p>וְהַאי אִיהוּ (שמות ג׳:ט״ו) זֶה שְׁמִי י\"ה לְעוֹלָם, וְזֶה זִכְרִי ו\"ה. שְׁמִי עִם י\"ה, שס\"ה. זִכְרִי עִם ו\"ה, רמ\"ח. וְכֻלְּהוּ תרי\"ג. דְּהַיְינוּ תרי\"ג פִּקּוּדִין, דְּאִתְיְיהִיבוּ לִבְנִין קַדִישִׁין, לְמֶהֱוֵי לוֹן חוּלָקָא בִּשְׁמֵיהּ, הֲדָא הוּא דִכְתִיב, (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ.</p>\n<p>וְכַד אַקְדִּים תּוֹרָה לְמִצְוָה, אוֹ חָכְמָה לְיִרְאָה. אִתְהַפָּךְ שְׁמֵיהּ עָלֵיהּ לְנוּקְבָּא, מִדַּת הַדִין, כְּגַוְונָא דָּא הוה\"י. דְּאִתְהַפָּךְ לֵיהּ כֹּלָּא לְדִינָא, וְקָשִׁין מְזוֹנוֹתָיו בְּאוֹרַיְיתָא, כִּקְרִיעַת יַם סוּף. וּכְגַוְונָא דָּא פּוּרְקָנָא, אִם זָכוּ יִפְקוּן בְּרַחֲמֵי, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:ז׳) בְּטֶרֶם יָבֹא חֵבֶל לָהּ וְהִמְלִיטָה זָכָר, וְיִפְקוּן בְּרַחֲמֵי. וְאִי לָאו אַקְדִּים רַחֲמֵי, וְיִפְקוּן בְּצַעֲרָא. וְשַׁפִּיר דְּאַקְדִּים צַעֲרָא וְדִינָא לְרַחֲמֵי. וּבְגִין דָּא אוֹקְמוּהָ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, מָארֵי מַתְנִיתִין לְפוּם צַעֲרָא אַגְרָא.</p>\n<p>וּמַפְּקָנוּ דְּנַפְשָׁא, מִקּוֹדֶם דְּנַפְקָת אִית לָהּ צַעֲרָא, לְבָתַר דִּנְפִיקַת בְּרַחֲמֵי. וְרָזָא דְּמִלָּה (ירמיהו ל״א:ט׳) בִּבְכִי יָבֹאוּ, לְבָתַר וּבְתַחֲנוּנִים אוֹבִילֵם, וּבְגִין דָּא, (ירמיהו ל׳:ז׳) וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּה יִוָּשֵׁעַ, וְיִפְּקוּן בְּרַחֲמֵי. וּכְגַוְונָא דְּשָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לְיּוֹנָה, וְלָא אַשְׁכַּח אֲתָר לְשַׁרְיָא. הָכִי שָׁלַח לָךְ רַעְיָא מְהֵימָנָא בְּקַדְמִיתָא.</p>\n<p>וּמַה כְּתִיב בְּהוֹן. (שמות ב׳:י״ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ. דְּכֻלְּהוֹן חַיָּיבִין, וְלָא אַשְׁכָּחַת בְּהוֹן אִישׁ זוֹכֶה לְאַפָּקָא מִן גָּלוּתָא. וּבְגִין דָּא סַרְבַת לְמֵיזָל תַּמָּן, וְאַמְרַת, (שמות ד׳:י״ג) שְׁלַח נָא בְּיַד תִּשְׁלָח. וְהָא אַנְתְּ כְּגוֹן בְּהַהוּא זִמְנָא, בָּךְ יִתְקַיֵּים עִם יִשְׂרָאֵל, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. וּבְגָלוּתָא בַּתְרָאָה, תְּרֵין מְשִׁיחִין יִשְׁלַּח עִמָּךְ, לָקֳבֵל תְּרֵין גַּדְפִּין דְּיוֹנָה. דְּאַנְתְּ כְּגוּפָא בְּגָלוּתָא רְבִיעָאָה, לֵית לָךְ גַּדְפִּין. וְלֹא עוֹד, אֶלָּא בְּקַדְמִיתָא הֲווֹ יִשְׂרָאֵל כְּגוּפָא, וְאַנְתְּ וְאַהֲרֹן, כִּתְרִין גַּדְפִּין דְּיוֹנָה, וּבְהוֹן פַּרְחוּ יִשְׂרָאֵל.</p>"],[9520012690,"<p>לֵית פִּקּוּדָא, דְּלָא אִתְכְּלִילוּ תַּמָּן עֶשֶׂר סְפִירוֹת. בַּתֵּיבָה תַּחְתִּיִּים שְׁנִיִּים וּשְׁלִישִׁים תַּעֲשֶׂיהָ. לְאַכְלְלָא בָּהּ, כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים. תֵּיבָה שְׁכִינָה עִמְּהוֹן, תּוֹרַת יְיָ', אִיהִי רְבִיעִית הַהִין, ה' רְבִיעָאָה. וּמְשׁוּלֶּשֶׁת בְּיה\"ו, לְאַשְׁלְמָא בֵּיהּ ידוד. וְעַשְׂרָה דַּרְגִּין דְּאִתְכְּלִילוּ בֵּיהּ, דְּאִינּוּן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. לְאִתְקַיְּימָא בְּהוּ בְּיִשְׂרָאֵל, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם וְגוֹ', (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם. הַאי שְׁמָא שֻׁלְטָנוּתֵיהּ בְּצוּלְמָא דְּבַר נָשׁ, וְעַל כָּל אֵבֶר וְאֵבֶר דִּילֵיהּ.</p>"],[9520012691,"<p>פִּקּוּדָא בָּתַר דָּא, לָדוּן בְּדִינֵי חֲגָבִים, דְּאִתְּמַר דָּגִים וַחֲגָבִים אֵינָן טְעוּנִין שְׁחִיטָה, אֶלָּא אֲסִיפָתָם הִיא הַמַתֶּרֶת אוֹתָם. הָכִי מָארֵי מַתְנִיתִין, אֵינָן צְרִיכִין שְׁחִיטָה, אֶלָּא דְּאִתְּמַר בְּהוֹן וַיִּגְוַע וַיֵּאָסֶף עַל עַמָּיו. מַה נוּנֵי יַמָּא, חִיוּתָן בְּיַמָּא, אוּף תַּלְמִידֵי חֲכָמִים, מָארֵי מַתְנִיתִין, חִיּוּתַיְיהוּ בְּאוֹרַיְיתָא, וְאִי אִתְפָּרְשָׁן מִנָהּ מִיָּד מֵתִים. תַּנִּינָא (נ\"א תנאין) דְּמַתְנִיתִין, דְּבָהּ אִתְרָבּוּ תַנִינֵי יַמָּא. וְאִי אִינּוּן דִּבְיַבֶּשְׁתָּא יַעֲלוּן (נ\"א יפלון) לְמַיָּא, וְלָא יַדְעִין לְשַׁטְטָא, אִינּוּן מַיְיתִין. אֲבָל אָדָם דְּאִינּוּן מָארֵי קַבָּלָה, אִינּוּן לְעֵילָּא מִכֻּלְּהוּ, בְּהוּ אִתְּמַר (בראשית א׳:כ״ו) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם, דְּאִינּוּן מָארֵי מַתְנִיתִין, תַּנִּינָיָּא. הַתַּנִּין הַגָּדוֹל, (ישעיהו כ״ז:א׳) נָחָשׁ בָּרִיחַ, לָקֳבֵל (שמות כ״ו:כ״ח) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים.</p>\n<p>בְּזִמְנָא דְּתַנִּינָן (דתנינין) מָארֵי מִשְׁנָה, אִית בְּהוֹן מַחֲלוֹקֶת, וּמַקְשִׁין דָּא לְדָא, בָּלַע לְחַבְרֵיהּ. וְהַאי אִיהוּ תַּלְמִיד זְעֵיר, שֶׁלֹּא הִגִיעַ לְהוֹרָאָה, וּמוֹרֶה, חַיָּיב מִיתָה. וְאִי אִינּוּן שָׁוִין דָּא לְדָא, וְאִית בְּהוֹן מַחֲלוֹקֶת וְקוּשְׁיָא, אִתְּמַר בְּהוֹן לְסוֹף, (במדבר כ״א:י״ד) וְאֶת וָהֵב בְּסוּפָה, וְאוֹקְמוּהָ אַהֲבָה בְּסוֹפָהּ.</p>"],[9520012692,"<p>אַדְּהָכִי, הָא נוּנָא רַבָּא אִזְדְּמַן לְגַבֵּיהּ, וְאָמַר רַעְיָא מְהֵימָנָא, (במדבר כ״ד:כ״א) אֵיתָן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּךָ. תַּנְיָא דִּמְסַיֵּיעַ לָךְ. דְּהָא נוּנִין בַּסֶּלַע קִנָּא דִּלְהוֹן, אֵיתָן בְּהִפּוּכָא, תַּנְיָא. אֵיתָנִים בְּהִפּוּךְ אַתְוָון, תַּנָּאִים. אִסְתְּמַּר מִנַּיְיהוּ, דְּהָא אַנְתְּ כְּבַד פֶּה וּכְבַד לָשׁוֹן, וּמַאן דְּבָעֵי לְאַתְקְפָא בַּסֶּלַע דְּנוּנֵי יַמָּא, דְּמָארֵי מַתְנִיתִין, דְּאִינּוּן תַּנָּאִים, בָּעֵי לְמֶהֱוֵי תַּקִּיף, לִישָׁנָא חֲדִידָא חֲרִיפָא, (דלינקוב) לִינְקוּב עַד דְּמָטֵי לִתְהוֹמָא רַבָּא דְּתַמָּן.</p>\n<p>(חבקוק ב׳:ג׳) כִּי עוֹד <Nonei></i> חָזוֹן לַמּוֹעֵד וְיָּפֵחַ לַקֵּץ וְלֹא יְכַזֵּב, וְאוֹקְמוּהָ דְּהַאי קְרָא נוֹקֵב וְיּוֹרֵד, עַד תְּהוֹמָא רַבָּא. מַאן הוּא דְּנָחִית לִתְהוֹם רַבָּא, לְאַשְׁכְּחָא זִמְנָא דָּא, אֶלָּא אַנְתְּ, דְּאִתְּמַר בָּךְ (תהילים ל״ו:ז׳) צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה. כַּמָה מָארֵי מַתְנִיתִין, דְּבָעוּ לְנַחְתָּא לְעוּמְקָא דַּהֲלָכָה, לְאַשְׁכְּחָא תַּמָּן קֵץ דְּפֻרְקָנָא, וְנַחְתּוּ תַּמָּן, וְלָא סְלִיקוּ. וְאַף עַל גַּב דְּלִישָׁנְהוֹן הֲוַת כְּפַטִּישׁ יְפוֹצֵץ סֶלַע, חֲלִישׁ פַּטִּישׁ דִּלְהוֹן, לְנַקְבָא בְּהַהוּא סֶלַע. וּמַאן דִּנְקִיבוּ דִּילֵיהּ בְּהַהוּא סֶלַע בְּלָא רְשׁוּ, אָתָא חִוְיָא לְנַשְּׁכָא לֵיהּ. וְאִית אַחֲרָנִין דִּנְקִיבוּ לָהּ, עַד דְּמָטוּ לִתְהוֹמָא רַבָּא, וְלָא סְלִיקוּ מִתַּמָּן.</p>"],[9520012693,"<p>וּבְזִמְנָא דְּנוּקְבָּא פְּתִיחָא, כָּל מַאן דְּהֲוָה נָפִיל תַּמָּן, לָא הֲוָה סְלִיק. וּמָשִׁיחַ בֶּן דָּוִד נָפַל תַּמָּן עִם מָשִׁיחַ בֶּן יוֹסֵף. דְּחָד אִיהוּ (זכריה ט׳:ט׳) עָנִי וְרוֹכֵב עַל חֲמוֹר. וְחַד אִיהוּ, (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ, דָּא מָשִׁיחַ בֶּן יוֹסֵף. וְהַאי אִיהוּ (שמות כ״א:ל״ג) כִּי יִכְרֶה אִישׁ בּוֹר וְלֹא יְכַסֶּנּוּ וְנָפַל שָׁמָּה שׁוֹר אוֹ חֲמוֹר. וּבְגִין דָּא אִקְרֵי מָשִׁיחַ, בַּר נַפְלֵי. וְאִיהִי נַפְלַת בַּתְרַיְיהוּ, וְאִתְּמַר עָלָהּ, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. וְאַנְתְּ הוּא (שמות כ״א:ל״ד) בַּעַל הַבּוֹר יְשַׁלֵּם כֶּסֶף יָשִׁיב לִבְעָלָיו. וְהַמֵּת יִהְיֶה לּוֹ, דָּא מָשִׁיחַ בֶּן יוֹסֵף, דְּעָתִיד לְאִתְקָטְלָא. (מצאתי כאן חלק כמו ד' שורות ונראה שחסר)</p>\n<p>נָחַת בְּגִינֵיהּ. דְּוַדַּאי אַרְבַּע גָּלִיוֹת הֲווֹ, תְּלַת, לָקֳבֵל תְּלַת קְלִיפִּין דֶּאֱגוֹזָא, דְּאִינּוּן תֹּהוּ, קַו יָרוֹק, קְלִיפָּה יְרוֹקָא דֶּאֱגוֹזָא. תִּנְיָינָא בֹּהוּ, אֲבָנִין מְפוּלָּמִין, דְּאִינּוּן סְלָעִים תַּקִּיפִין, דְּמִכָּל מָקוֹם פַּסְקוּ מִינַּיְיהוּ כַּמָה פְּסָקוֹת, וְנָקִיט לוֹן, לְאַפָּקָא מַיָּא דְּאוֹרַיְיתָא. וּבְגִין דָּא אִתְקְרִיאוּ אֲבָנִים מְפוּלָּמוֹת, דְּמִנַּיְיהוּ מַיִין נָפְקִין. קְלִיפָּה תְּלִיתָאָה, דְּקִיקָא, גָּלוּתָא תְּלִיתָאָה, דְּהֲוָה זְעֵיר, וְהַאי אִיהוּ וְחֹשֶׁךְ. גָּלוּתָא רְבִיעָאָה, תְּהוֹם רַבָּה, חָלָל דֶּאֱגוֹזָא. וְהַאי אִיהוּ, (בראשית א׳:ב׳) וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם.</p>\n<p>וְאִתְקְרֵי בּוֹר, דְּנָפַל שָׁמָּה שׁוֹר, דָּא דִּכְתִיב בְּיוֹסֵף, (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. דְּאִתְּמַר בֵּיהּ, (בראשית ל״ז:כ״ד) וַיַּשְׁלִיכוּ אוֹתוֹ הַבּוֹרָה. נוּקְבָּא בִּישָׁא. וְהַבּוֹר רֵק, דְּכוּרָא (נ\"א דבורא), רֵק בְּלָא תּוֹרָה, אֲבָל נְחָשִׁים וְעַקְרַבִּים יֵשׁ בּוֹ. וְדָא גָּלוּתָא רְבִיעָאָה, דּוֹר דִּרְשָׁעִים מָלֵא נְחָשִׁים וְעַקְרַבִּים, רַמָּאִים כִּנְחָשִׁים וְעַקְרַבִּים, דְּעַקְרִין מִלֵּי דְּרַבָּנָן, וְדַיְינִין לְשַׁקְרָא, עָלַיְיהוּ אִתְּמַר, (איכה א׳:ה׳) הָיוּ צָרֶיהָ לְרֹאשׁ.</p>\n<p>(שמות ב׳:י״ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ דְּיִשְׂרָאֵל, בְּאִלֵּין רַשִׁיעַיָּא עֵרֶב רַב, וְדָא בְּסוֹף גָּלוּתָא. וּבְגִין דָּא קֵץ דְּפוּרְקָנָא נוֹקֵב עַד הַתְּהוֹם רַבָּה. וְרַעְיָא מְהֵימָנָא, תְּהוֹם הוּא הַמָּוֶת בְּהִיפוּךְ אַתְוָון, וְלֵית מָוֶת אֶלָּא עֲנִיּוּתָא, אַנְתְּ נְחִיתַת תַּמָּן. וְהָא קָא אִתְבְּרִיר לְעֵילָּא, קַמֵּי תַּנָּאִים וַאֲמוֹרָאִים, וְכֻלְּהוּ נַחְתִין בְּגִינָךְ בִּתְהוֹמָא לְסַיְּיעָא לָךְ.</p>"],[9520012694,"<p>וְאַנְתְּ תַּנְיָא דִּמְסַיֵּיעַ לָךְ יַתִּיר מִכֻּלְּהוּ, בְּגִין דְּאַנְתְּ לִוְיָתָן (נחש בריח) דְּיַמָּא דְּאוֹרַיְיתָא, מָארֵיהּ דְּכָל נוּנִין לִוְיָתָן אִתְקְרֵי, עַל שֵׁם אוֹרַיְיתָא, דְּאִתְּמַר בֵּיהּ (משלי א׳:ט׳) כִּי לִוְיַת חֵן הֵם לְרֹאשֶׁךָ. וּבָךְ (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. אָדָם דְּאִתְּמַר בֵּיהּ (במדבר י״ט:י״ד) אָדָם כִּי יָמוּת בְּאֹהֶל, וְאוֹקְמוּהָ מָארֵי מַתְנִיתִין, אֵין הַתּוֹרָה מִתְקַיֶּימֶת אֶלָּא בְּמִי שְׁמֵמִית עַצְמוֹ עָלֵיהָ, וְלֵית מִיתָה אֶלָּא עֲנִיּוּתָא. וּבְהֵמָה, אִלֵּין עַמֵּי הָאָרֶץ, דְּאִינּוּן מִתְכַּפְיָין כַּסּוּס כַּפֶּרֶד תְּחוֹת מָארֵי מַתְנִיתִין.</p>\n<p>אַדְּהָכִי הָא בּוּצִינָא קַדִישָׁא אָתָא, פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, מָארֵי מַתְנִיתִין מַאן אִיהוּ לִוְיָתָן. אָמַר לֵיהּ בּוּצִינָא קַדִישָׁא, הַאי אִיהוּ דְּדַרְגֵּיהּ עַמּוּדָא דְּאֶמְצָעִיתָא, וְצַדִּיק, דְּאִתְּמַר בֵּיהּ, גּוּף וּבְרִית חַשְׁבֵינָן חַד. וְאִתְרַבֵּי בְּיַמָּא דָּא, דְּאִיהִי אִימָּא עִלָּאָה, יָם, דְּבָהּ מְיַיחֲדִין לְקוּדְשָׁא בְּרִיךְ הוּא כ\"ה כ\"ה אַתְוָון, דְּאִינּוּן יָם בְּחוּשְׁבָּן, וְאִיהוּ בָּהּ. אָמַר רַעְיָא מְהֵימְנָא, וַדָאי לִוְיָתָן דְּקָאִים עַל שְׂפַת הַיָּם, וְעָלְמָא קָאֵי עַל סְנַפִּירוֹי, דָּא (משלי י׳:כ״ה) צַדִּיק יְסוֹד עוֹלָם, דְּכָל עָלְמָא קָאִים עֲלוֹי. אָמַר בּוּצִינָא קַדִישָׁא, זַכָּאָה חוּלָקָךְ רַעְיָא מְהֵימְנָא. (כאן חסר)</p>"],[9520012695,"<p>בַּת קוֹל בְּגָלוּתָא, עַד דְּתֵיתֵי אַנְתְּ לְגַבָּהּ, דְּאַנְתְּ קוֹל דִּילָהּ, דְּכָל אִשָׁה בַּת בַּעְלָהּ, כְּמָה דְּאַתְּ אָמֵר וַתְּהִי לוֹ לְבַת. מְאוֹרָשָׂה אִיהִי לָךְ, עֲדַיִין לָא עַבְדַת (ד\"א עאלת עמיה) עִמָּהּ לַחוּפָּה.</p>\n<p>אִתְּמַר, צָעֲקָה הַנַּעֲרָה הַמְאוֹרָשָׂה וְאֵין מוֹשִׁיעַ לָהּ. הָכִי שְׁכִינְתָּא, אִימָּא דִּילָהּ (נ\"א עלאה), צוֹעֶקֶת עַל בְּנָה, וְאֵין מוֹשִׁיעַ לָהּ, עַד דְּיֵיתֵי עַמּוּדָא דְּאֶמְצָעִיתָא בְּגִינָהּ, דְּאִיהוּ מוֹשִׁיעַ. דִּבְגִינָהּ אִתְּמַר, (זכריה ט׳:ט׳) הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּיק וְנוֹשָׁע. הוּא מוֹשִׁיעַ לְעֵילָּא, וְאַנְתְּ לְתַתָּא. וּבְגִין דְּאַנְתְּ בְּדִיּוּקְנֵיהּ, אִתְּמַר בָּךְ, (דברים ה׳:כ״ח) וְאַתָּה פֹּה עֲמוֹד עִמָּדִי. דְּכֻלְּהוּ יִשְׂרָאֵל אָהַדְרוּ לְאָהֳלֵיהוֹן, וְאַנְתְּ לָאו, עַד פּוּרְקָנָא בַּתְרַיְיתָא. וּמַאן גָּרַם דָּא, עֵרֶב רַב. דִּבְגִּינַיְיהוּ, (שמות ל״ב:י״ט) וַיַּשְׁלֵךְ מִיָּדָו אֶת הַלּוּחוֹת. וּמֵהַהִיא שַׁעֲתָא נָפְלָה, וְלָא אִתְפָּרְקַת מֵעֵרֶב רַב, דְּאִתְּמַר בְּהוֹן (שמות י״ב:ל״ח) וְגַם עֵרֶב רַב עָלָה אִתָּם. בְּכָל דָּא לָא אִתְפָּרְשָׁן מִיִּשְׂרָאֵל. וְשִׁפְחָה מִגְּבִרְתָּהּ, עַד פּוּרְקָנָא בַּתְרַיְיתָא.</p>\n<p>אַנְתְּ בְּרָא דְּמַלְכָּא, כְּגַוְונָא דִּילָךְ אִתְּמַר בְּעַמּוּדָא דְּאֶמְצָעִיתָא <Nonei></i> בְּכֹלָּא, חֶדְוָה דִּילָךְ, כְּחֶדְוָה דִּילֵיהּ יְהֵא, כַּד יֵיתֵי לְמִפְרַק לְכַלָּתֵיהּ, (תהילים י״ט:ו׳) וְהוּא כֶּחָתָן יוֹצֵא מֵחוּפָּתוֹ וְגוֹ'. דְּהָא לְבוּשִׁין דִּילָהּ בְּגָלוּתָא חֲשׁוֹכִין, וּבְזִמְנָא דְּאִיהִי מִתְלַבְּשַׁת בְּהוֹן, אִיהִי אָמְרָה (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. וְאִלֵּין קְלִיפִּין אִינּוּן, מַשְׁחִית אַף וְחֵמָה, נוּקְבָּא בִּישָׁא, שִׁפְחָה בִּישָׁא, שַׁבְתַּאי, (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, דְּאִיהִי שַׁבָּת מַלְכְּתָא. מַשְׁחִית אַף וְחֵמָּה, סָחֲרִין לִתְלָתָא אֲבָהָן.</p>"],[9520012696,"<p>וְלֹא עוֹד, אֶלָּא מַה דַּהֲוַת בְּרַתָּא דְּמַלְכָּא, י' עַל הו\"ה, דִּכְלִילָן בַּאֲבָהָן, ה' קַדְמָאָה בְּאַבְרָהָם. ה' תִּנְיָינָא בְּיִצְחָק. ו' בְּיַעֲקֹב. וַהֲוַת י' רֵישָׁא עָלַיְיהוּ. אִתְּמַר, (איכה ה׳:ט״ז) נָפְלָה עֲטֶרֶת רֹאשֵׁנוּ. וְאַמְתִּילוּ רַבָּנָן מְתָלָא, לְמַלְכָּא דְּהֲוָה לֵיהּ עֲטָרָה עַל רֵישֵׁיהּ, וְאִילָן יָאֶה קֳדָמֵיהּ, אַתְיָא לֵיהּ שְׁמוּעָה בִּישָׁא, אַרְמֵי עֲטָרָה מֵעַל רֵישֵׁיהּ. וּמַה דַּהֲוַת י' עַל הו\"ה. י' לְעֵילָּא, אִתְהַדָּר הוה\"י, י' לְתַתָּא. וּבְגִין דָּא אָמַר דָּוִד, (תהילים קי״ח:כ״ב-כ״ג) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה מֵאֵת יְיָ' הָיְתָה זֹּאת.</p>"],[9520012697,"<p>קוּם רַעְיָא מְהֵימְנָא, טוֹל אַבְנָא דָּא בִּידָךְ, דְּאִתְּמַר בָּהּ, (זכריה ג׳:ט׳) עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. לְתַבְרָא קְלִיפִּין דֶּאֱגוֹזָא, דְּהָא כַּמָה רוֹעִים פַּרְנָסֵי דָּרָא, אִתְכְּנָשׁוּ עַל הַאי אַבְנָא, דְּאִיהִי סֶלַע דִּילָךְ, לְאַפָּקָא מַיָּא מִתַּמָּן, דְּכַלָּה דִּילָךְ מַעְיַן הַחָכְמָה. בְּהַאי סֶלַע, דִּנְבִיעָא דִּילָהּ בְּאוֹרַיְיתָא, בְּרָזִין סְתִימִין לֵית סוֹף. וְעָלָה אִתְּמַר, (איוב כ״ח:י״ב) וְהַחָכְמָה מֵאַיִן תִּמָּצֵא.</p>\n<p>וְכָל תּוּקְפָּא דִּלְהוֹן לְאַעְבְּרָא קְלִיפָה דִּלְעֵילָּא, וְכַד מָטָן לַקְּלִיפָה תִּנְיָינָא, דְּאִיהִי תַּקִּיפָא, אִיהִי קַשְׁיָא לוֹן, וּמָחָאן בָּהּ כָּל יוֹמֵיהוֹן כֻּלְּהוּ, בְּלִישָׁנֵהוֹן דְּאִינּוּן תַּקִּיפִין כְּפַטִּישִׁין, וְלֵית לוֹן רְשׁוּ לְאַפָּקָא מִינָהּ מַיָּא. אֶלָּא אִלֵּין טִפִּין דְּנָפְקִין עַל יְדָךְ, בְּזִמְנָא דְּאִתְּמַר בָּהּ, (במדבר כ׳:י״א) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. וּבִמְחָאָה תִּנְיָינָא נַפְקֵי אִלֵּין טִפִּין. וְאִלֵּין אִינּוּן רְמִיזִין דְּחָכְמָה, רְמִיזִין דְּקַבָּלָה, דְּאִינּוּן בַּחֲגִיגָה, וּשְׁאַר מַתְנִיתִין. וְהַאי אֶבֶן לֵית מַאן דְּאַפִּיק מִינָהּ חָכְמָה, דְּאִיהִי מִלְּגָאו, דְּלֵית לָהּ סוֹף, (דאיהו מוחא מלגאו) בַּר אַנְתְּ, דְּאִתְּמַר בָּךְ הֲלָכָה לְמֹשֶׁה מִסִּינַי.</p>\n<p>פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר, סָבָא סָבָא, אִית סֶלַע, וְאִית סֶלַע, אִית אֶבֶן, וְאִית אֶבֶן. אִית אֶבֶן דִּשְׁמָא דִּיְהוָֹ\"ה, עָלָהּ אִתְּמַר (דניאל יב) וְאַבְנָא דִּי מְחָת לְצַלְמָא הֲוַת לְטוּר רַב. וְאִית אֶבֶן דְּאִיהִי (ויקרא כ״ו:א׳) אֶבֶן מַשְׂכִּית, דְּלֵית תַּמָּן נְבִיעוּ דְּמַיָּא דְּחָכְמְתָא, וְלָא דִּבּוּר.</p>\n<p>אֶלָּא אֶבֶן דְּאִיהִי (חסר) סֶלַע, דְּמֹשֶׁה, עָלָהּ אִתְּמַר (במדבר כ׳:ח׳) וְדִבַּרְתֶּם אֶל הַסֶּלַע לְעֵינֵיהֶם וְנָתַן מֵימָיו. דְּאִיהִי בַּת קוֹל וְלָא תַּלְיָא בָּהּ אֶלָּא דִּבּוּר וּפִיוּסָא. אֲבָל שִׁפְחָה, סֶלַע אַחֲרָא, דְּאִתְקְרִיאַת (קליפה) מִשְׁנָה. נוּקְבָּא דְּעֶבֶד נַעַר. עָלָהּ אִתְּמַר, (משלי כ״ט:י״ט) בִּדְבָרִים לֹא יִוָּסֶר עָבֶד, אֶלָּא דְּמָחָאן וּמְתַבָּרִין מִינָּהּ כַּמָה פְּסָקוֹת, וְלַקְטִין לוֹן, וְאִתְקְרוּן לְקוּטוֹת. וְעַל דִּמְלַקֵּטֵי לוֹן, אִתְקְרִיאוּ לְקוּטוֹת, בְּלָא נְבִיעוּ דְּחָכְמָה וְקַבָּלָה.</p>\n<p>אֲבָל סֶלַע דִּילִי, אִיהִי בְּרַתָּא דְּמַלְכָּא, בְּגִינָהּ אִתְּמַר, וְדִבַּרְתֶּם אֶל הַסֶּלַע לְעֵינֵיהֶם וְנָתַן מֵימָיו, בְּדִבּוּר וּפִיּוּס, כִּבְרָתָא דְּמַלְכָּא. וּבְגִין דְּמָחֵינָא בָּהּ, לָקֵינָא עָלָהּ, וְאִתְגְּזַר עֲלָנָא מוֹתָא. דְּמַאן דִּמְסָרֵב לְמַטְרוֹנִיתָא, חַיָּיב מִיתָה. כָּל שֶׁכֵּן מַאן דְּמָחָא לִבְרָתֵיהּ דְּמַלְכָּא. וּבְגִין דָּא אִתְגְּזַר עָלַי, דְּלָא אִיעוּל לְאַרְעָא דְּיִשְׂרָאֵל, וַאֲנָא קָבוּר בְּאַרְעָא נוּכְרָאָה, וְאִתְעַבְּרַת מִינִי. וְאִתְּמַר, (שמואל ב כ״ג:כ״א) וַיֵּרֶד אֵלָיו בַּשָׁבֶט. וְהַאי שֵׁבֶט, אִיהוּ חַד מִשִׁבְטַיָּא דִּילִי, דַּאֲנָא עָתִיד לְנַחְתָּא תַּמָּן לְמֶהֱוֵי עִם יִשְׂרָאֵל בְּגָלוּתָא. וְכֹלָּא אִתְרְמִיז, וּבַאֲתָר אוֹחֲרָא אוֹקְמוּהָ מָארֵי מַתְנִיתִין. (חסר)</p>"],[9520012698,"<p>דְּבֵי מַקְדְּשָׁא, וּשְׁמָא דְּמָשִׁיחַ, אִתְקְרִיאוּ בְּשֵׁם ידוד. וְדָא אַרְבַּע אַנְפֵּי אָדָם, וְאִינּוּן דְּשִׁבְטָא דְּלֵוִי, אִינּוּן נַפְקָן מֵחֵיוָן דְּאִינּוּן שְׁאַר שְׁבָטִין, וְעָאלוּ בְּחוּלָקָא דְּאָדָם, דְּאִינּוּן אַרְבַּע אַנְפִּין דִּילֵיהּ. וּמֹשֶׁה אִיהוּ אָדָם בְּדִיּוּקְנָא דְּהַהוּא אָדָם קַדְמָאָה דִּלְעֵילָּא. (משלי ל׳:ד׳) מַה שְּׁמוֹ וּמַה שֵּׁם בְּנוֹ. וּבְגִין דָּא, כַּהֲנַיָיא וְלֵיוָאֵי, מְזוֹנֵיהוֹן עַל יְדָא דְּמַלְכָּא אָכִיל בְּפָתוֹרֵיהּ, וּשְׁאַר חַיָּילִין דְּמַלְכָּא, כָּל חַד יָהֲבִין לֵיהּ לְמֵיכַל בְּבֵית מוֹשָׁב דִּילֵיהּ. וְרַעְיָא מְהֵימָנָא אִיהוּ כִּבְרָא דְּמַלְכָּא, קָרִיב לְמַלְכָּא יַתִיר מֵאִלֵּין דְּאַכְלִין לְפָתוֹרֵיהּ, דְּלֵית מַאן דְּקָרִיב לְמַלְכָּא מִכָּל בְּנֵי מַלְכוּתָא, כִּבְרֵיהּ.</p>\n<p>קָם בּוּצִינָא קַדִּישָׁא וְאָמַר, סָבָא סָבָא, בְּמִלִּין דִּילָךְ אִשְׁתְּמוֹדַע מַאן אַנְתְּ. אַנְתְּ הוּא אָדָם קַדְמָאָה. מַה שְׁמוֹ, אִתְּמַר עָלָךְ. מַה שֵּׁם בְּנוֹ, אִתְּמַר עַל רַעְיָא מְהֵימָנָא. וּבְגִין דְּאִיהוּ חִדֵּשׁ כַּמָה חִדּוּשִׁין בְּאוֹרַיְיתָא, חֶדְוָה זְמִינָא לְגַבָּךְ, (משלי י׳:א׳) דְּבֵן חָכָם יְשַׂמַּח אָב. (חסר)</p>\n<p>רַעִִיָא מְהֵימָנָא, בְּפַרְשְׁתָּא דָּא, הֲוָה אַדְכַּר כְּנִישׁוּ דִּילָךְ לְהַהוּא עָלְמָא, דִּכְתִּיב (במדבר כ״ז:י״ב) (עלה) <Nonei></i> אֶל הַר הָעֲבָרִים הַזֶּה הַר נְבוֹ וְגוֹ', וְרָאִיתָ אוֹתָהּ וְנֶאֱסַפְתָּ אֶל עַמֶּךָ וְגוֹ', כַּאֲשֶׁר נֶאֱסַף אַהֲרֹן אָחִיךָ וְגוֹ'. וּבְהַאי פַּרְשְׁתָּא, אִית לָךְ לְאָהַדְרָא לְעָלְמָא וּלְהַחֲיוֹת, וּלְאַעֲלָא לְאַרְעָא דְּיִשְׂרָאֵל, וּלְאִתְחַבְּרָא בְּפַרְשְׁתָּא דָּא בְּכַלָּה דִּילָךְ, דִּכְתִּיב בָּהּ, (במדבר כ״ה:י״ב) הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וּבְגִין דָּא לָא אָמַר לָךְ קוּדְשָׁא בְּרִיךְ הוּא הָכָא רֵד, אֶלָּא עֲלֵה. דְּמִנֵּיהּ, אַנְתְּ תְּהֵא עָאל לְאַרְעָא דְּיִשְׂרָאֵל.</p>\n<p>וּמַה דְּאָמַר בָּךְ, (דברים ל״ד:ו׳) וְלֹא יָדַע אִישׁ אֶת קְבוּרָתוֹ עַד הַיּוֹם הַזֶּה. וַי לְאִינּוּן אֲטִימִין לִבָּא, סְתִימִין עַיְינִין, דְּלָא יַדְעֵי קְבוּרָה דִּילָךְ, דַּהֲוֵית אַנְתְּ בָּעֵי רַחֲמֵי מְקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יֵיעוּל לָךְ בְּהַהוּא קְבוּרָה, דְּבָהּ אַנְתְּ מִתְקְרֵי מֵת. הֲדָא הוּא דִכְתִיב, (יהושע א׳:ב׳) מֹשֶׁה עַבְדִּי מֵת. וְאִינּוּן טִפְּשָׁאֵי אַמְרִין, וְכִי מֹשֶׁה הֲוָה מְפָחֵד מִמִּיתָה, לְנָפְקָא מֵהַאי עָלְמָא, לְעָלְמָא דְּאָתֵי, כִּשְׁאַר בִּרְיָין. וְאִינּוּן לָא יַדְעִין דִּקְבוּרָה דִּילָךְ, וּמוֹתָא דִּילָךְ אֵיךְ הִיא.</p>\n<p>דְּהָכִי אוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּמֵתֵי חוּצָה לָאָרֶץ אֵינָם חַיִּים. לָא אַמְרֵי דְּאֵינָם עֲתִידִים לְהַחֲיוֹת, דְּאִלְמָלֵי כַּךְ הֲווֹ כַּפְרִין בִּתְחִיַּית הַמֵּתִים. אֶלָּא הָכָא רָזָא רַבְרְבָא, קְבוּרָה דִּילֵיהּ בְּצוּלְמָא דְּלָאו הֲגוּנָה לֵיהּ, דְּאִיהִי (תהלים מב) אֶרֶץ צִיָּה וְעָיֵף בְּלִי מָיִם, וְלֵית מַיִם אֶלָּא תּוֹרָה, וּבָהּ (ישעיהו נ״ג:ב׳) לֹא תֹאַר לוֹ וְלֹא הָדָר. וּמַאן דְּחָזִי לֵיהּ בְּהַהוּא צוּלְמָא, וְנִרְאֵהוּ וְלֹא מַרְאֶה וְנֶחְמְדֵהוּ. וּבְגִין דָּא, נְבוּאַת יְשַׁעְיָה (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי, קָא רָמִיז עָלֵיהּ.</p>\n<p>וּבְגִין הַהוּא קְבוּרָה, הֲוָה בָּעֵי רַחֲמֵי דְּלָא יְמוּת תַּמָּן בְּחוּצָה לָאָרֶץ, לְפוּם דְּהֲוָה בְּאָרֶץ צִיָּה רָעֵב וְעָיֵף וְצָמֵא בְּלִי מַיִם, דְּאִיהִי אוֹרַיְיתָא. וּבְגִין דָּא אִתְּמַר עָלֵיהּ, עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה. מִשִּׁפְלּוּתָא דִּילֵיהּ, אַחְזֵי לֵיהּ מַעֲלָתֵיהּ, אַף עַל גַּב דְּאַנְתְּ קָבוּר בַּאֲתָר דְּלָאו הָגוּן לָךְ, עָרוּם בְּלָא לְבוּשִׁין דִּילָךְ, דְּאִינּוּן עוֹר וּבָשָׂר (תלבישני), נָע וָנָד מֵאֲתָר דִּילָךְ, וּמְטַלְטֵל וְגָלֵּי. הָא פִּנְחָס דְּעַבְדַּת טִיבוּ עִמֵּיהּ, דְּאִתְּמַר עָלָךְ, הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, הָא אִיהוּ יַעְבִּיד טִיבוּ עִמָּךְ, וּבֵיהּ תִּסְתְּלַּק בְּפַרְשְׁתָּא דִּילֵיהּ. דְּבָהּ כַּלָּה דִּילָךְ, תַּמָּן תִּתְיַיחֵד עִמָּהּ, כֶּחָתָן עִם כַּלָּתֵיהּ.</p>\n<p>דְּהָא אַנְתְּ (תועלת גדול לישראל בקבורתך), אִי לָא הֲוֵית קָבוּר לְבַר מֵאַרְעָא קַדִּישָׁא, לְבַר מִכַּלָּה דִּילָךְ, לָא הֲווֹ יִשְׂרָאֵל נָפְקִין מִגָּלוּתָא. וּבְגִינָךְ אִתְּמַר, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ. אִתְעָבִידַת חוֹל בְּגִין חוֹבָה וָפֶשַׁע דְּיִשְׂרָאֵל בִּקְבוּרָה דִּילָךְ, דְּאִתְּמַר בָּךְ (דברים ל״ד:ו׳) וַיִקְבּוֹר אוֹתוֹ בַגַּיְא. וּמַה כְּתִיב בִּקְבוּרָה דִּילָךְ. (ישעיהו מ׳:ד׳) כָּל גֶּיא יִנָּשֵׂא, כָּל שָׁפֵל וְנָמוּךְ יִנָּשֵׂא בְּגִינָךְ, דְּאִינּוּן יִשְׂרָאֵל, דְּאִינּוּן שְׁפָלִים מִכָּל אוּמָה וְלִישָׁן. וְכָל הַר וְגִבְעָה יִשְׁפָּלוּ, דְּאִינּוּן רַשִׁיעֲיָיא, וְגַסֵי הָרוּחַ.</p>\n<p>וְהַאי אִיהוּ, (ישעיהו נ״ג:ה׳) וּבַחֲבוּרָתוֹ נִרְפָּא לָנוּ, (בחבורא) בְּחִבּוּרָה דְּאִתְחַבָּר עִמָּנָא בְּגָלוּתָא, נִרְפָּא לָנוּ. דְּאַנְתְּ הוּא כְּשִׁמְשָׁא דְּנָהִיר, דְּאַף עַל גַּב דְּאִתְכְּנַשׁ בְּלֵילְיָא, נָהִיר הוּא בְּסִיהֲרָא, וּבְכָל כֹּכָבַיָא וּמַזָּלֵי. הָכִי אַנְתְּ נָהִיר, בְּכָל מָארֵי הֲלָכוֹת וְקַבָּלוֹת. וְלָךְ אִשְׁתַּקְיָין בִּגְנִיזוּ, כְּמַבּוּעָא דְּאַשְׁקֵי לְאִילָנִין תְּחוֹת שָׁרְשֵׁיהוֹן בִּגְנִיזוּ, עַד דְּאִתְבְּקַע מֵימוֹי בְּאִתְגַּלְיָיא. הֲדָא הוּא דִכְתִיב, (משלי ה׳:ט״ז) יָפוּצוּ מַעְיְנוֹתֶיךָ חוּצָה.</p>\n<p>דְּאַנְתְּ הוּא אוּף הָכִי, כְּשִׁמְשָׁא דְּאָזִיל בִּימֵי הַחוֹרֶף תְּחוֹת מַבּוּעִין, וְכַד מָטֵי פּוּרְקָנָא, תְּהֵא כְּשִׁמְשָׁא דְּאָזִיל בַּקַּיִץ לְעֵילָּא מִמַּבּוּעִין, וְיֵהוֹן צוֹנְנִין בְּרַחֲמֵי. דְּכַד אַנְתְּ תְּחוֹתַיְיהוּ, אִינּוּן חַמִּין בְּדִינָא. אָתָא רַעְיָא מְהֵימָנָא, וּבָרִיךְ לְבוּצִינָא קַדִּישָׁא, וְאָמַר וַדַּאי אַנְתְּ הוּא דְּנָהִיר לִי, בְּזִמְנָא דְּאִתְּמַר עָלַי, (בראשית כח) כִּי בָא הַשֶּׁמֶשׁ, כָּבָה הַשֶּׁמֶשׁ, דְּאַחֲשִׁיךְ נְהוֹרֵיהּ. יְהֵא רַעֲוָא, דידו\"ד יַנְהִיר שְׁמֵיהּ עֲלָךְ.</p>"],[9520012699,"<p>וְעוֹד אָמַר בּוּצִינָא קַדִּישָׁא, וַדַּאי אַנְתְּ הוּא כֹּלָּא, (ס\"א ויאמר וגו') דְּאָמַר, (במדבר י״ב:ו׳) אִם יִהְיֶה נְבִיאֲכֶם וְגוֹ'. וּבְגִין דָּא, כַּד אִתְגַּלְיָיא אִימָּא עִלָּאָה לָךְ, אַמָרְתּ (שמות ג׳:ג׳) אֲסוּרָה נָּא וְאֶרְאֶה אֶת הַמַּרְאֶה הַגָּדוֹל הַזֶּה מַדּוּעַ לֹא יִבְעַר הַסְּנֶה. בְּגִין דְּאִיהִי רַחֲמֵי, אִתְּמַר בָּהּ לֹא יִבְעַר הַסְּנֶה.</p>\n<p>וְחָמֵשׁ נְהוֹרִין אִית לָהּ, דְּאִתְקְרִיאוּ קַרְנֵי הַחַמָּה, עַד הוֹד, וּמִתַּמָּן עַד הוֹד, הֲווֹ נְהִרִין בָּךְ רַעְיָא מְהֵימְנָא, וְהַאי אִיהוּ וְנָתַן הוֹד לְמֹשֶׁה, לְאִשְׁתְּמוֹדְעָא דְּכֻלְּהוּ לָךְ אִתְיְיהִיבוּ, אֲפִילּוּ עַד הוֹד. וּבְגִין דָּא, פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. וְאִלֵּין חֲמֵשׁ, סַלְּקִין לְחַמְשִׁין תַּרְעִין דְּבִינָה.</p>\n<p>וּבְאִלֵּין חָמֵשׁ דְּאִתְּמַר, דְּאִינּוּן חָמֵשׁ אוֹר דְּיוֹמָא קַדְמָאָה, דְּאִינּוּן לָקֳבֵל חָמֵשׁ אֶצְבְּעָן דִּימִינָא אִתְחַזְיָא לָךְ בַּסְּנֶה. בְּגִין דְּעָתִיד אַנְתְּ לְאַפָּקָא זַרְעָא דְּאַבְרָהָם מִן גָּלוּתָא, דְּאִיהוּ דַּרְגָּא (דאברהם) יְמִינָא. וּמִתַּמָּן בִּינָה אִיהוּ רַחֲמִים גְּמוּרִים, יַד הַגְּדוֹלָה. (אבל) מִסִּטְרָא דִּגְבוּרָה, יַד הַחֲזָקָה, חָמֵשׁ רָקִיעַ, בְּיוֹם שֵׁנִי, לָקֳבֵל חֲמֵשׁ אֶצְבְּעָן דִּשְׂמָאלָא. אֲבָל מִסִּטְרָא דְּדַרְגָּא דִּילָךְ, (שמות י״ד:ח׳) וּבְנֵי יִשְׂרָאֵל יוֹצְאִים בְּיָד רָמָה. דְּגוּף וּתְרֵין דְּרוֹעִין וּתְרֵין שׁוֹקִין, לָקֳבֵל חֲמֵשׁ אֶצְבְּעָן, ה' ה' ה'. ה' אֶצְבְּעָן דְּיָד יָמִין, וה' דְּיָד שְׂמֹאל, וּתְרֵין דְּרוֹעִין וּתְרֵין <Nonei></i> שׁוֹקִין וְגוּף, דְּאִינּוּן חָמֵשׁ דְּסַלְּקִין יָ\"הּ.</p>\n<p>אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, בְּרִיךְ אַנְתְּ לְאִמָּא עִלָּאָה. אֲבָל הַאי י\"ה שַׁוְיָא לִי (נ\"א לי\"ה) ה', בְּגִין מַטֵּה הָאֱלֹהִים, דְּאִיהוּ ו'. וְאָמַר וַדַּאי הָכִי הוּא. אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, בּוּצִינָא קַדִּישָׁא, לְאִתַּתְקְפָא מִלִּין דִּילָךְ, דְּמַרְאֶה אִיהִי לִימִינָא, חָשׁוּב בַּמַּרְאָה דְּאִתְּמַר בֵּיהּ (במדבר י״ב:ו׳) בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, וַתִּשְׁכַּח רמ\"ח, דְּסָלִיק בְּחֻשְׁבַּן אַבְרָהָם. אָמַר בּוּצִינָא קַדִּישָׁא, בְּקַדְמִיתָא אִתְחֲזֵי לָךְ הַאי חֵיזוּ, דְּאִתְּמַר בֵּיהּ בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וּלְבָתַר דְּאַמְרַת, (שמות ג׳:ג׳) אָסוּרָה נָּא וְאֶרְאֶה אֶת הַמַּרְאֶה הַגָּדוֹל הַזֶּה. דְּאַדְכִּיר בֵּיהּ ה' זִמְנִין הַסְּנֶה. כְּעַן אִתְגַּלְיָיא לָךְ חֵיזוּ דָּא, ברמ\"ח פִּקּוּדִין אִלֵּין, דְּאִינּוּן בַּחֲמִשָּׁה חוּמָשֵׁי תּוֹרָה. קָם רַעְיָא מְהֵימְנָא, וְנָשִׁיק לֵיהּ, וּבָרִיךְ לֵיהּ.</p>\n<p>אָמַר לֵיהּ בּוּצִינָא קַדִּישָׁא, הַאי מַרְאֶה, לְזִמְנִין אִיהוּ בְּאוֹת ה' הַמַּרְאֶה הַגָּדוֹל. וּלְזִמְנִין אִיהוּ בְּאוֹת ב', בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וּלְזִמְנִין במ\"ם, (יחזקאל א׳:כ״ז) מִמַּרְאֶה מָתְנָיו וּלְמַטָּה. וּלְזִמְנִין בכ' (שם) כְּמַרְאֵה אָדָם עָלָיו. וּלְזִמְנִין בו', (שמות כ״ד:י״ז) וּמַרְאֶה כְּבוֹד יְיָ'. וּלְזִמְנִין לְמַרְאֵה. לָא הֲוָה לֵיהּ לְמֶהֱוֵי תּוֹסֶפֶת אָת כְּלַל, בַּר ב' מִן בַּמַּרְאָה. אֶלָּא וַדַּאי, הַאי מַרְאֶה כְּלִילָא אִיהִי מֵעֶשֶׂר סְפִירָן, וְכָל אָת אַחְזֵי סְפִירָה דִּילָהּ, כְּגוֹן כְּמַרְאֵה בְּאָת כ', אַחְזֵי עַל כֶּתֶר, וְהָכִי שְׁאַר אַתְוָון, כָּל חַד אַחְזֵי עַל סְפִירָה דִּילָהּ. וְלָא צָרִיךְ לְאַרְכָא הָכָא, וּלְחַכִּימָא בִּרְמִיזָא.</p>\n<p>וְכַמָּה חֶזְיוֹנוֹת אִית לָהּ, וְדִמְיוֹנוֹת וּמַרְאוֹת אִית לָהּ, וְכֹלָּא אִשְׁתְּמוֹדַע בְּעֵין הַשֵּׂכֶל דְּלִבָּא, דְּאִתְּמַר בָּהּ הַלֵּב יוֹדֵעַ הַלֵּב מֵבִין. וּמַה דְּאָמַר, (הושע י״ב:י״א) וּבְיַד הַנְּבִיאִים אֲדַמֶּה. דִּמְיוֹן לָאו אִיהוּ, אֶלָּא בְּשֵׂכֶל דְּלִבָּא, וְלָאו כְּדִמְיוֹן דְּעֵינָא. הֲדָא הוּא דִּכְתִּיב, (ישעיהו מ׳:כ״ה) וְאֶל מִי תְּדַמְּיוּנִי וְאֶשְׁוֶה. (ישעיהו מ׳:כ״ה) וְאֶל מִי תְּדַמְּיוּן אֵל. וְאִית חֶזְיוֹנוֹת כְּגוֹן הַחוֹזִים בַּכּוֹכָבִים, אֲבָל חֶזְיוֹן דִּנְבוּאָה אִיהוּ כְּחֶזְיוֹן לַיְלָה.</p>\n<p>דִּמְיוֹנוֹת וְחֶזְיוֹנוֹת, כְּגוֹן הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר, וְהַמְּדַמֶּה דָּבָר לְדַבֵּר. אֲבָל מַרְאֶה דְּאִיהִי בְּעֵין הַשֵּׂכֶל, אִיהִי כְּאוֹר דְּנָהִיר בְּבַת עֵינָא. דְּבַת עֵינָא אִיהִי אוּכָּמָא. שְׁחוֹרָה אֲנִי וְנָאוָה, אוֹר דְּנָהִיר בָּהּ הַהוּא חִוָּורוּ דִּלְגוֹ. וְהַאי בַּת עֵינָא, אִיהִי (משלי ו׳:כ״ג) נֵר מִצְוָה. נְהוֹרָא דְּנָהִיר בָּהּ מִלְּגוֹ, וְתוֹרָה אוֹר.</p>\n<p>אָמַר בּוּצִינָא קַדִּישָׁא הַיְינוּ מַאי דַּאֲמֵינָא דִּכְעָן בְּאוֹרַיְיתָא אִתְגַּלְיָא לָךְ קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְהַאי אִיהוּ יְהוָֹ\"ה, בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. בַּמַּרְאָה, אִימָּא עִלָּאָה. אִתְיְדַע, לָךְ בְּדַעַת. בֵּן יָ\"הּ. בַּחֲלוֹם אֲדַבֶּר בּוֹ, הֵ\"א בַּתְרָאָה.</p>\n<p>חֶלְמָא, בִּסְתִימוּ דְּעַיְינִין. וּבְגִין דָּא אִתְקְרִיאַת אַסְפַּקְלַרְיָאה שְׁאֵינָה מְאִירָה. נְבוּאָה אִיהִי מַרְאֶה בִּפְתִּיחוּ דְּעַיְינִין. וּשְׁלֹשָׁה גַּוְונִין בְּעֵינָא, לָקֳבֵל תְּלַת אֲבָהָן. דִּבְהוֹן נְהִירָא בַּת יְחִידָאָה, תְּרֵין כַּנְפֵי עֵינָא, נֶצַח וְהוֹד. מַרְאֶה לָא אִתְחַזְיָא אֶלָּא בְּהוֹן, כַּד אִינּוּן פְּתִחִין, אִיהִי מַרְאֶה בְּהָקִיץ. וְכַד אִינּוּן סְגִירִין, אִיהוּ מַרְאֶה בַּחֲלוֹם.</p>\n<p>אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, בְּרִיךְ אַנְתְּ לְקוּדְשָׁא בְּרִיךְ הוּא, קוּם אַשְׁלִים פִּקּוּדִין, לְאַנְהֲרָא מַרְאֶה עִלָּאָה בְּהוֹן, לְקוּדְשָׁא בְּרִיךְ הוּא. אָמַר לֵיהּ בּוּצִינָא קַדִּישָׁא, י', אִיהִי בַּת עֵינָא, כִּי נֵר מִצְוָה וְתוֹרָה אוֹר ה\"ו מַנְהִיר בָּהּ ה', ג' גַּוְונִין דְּעֵינָא, וּתְרֵין כַּנְפֵי עֵינָא. חָמֵשׁ אוֹר נְהִרִין בָּהּ מִלְּגָאו, ה' עִלָּאָה דְּאִיהִי אוֹר הַמַּרְאֶה. (אורה מראה) ע\"כ (פרשת צו, כ\"ז ע\"א פקודא לעשות העולה)</p>"],[9520012700,"<p>(דברים כ״ה:ג׳) אַרְבָּעִים יַכֶּנוּ לֹא יוֹסִיף וְגוֹ', פִּקּוּדָא דָּא לְהַלְקוֹת לְרָשָׁע, דְּאִיהוּ סָמָאֵל, דְּעָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְמַחֲאָה לֵיהּ חַמְשִׁין מָחָאן. בְּגִין דְּעָבַד גַּרְמֵיהּ אֱלוֹהַּ. יֵיתֵי יִחוּדָא, דִּמְיַיחֲדָן בֵּיהּ יִשְׂרָאֵל בְּכָל יוֹמָא, בְּכ\"ה אַתְוָון, וְיִמְחֵי בְּהוֹן, לְמַאן דְּשַׁוֵּי גַּרְמֵיהּ אֱלוֹהַּ, וְלָאו אִיהוּ אֶלָּא עֶבֶד מְטוּנָּף. וְאִלֵּין דְּסָרְחוּ בְּה' תַּקִּין לוֹן קוּדְשָׁא בְּרִיךְ הוּא, (למחאה) בְּיוֹ\"ד הֵ\"א וָא\"ו, דְּאִינּוּן אַרְבָּעִים חָסֵר חַד. וּבְהַאי שְׁמָא, מָחָא קוּדְשָׁא בְּרִיךְ הוּא עַשְׂרָה מַכְתְּשִׁין לְאָדָם. וְעַשְׂרָה לְחַוָּה. וְעַשְׂרָה לְנָחָשׁ. וְתִשְׁעָה לְאַרְעָא. בְּגִין דְּכֻלְּהוּ סָרְחוּ בְּאָת ה'. וּבְגִין דָּא, (בראשית ג׳:י״ד) כִּי עָשִׂיתָ זֹאת. (ע\"כ)</p>"],[9520012701,"<p>(דברים כ״ה:ה׳) כִּי יֵשְׁבוּ אַחִים יַחְדָּו וּמֵת אַחַד מֵהֶם וּבֶן אֵין לוֹ וְגוֹ', יְבָמָה יָבֹא עָלֵיהּ וּלְקָחָהּ לוֹ לְאִשָּׁה וְיִבְּמָהּ. פִּקּוּדָא דָּא, לְיַבֵּם אֵשֶׁת אָח דְּאֵשֶׁת אָח אִיהִי ד', וְעִם א\"ח אִיהִי אֶחָד. וְאִם חַס וְשָׁלוֹם לִבֵּיהּ לָאו אִיהוּ, לְמַיְיתֵי אָח עַל ד', דְּאִיהִי אִתְּתֵיהּ בַּת זוּגֵיהּ דא\"ח, עָבִיד פִּרוּדָא, וְעָאל סָמָאֵל אֵל אַחֵר בְּאֶמְצָעִיתָא, וְאִתְּמַר בֵּיהּ, (בראשית ל״ח:ט׳) וְשִׁחֵת אַרְצָה לְבִלְתִּי וְגוֹ', דְּאִסְתַּלָּק קוֹצָא דְּאָת ד' מִן אֶחָד. וּבְגִין דָּא, וְהָיָה אִם בָּא אֶל אֵשֶׁת אָחִיו וְשִׁחֵת אַרְצָה לְבִלְתִּי נְתָן זֶרַע לְאָחִיו. וְהַשְׁחָתַת זַרְעָא, מָנַע מִנֵּיהּ כַּמָה בִּרְכָאן, וּפִרוּדָא דְּיִיחוּדָא. וּבְגִין דָּא וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה' וַיְמִיתֵהוּ ה'.</p>\n<p>וְיִיחוּדָא דְּאָח עִם ד' בְּצַדִּיק. וּבֹעַז בְּגִין דְּאִתְתְּקַּף עַל יִצְרֵיהּ, אִקְרֵי צַדִּיק. וְהַאי אִיהוּ בּוֹעַ\"ז, בּ\"וֹ עֹ\"ז, תַּקִּיף בְּיִצְרֵיהּ. (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, וְדָא יה\"ו <Nonei></i> דִּכְלִילָן תְּלַת אַתְוָון (ס\"א אבהן) בְּצַדִּיק, לְיַבֵּם ה'.</p>\n<p>וּבִינָה בֶּן יָ\"הּ, בְּגִינָהּ אִתְּמַר, (רות ד׳:ז׳) וְזֹאת לַפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָה וְעַל הַתְּמוּרָה לְקַיֵּים כָּל דָּבָר. הָכָא קָא רָמִיז שִׁנוּי הַשֵּׁם, וְדָא מצפ\"ץ הָכָא, וְזֹאת לְפָנִים בְּיִשְׂרָאֵל. וְדָא שִׁנּוּי מָקוֹם, אֶהְיֶ\"ה, אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ. יה\"ו, אִיהוּ אֶהְיֶ\"ה, וְדָא שִׁנּוּי מָקוֹם. שִׁנּוּי מַעֲשֵׂה, אֲדֹנָ\"י, א' אֶדְיֶ\"ד, י' ידוד, תַּרְוַויְיהוּ מִשְׁתַּנִים בַּאֲדֹנָ\"י.</p>"],[9520012702,"<p>וְזֹאת הַתְּעוּדָה בְּיִשְׂרָאֵל, הַתְּעוּדָה, אִימָּא עִלָּאָה, (ישעיהו ח׳:ט״ז) צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמּוּדָי. אִיהוּ חוֹתָם דְּעָלְמָא, חוֹתָם דִּשְׁמַיָּא וְאַרְעָא. עַל הַתְּמוּרָה, שְׁכִינְתָּא תַּתָּאָה. בְּאָן אֲתָר אִתְטַמָּרַת. בְּעוּלֵימָא דִּילָהּ, מְטַטְרוֹ\"ן, וְיִשְׁנֶה תַּמָּן, אִיהִי מְשַׁנָּה. וְאָדָם דְּאִתְּמַר בֵּיהּ (ישעיהו מ״ד:י״ג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, (איוב י״ד:כ׳) מְשַׁנֶּה פָּנָיו וַתְּשַׁלְּחֵהוּ.</p>\n<p>וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, לֹא כְּשֶׁאֲנִי נִכְתָּב אֲנִי נִקְרָא בָּעוֹלָם הַזֶּה, נִכְתָּב ידוד, וְנִקְרָא אֲדֹנָ\"י. וְהָא כְּתִיב (מלאכי ג׳:ו׳) אֲנִי יְיָ' לֹא שָׁנִיתִי. בַּכְּתִיבָה לֹא אִשְׁתַּנֵּי, אֲבָל בַּקְּרִיאָה אִשְׁתַּנֵּי. דִּכְתִּיבָה דְּאִיהוּ אַתְרֵיהּ, לָא אִשְׁתַּנֵּי. בַּקְּרִיאָה דְּאִיהִי לְבַר מֵאַתְרֵיהּ, אִשְׁתַּנֵּי. (שמות כ״ג:כ״א) הִשָּׁמֶר מִפָּנָיו וּשְׁמַע בְּקוֹלוֹ אַל תַּמֵּר בּוֹ. בְּגִין דְּשִׁפְחָה דִּילֵיהּ אֲדֹנָ\"י, שְׁמָהּ כְּשֵׁם מַטְרוֹנִיתָא. וְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ אִשְׁתַּנֵּי, בְּגִין דְּאִיהוּ נַעַר. בֵּיהּ רָזָא (רוחא) (איוב ל״ג:כ״ה) יָשׁוּב לִימֵי עֲלוּמָיו.</p>\n<p>אֲבָל שְׁכִינְתָּא אֵצֶל קוּדְשָׁא בְּרִיךְ הוּא לָא מִשְׁתַּנֵּית, וְקוּדְשָׁא בְּרִיךְ הוּא לְגַבָּהּ לָא אִשְׁתַּנֵּי, הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ו׳) אֲנִי יְיָ' לֹא שָׁנִיתִי, אֲנִי, שְׁכִינְתָּא. יְיָ', עַמּוּדָא דְּאֶמְצָעִיתָא. שָׁלַף אִישׁ נַעֲלוֹ, דָּא סַנְדַּלְפוֹן, סַנְדָּל אִיהוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְנַעַל לְגַבֵּי שְׁכִינְתָּא. אֲבָל תִּפְאֶרֶת, דְּכָלִיל שִׁית סְפִירָן, אִיהוּ גּוּפָא לַיְדוָֹ\"ד. וּמַלְכוּת, גּוּפָא לִשְׁכִינְתָּא, דְּאִיהוּ אֲדֹנָי.</p>\n<p>(דברים כ״ה:ט׳) וְנִגְּשָׁה יְבִמְתּוֹ אֵלָיו לְעֵינֵי הַזְּקֵנִים וְחָלְצָה נַעֲלוֹ מֵעַל רַגְלוֹ וְגוֹ'. פִּקּוּדָא דָּא, לַחֲלוֹץ. וְהַאי אִיהוּ חֲלִיצַת רוּחָא מֵהַהוּא גּוּפָא, דְּבָעֵי לְאַנְהָגָא עִמֵּיהּ כְּאָח, וְהַהוּא קְשִׁירָא דְּאַחְוָה דְּעִם אָחוּהָ מַתִּיר מִנֵּיהּ, וְהַהוּא רוּחָא אָזִיל נָע וָנָד, עַד דְּאַשְׁכַּח פָּרוֹקָא. הֲדָא הוּא דִכְתִיב, (ויקרא כ״ה:מ״ט) אוֹ דוֹדוֹ אוֹ בֶן דוֹדוֹ יִגְאָלֶנּוּ אוֹ מִשְּׁאֵר בְּשָׂרוֹ וְגוֹ'. וְאִי לָא אַשְׁכַּח, וְהִשִּׂיגָה יָדוֹ וְנִגְאָל. כְּאוֹרֵחַ דְּאָזִיל מֵאֲתָר לַאֲתָר, אוֹ כְּעֶבֶד דְּאָזִיל בְּשַׁלְשֶׁלֶת עַל צַוָּארֵיהּ, עַד דְּאַשְׁכַּח פִּדְיוֹן מֵאָדוֹן דִּילֵיהּ עַל חוֹבֵיהּ. וַוי לְמַאן דְּלָא אֲנָח בֵּן לְמִפְרַק יָתֵיהּ.</p>\n<p>וְאֵלִיָּהוּ וְרַבָּנָן וּמָארֵי מְתִיבְתָאן, הָכָא רָמִיז, אֵין חָבוּשׁ מַתִּיר עַצְמוֹ מִבֵּית הָאֲסוּרִין. דְּאִיהוּ קָשׁוּר בְּקִשּׁוּרָא דִּתְפִלִּין דְּיָד, וְאָסוּר בִּתְפִלִין דְּרֵישָׁא, כַּד לֵית (ליה) בֵּן לְמִפְרַק לֵיהּ, מִסִּטְרָא דְּבֶן יָ\"הּ. בְּהַהוּא קְשִׁירוּ אִיהוּ אָח חָבוּשׁ וְאָסוּר, דְּלֵית לֵיהּ רְשׁוּ לְמִפְרַק יַת גַּרְמֵיהּ, דְּאִיהוּ ד' עַצְמוֹ דְּאָח, (בראשית ב׳:כ״ג) עֶצֶם מֵעֲצָמַי קָרָא לָּהּ לְגַבֵּיהּ, בְּקַרְקַפְתָּא דִּתְפִלִּין דְּרֵישָׁא. וּבָשָׂר מִבְּשָׂרִי קָרָא לָהּ מִסִּטְרָא דְּלִבָּא.</p>"],[9520012703,"<p>וְלָא לְמַגָנָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כָּל הָעוֹסֵק בַּתּוֹרָה וּבִגְמִילוּת חֲסָדִים וּמִתְפַּלֵּל עִם הַצִּבּוּר, מַעֲלֶה אֲנִי עָלָיו כְּאִלּוּ פְּדָאַנִי לִי וּלְבָנַי מִבֵּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְכַמָּה בְּנֵי נָשָׁא דְּקָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְעַבְדֵּי גְּמִילוּת חֲסָדִים, וּמְצַלִּין, וְלָא אִתְפְּרַק קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ וְיִשְׂרָאֵל. אֶלָּא דְּיִשְׁתְּדַּל בְּאוֹרַיְיתָא, לְחַבֵּר יָתָהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וּגְמִילוּת חֶסֶד, הָא אוֹקְמוּהָ, דְּהָא אֵין חָסִיד אֶלָּא הַמִּתְחַסֵּד עִם קוֹנוֹ, דְּכָל פִּקּוּדִין דְּעָבִיד, לְמִפְרַק בְּהוּ שְׁכִינְתֵּיהּ, וּבְהָא עָבִיד חֶסֶד עִם קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מַאן דְּגָמִיל חֶסֶד בִּשְׁכִינְתֵּיהּ, עִם קוּדְשָׁא בְּרִיךְ הוּא גָּמִיל. בְּגִין דְּכַד חָבוּ יִשְׂרָאֵל, וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בָּעֵי לְיַסְּרָא לוֹן, אִימָּא הֲוַת רְבִיעָא עָלַיְיהוּ, עַד דְּנַפְקוּ לְתַרְבּוּת רָעָה. קוּדְשָׁא בְּרִיךְ הוּא מַה עָבִיד. תָּרִיךְ בְּנֵי מַלְכָּא וּמַטְרוֹנִיתָא. וְאִיהוּ אוֹמֵי, דְּלָא יֶהְדַּר לְאַתְרֵיהּ, עַד דְּמַטְרוֹנִיתָא אִתְהַדְּרַת לְאַתְרָהָא. וּמַאן דְּהָדַר בִּתְשׁוּבָה, וְגָמִיל חֶסֶד בִּשְׁכִינְתָּא, וּבְכָל אוֹרַיְיתָא וּבְפִקּוּדִין דִּילָהּ, וְלָאו אִיהִי (איהו) אֶלָּא לְמִפְרַק שְׁכִינְתָּא, דָּא עָבִיד חֶסֶד עִם קוֹנוֹ, וּכְאִילּוּ פָּרִיק לֵיהּ וּלִשְׁכִינְתֵּיהּ וְלִבְנוֹי.</p>\n<p>אָמַר אֵלִיָּהוּ וְכָל רָאשֵׁי מְתִיבְתָאן, רַעְיָא מְהֵימָנָא, אַנְתְּ הוּא הַאי בַּר נָשׁ, אַנְתְּ הוּא בַּר מִן מַלְכָּא וּמַטְרוֹנִיתָא, דְּאִשְׁתַּדְּלוּתָא דִּילָךְ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, לָאו כְּמַאן דְּעָבִיד חֶסֶד עִם קוֹנוֹ, אֶלָּא כִּבְרָא דִּמְחוּיָּיב לְשַׁוּוּיֵיהּ גַּרְמֵיהּ וְתוּקְפֵּיהּ לְמִפְרַק אַבָּא וְאִימָּא, וּמָסַר גַּרְמֵיהּ לַמִּיתָה עָלַיְיהוּ. דְּמַאן דְּלָאו אִיהוּ בְּרָא דְּמַלְכָּא, וְעָבִיד טִיבוּ עִם מַלְכָּא וְעִם מַטְרוֹנִיתָא, וַדַּאי הַאי אִתְחֲשִׁיב דְּעָבִיד חֶסֶד עִם קוֹנוֹ.</p>\n<p>קָם רַעְיָא מְהֵימָנָא, וְאִשְׁתְּטַּח קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וּבָכָה, וְאָמַר כֵּן יְהֵא רַעֲוָא דִּילֵיהּ, דְּיַחֲשִׁיב לִי כְּבַר, דְּעוֹבָדִין דִּילִי לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ יְהוֹן לְגַבֵּיהּ כִּבְרָא דְּאִשְׁתְּדַּל בְּהוֹן בָּתַר אֲבוֹי וְאִמֵּיהּ, דְּרָחִים לוֹן יַתִיר מִגַּרְמֵיהּ וְנַפְשֵׁיהּ רוּחֵיהּ וְנִשְׁמָתֵיהּ, וְכָל מַה דְּהֲוָה לֵיהּ הֲוָה חָשִׁיב לוֹן לְאַיִן, <Nonei></i> לְמֶעְבַּד בְּהוֹן רְעוּתֵיהּ דְּאַבָּא וְאִמָּא, וּלְמִפְרַק לוֹן בְּהוֹן. וְאַף עַל גַּב דְּיָדַעְנָא דְּכֹלָּא בִּרְשׁוּתֵיהּ, רַחֲמָנָא לִבָּא בָּעֵי. בְּהַהוּא זִמְנָא אָתָא קוּדְשָׁא בְּרִיךְ הוּא וְנָשִׁיק לֵיהּ, וְאָמַר, רַעְיָא מְהֵימָנָא, וַדַאי אַנְתְּ הוּא בְּרָא דִּילִי, וְדִשְׁכִינְתָּא. רַבָּנָן וּמַלְאָכִין נַשְּׁקוּ בַּר קָמוּ כֻּלְּהוּ וְנַשְּׁקוּ לֵיהּ, וְקַבִּילוּ לֵיהּ לְרַב וּמַלְכָּא עָלַיְיהוּ.</p>"],[9520012704,"<p>(דברים כ״ה:י״ט) וְהָיָה בְּהָנִיחַ יְיָ' אֱלֹהֶיךָ וְגוֹ', תִּמְחֶה אֶת זֵכֶר עֲמָלֵק וְגוֹ'. פִּקּוּדָא דָּא, לְהַכְרִית זַרְעוֹ שֶׁל עֲמָלֵק. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אוֹמֵי, דְּלָא יַחֲזוֹר עַל כֻּרְסֵיהּ, עַד דְּיִטּוֹל נוּקְמָא מִנֵּיהּ. פָּתַח רַעְיָא מְהֵימָנָא וְאָמַר. וַדַּאי, בְּגִין דָּא הֲווֹ אַזְלֵי בְּמַדְבְּרָא וְעַל יַמָּא, וְלָא יֵיעֲלוּן בְּאַרְעָא דְּיִשְׂרָאֵל, עַד דְּיִטּוֹל נוּקְמָא מִנֵּיהּ דַּעֲמָלֵק.</p>\n<p>עֲמָלֵק מַאן הוּא לְעֵילָּא, דְּהָא חֲזֵינָן דְּבִלְעָם וּבָלָק מִתַּמָּן הֲווֹ נִשְׁמָתִין דִּלְהוֹן, וּבְגִין דָּא הֲווֹ שַׂנְאִין לְיִשְׂרָאֵל יַתִיר מִכָל אוּמָה וְלִישָׁן, וּבְגִין דָּא עֲמָלֵק רָשִׁים בִּשְׁמֵהוֹן, ע\"ם מִן בִּלְעָם, ל\"ק מִן בָּלָק, וּדְכָר וְנוּקְבָּא אִינּוּן עֲמָלֵקִים. וְעָלַיְיהוּ אִתְּמַר, (במדבר כ״ג:כ״א) לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל.</p>\n<p>כְּגַוְונָא דְּאִית בְּיִשְׂרָאֵל אַרְבַּע אַנְפִּין, יַעֲקֹב, יִשְׂרָאֵל, רָחֵל, לֵאָה. יִשְׂרָאֵל עִם לֵאָה, יַעֲקֹב עִם רָחֵל, לָקֳבֵל, (יחזקאל א׳:י׳) וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּם. הָכִי אִית אַרְבַּע אַנְפִּין לַעֲמָלֵק, קֶסֶם, וְנַחַשׁ, עָמָל, וָאָוֶן. עָמָל רָשִׁים בַּעֲמָלֵק. וְהָמָן דְּהֲוָה מִסִּטְרָא דַּעֲמָלֵק, (תהילים ז׳:י״ז) יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ. וְכָל אַלּוּפֵי עֵשָׂו מֵעֲמָלֵק הֲווֹ. וּלְעֵילָּא עֲמָלֵק, סָמָאֵל. עָמָל, נַחַשׁ, אָוֶן, וּמִרְמָה. דִּמְפַתֵּי לֵיהּ לְבַּר נָשׁ לְמֶחֱטֵי לְקוּדְשָׁא בְּרִיךְ הוּא. קֶסֶ\"ם, ק' מִן עֲמָלֵק ס\"ם מִן סָמָאֵ\"ל. נַחַ\"שׁ, אֵ\"ל מִסָּמָאֵל (כאן חסר)</p>"],[9520012705,"<p>עָלֵיהּ אִתְּמַר לְאַבְרָהָם, (בראשית י״ב:א׳) לֵךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ, בֵּית מוֹלָד דִּילָךְ, מֵאִלֵּין בָּתֵּי סִיהֲרָא, אוֹ בָּתֵּי שַׁבְּתַאי, אוֹ בָּתֵי מַאֲדִים. דְּבָתֵי מַאֲדִים וּבָתֵי שַׁבְּתַאי וּלְבָנָה, עָלַיְיהוּ אִתְּמַר, אֵין מַתְחִילִין בְּב\"ד (אין מתחילין בב' ואין מסיימין בד'). דְּמַאֲדִים סוּמָקוּ דְּחַמָּה, גֵּיהִנָּם, אִימָּא דְּעֵשָׂו, דְּאִתְיְילִידַת בְּיוֹמָא תִּנְיָינָא. וְסִיהֲרָא, אִיהוּ טוֹב וָרָע, טוֹב בְּמִילּוּאָהּ. וְרַע בְּחֶסְרוֹנָהּ.</p>\n<p>וּבְגִין דְּאִיהִי כְּלִילָא מִטּוֹב וָרָע, מוֹנִין בָּהּ יִשְׂרָאֵל וּמוֹנִין בָּהּ בְּנֵי יִשְׁמָעֵאל. וְכַד לָקַת בְּמִלּוּאָה, סִימָנָא לָא טַב לְיִשְׂרָאֵל. וְכַד לָקַת בְּחֶסְרוֹנָהּ, סִימַן רָע לַיִשְׁמְעֵאלִים. וּבְהַאי (ישעיהו כ״ט:י״ד) וְאָבְדָה חָכְמַת חֲכָמָיו, חָכְמָה דְּיִשְׁמְעֵאלִים, וּבִינַת נְבוֹנִים תִּסְתַּתָּר, דְּאִינּוּן לָא יַדְעִין בִּבְרִיאָתָן, אֶלָּא בְּשִׁמוּשָׁא דִּילְהוֹן, כְּפִי שִׁנּוּי עָלְמָא בַּהֲלִיכָתָן וְשִׁימּוּשָׁן. וְסִיהֲרָא אִתְבְּרִיאַת בְּיוֹמָא רְבִיעָאָה, וּבְחֶסְרוֹנָה דִּילָהּ עֲנִיּוּת, אִתְבְּרִיאַת לִילִית, שַׁבְּתַאי, דְּאִיהוּ רָעָב וְצִמָאוֹן וְלָקוּתָא דִּנְהוֹרִין. עָלָהּ אִתְּמַר, יְהִי מְאֹרֹת חָסֵר. (משלי ג׳:ל״ג) מְאֵרַת יְיָ' בְּבֵית רָשָׁע. (קהלת ז׳:כ״ו) וְחוֹטֵא יִלָּכֶד בָּהּ, בְּבֵית הַסֹּהַר דִּילָהּ, וְצַדִיק יִמָּלֵט מִמֶּנָּה.</p>\n<p>וְאִית כֹּכָבָא אַחֲרָא, נְקוּדָּה זְעֵירָא, נָקוּד עַל שִׁפְחָה (נ\"א סיהרא) דְּאִיהוּ מְאֹרֹת, וְדָא חוֹלָם, בַּת מֶלֶךְ, שַׁבָּת מַלְכְּתָא. דְּשֻׁלְטָנוּתָא דְּתַרְוַויְיהוּ בְּיוֹם שְׁבִיעִי, דְּאִתְּמַר בֵּיהּ, (דברים ה׳:י״ד) לְמַעַן יָנוּח עַבְדְּךָ וַאֲמָתְךָ. דְּסֵדֶר בְּרִיאָתָן לָאו כְּסֵדֶר שִׁמּוּשָׁן. וּבְגִין דָּא חַמָּ\"ה וּמַ\"אֲדִים סוּמָקֵי דְּגֵיהִנָּם, אִתְבְּרִיאוּ בְּיוֹמָא תִּנְיָינָא. לְבָנָה שַׁבְּתַאי, אִתְבְּרִיאוּ בְּיוֹמָא רְבִיעָאָה, כַּפְנָא וַחֲשׁוֹכָא. וּבְגִין דָּא אֵין מַתְחִילִין בְּב\"ד, בְּגִין דְּגֵיהִנָּם אִתְבְּרֵי בְּיוֹמָא תִּנְיָינָא, וְלָקוּתָא דִּנְהוֹרִין בְּיוֹמָא רְבִיעָאָה.</p>\n<p>כֹּכָ\"ב, עָלֵיהּ אִתְּמַר, (במדבר כ״ד:י״ז) דָּרַךְ כֹּכָב מִיַּעֲקֹב. דְּדַרְגֵּיהּ בְּיוֹמָא תְּלִיתָאָה. וּבֵיהּ (שמות י״ט:ט״ז) וַיְהִי בַיוֹם הַשְּׁלִישִׁי בִּהְיוֹת הַבֹּקֶר, דְּבֵיהּ נָחִית קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב אוֹרַיְיתָא לְיִשְׂרָאֵל, בַּת יְחִידָה, לְמֶהֱוֵי עִמֵּיהּ שַׁבָּת מַלְכְּתָא. דְּאִיהוּ יוֹם שְׁלִישִׁי, כָּלִיל תְּלַת עַנְפֵי אֲבָהָן, ש', בַּת (מלכתא) יְחִידָאָה, דְּשֻׁלְטָנוּתָא דִּילָהּ בְּלֵיל שַׁבָּת, בֵּיהּ אִתְעָבִידַת שַׁבָּת.</p>\n<p>וּבְגִין דָּא חוֹלְקִין מָארֵי מַתְנִיתִין עַל מַתַּן תּוֹרָה, בַּת יְחִידָה. דָּא אָמַר, בַּשְּׁלִישִׁי נִתְּנָה תּוֹרָה. וְדָא אָמַר, בַּשְּׁבִיעִי נִתְּנָה תּוֹרָה. וְאִיהִי בַּת יְחִידָה, דַּאֲחִידַת בְּעַמּוּדָא דְּאֶמְצָעִיתָא, תְּלִיתָאָה לַאֲבָהָן. וּבְצַדִּיק, שְׁבִיעִית לֵיהּ בַּת יְחִידָאָה. וְכַד אִיהִי עֲטָרָה עַל רֵישֵׁיהּ, אִתְקְרֵי בֵּיהּ שְׁבִיעִי, דְּהוּא שִׁשִּׁי הֲוָה, דְּכֹכָב דִּילֵיהּ צֶדֶק, וּבַת יְחִידָה שַׁבָּת מַלְכְּתָא אִתְקְרֵי צֶדֶק. וּבְגִין דָּא, תּוֹרָה אֲחִידָא בֵּין יוֹם ג' וְז'.</p>\n<p>וְאִיהוּ כ\"ב מִן כּוֹכָ\"ב, כ\"ו (תהילים פ״ד:י״ב) כִּי שֶׁמֶשׁ וּמָגֵן יְדוָֹ\"ד צְבָאוֹת, שְׁכִינְתָּא מַלְכוּת הַקֹּדֶשׁ, (בראשית מ״ח:כ׳) בְּךָ יְבָרֵךְ יִשְׂרָאֵל, כ\"ב אַתְוָון דְּאוֹרַיְיתָא. כּוֹכָב, כְּלִילָא מִתְּלַת דַּרְגִּין, כ', כֶּתֶר. ב' בִּינָה. יְדוָֹ\"ד כָּלִיל תַּרְוַויְיהוּ, חָכְמָה. וְכֹלָּא כָּלִיל כּוֹכָ\"ב, דַּרְגָּא דְּעַמּוּדָא דְּאֶמְצָעִיתָא.</p>"],[9520012706,"<p>וּשְׁכִינְתָּא אִיהִי לְבָנָה, לִבּוּן הַהֲלָכָה, רַחֲמֵי, בְּסִטְרָא דְּחֶסֶד. וְאִתְקְרִיאַת חַמָּה, בָּרָה כַּחַמָּה, מִסִּטְרָא דִּגְבוּרָה, פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. סִיהֲרָא אֲפֵילָה, מִעוּט דְּסִיהֲרָא, שִׁפְחָה דִּילָהּ גֵּיהִנָּם, חַמָּה בִּישָׁא. שִׁפְחָה דִּילֵיהּ שַׁבְּתַאי, לָקוּתָא דִּנְהוֹרִין, חִילוּל שַׁבָּת. שִׁפְחָה, דְּאָהַדָרַת עוֹרֶף לִגְבִירְתָּהּ בְּכָל יוֹמָא <Nonei></i> וְיוֹמָא וְאִתְגַבְּרַת עָלָהּ בְּחוֹבִין דְּיִשְׂרָאֵל בְּנָהָא. הֲדָא הוּא דִכְתִיב, (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. דְּשׁוּלְטָנוּתָא דְּשִׁפְחָה, לָא הֲוֵי אֶלָּא בְּיוֹמָא תִּנְיָינָא, בַּגֵיהִנָּם. וּבָרְבִיעִי, בְּלָקוּתָא דִּנְהוֹרִין. וְאִתְהַדְּרַת לְשַׁלְּטָאָה בְּכָל יוֹמָא וְיוֹמָא.</p>\n<p>וּבַת מֶלֶךְ, אֲסִירָא בְּסִרְכוֹת, בְּבֵית הַסֹּהַר, בְּגָלוּתָא דִּילָהּ. וְאִיהִי קִינָּא דְּסָמָאֵל בֵּין כֹּכָבַיָּא. וְקוּדְשָׁא בְּרִיךְ הוּא אוֹמֵי, (עובדיה א׳:ד׳) אִם תַּגְבִּיהַ כַּנֶּשֶׁר וְאִם בֵּין כֹּכָבִים שִׂים קִנֶּךָ מִשָׁם אוֹרִידְךָ נְאֻם יְיָ'. וּשְׁכִינְתָּא נֹגַהּ, וְנֹגַהּ לָאֵשׁ, וּמֵהָכָא קָרוּ לְבֵי כְּנִשְׁתָּא אֵשׁ נוֹגַהּ.</p>\n<p>אֵשׁ מַאֲדִים לִישָׁנָא דְּאוֹדֶם, (שמות כ״ח:י״ז) טוּר אוֹדֶם פִטְדָה. נוֹגַהּ אֶשָּׁא חִיוָּרָא. וְתַרְוַויְיהוּ פְּנֵי חַמָּה וּפְנֵי סִיהֲרָא, נֶצַח וְהוֹד, אִינּוּן דְּנָטְלוּ חִוָּורוּ מֵחֶסֶד, וְסוּמָקוּ מִגְּבוּרָה. אַהֲרֹן וְדָוִד מִתַּמָּן הֲווֹ, חַד נָטִיל רַחֲמֵי, וְחַד נָטִיל דִּינָא, דָּוִד מִסִּטְרָא דִּשְׂמָאלָא, (שמואל א טז) וְהוּא אַדְמוֹנִי. אַהֲרֹן אִישׁ חֶסֶד, וְתַרְוַויְיהוּ נְבִיאֵי קְשׁוֹט מִתַּמָּן. פְּנֵי מֹשֶׁה הֲווֹ נְהִירִין בִּנְּבוּאָה דְּבִינָה, אִיהוּ חַמָּה (אימא) עִלָּאָה מִתַּמָּן נְבוּאָה דִּילֵיהּ.</p>\n<p>בְּהוֹן עֵשָׂו חַיָּיבָא עֶבֶד אֱדוֹם, וְנוּקְבָּא דִּילֵיהּ מַאֲדִים, אִיהִי שְׁפִיכוּת דָּמִים דְּיִשְׂרָאֵל, וְגַרְמָה דְּמַטְרוֹנִיתָא אִתְקַיָּים בָּהּ, (איכה א׳:י״ג) נְתָנַנִי יְיָ' בִּידֵי לֹא אוּכַל קוּם, (שם) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. הוֹד, דָּוָה אִתְהַדָר. דְּנֶצַח וְהוֹד לָקֳּבְלַיְיהוּ. יָכִין וּבוֹעַז. שְׁתֵיהֶן (שניהם) אֲשֶׁר הַבַּיִת נִשְׁעַן עֲלֵיהֶם. דְּבֵי כְּנִשְׁתָּא אִתְקְרִיאַת עַל שְׁמַיְיהוּ אֵשׁ נוֹגַהּ כַּדְּקָא אֲמֵינָא.</p>\n<p>וְשִׁפְחָה רָעָה אִיהִי קְבוּרָה, וּבָהּ אָסִירָא לִגְבִירְתָּא. וְאִיהִי שַׁבְּתַאי, קָרָה וִיבֵשָׁה, בִּקְבוּרְתָא דְּעַפְרָא, וְאִיהִי מָוֶת דַּעֲנִיּוּתָא דְּאוֹרַיְיתָא, וְאִיהִי קְבוּרַת עָנִי, מְכוּסֶּה בָּהּ בְּשֶׁבַע מִינֵי מָדוֹרוֹת, דְּאִיהִי כְּלִילָא מִשֶּׁבַע כֹּכָבַיָא, כְּמָה דְּשַׁבָּת מַלְכְּתָא כְּלִילָא מִשֶּׁבַע. וְאִינּוּן שֶׁבַע כֹּכָבַיָא מִסִּטְרָא דִּגְבוּרָה (ס\"א דגבירתא) (בראשית מ״א:נ״ג) שֶׁבַע שְׁנֵי הַשָּׂבָע, מִסִּטְרָא דְּשִׁפְחָה שֶׁבַע שְׁנֵי הָרָעָב. דְּעָלַיְיהוּ אָמַר נָבִיא (עמוס ח׳:י״א) לֹא רָעָב לַלֶּחֶם וְלֹא צָמָא לַמַּיִם כִּי אִם לִשְמוֹעַ אֶת דִּבְרֵי יְיָ'. (מכאן עד תיבת לא יטמא ליתא בדפוס וילנא ונראה דהוא השמטת הצנזור - מהמגיה מו\"ל.)</p>\n<p>גְּבִירְתָּהּ גַּן. שִׁפְחָה אַשְׁפָּה מְטוּנֶּפֶת, מִסִּטְרָא דְּעֵרֶב רַב אַשְׁפָּה מְעוּרֶבֶת בַּגַּן, לְגַדְּלָא זְרָעִים, מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע. מִסִּטְרָא דַּעֲבוֹדָה זָרָה, אִתְקְרִיאַת שַׁבְּתַאי, לִילִית, אַשְׁפָּה מְטוּנֶּפֶת, בְּגִין דְּצוֹאָה מְעוּרֶבֶת מִכָל מִינֵי טִנּוּף וְשֶׁרֶץ, דְּזַרְקִין בָּהּ כְּלָבִים מֵתִים וַחֲמוֹרִים מֵתִים. בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל קְבוּרִים בָּהּ. עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּאִינּוּן כְּלָבִים מֵתִים, קְבוּרִים בָּהּ. וְאִיהִי קֶבֶר דַּעֲבוֹדָה זָרָה, דְּקַבְרִין בָּהּ עֲרֵלִים, דְּאִינּוּן כְּלָבִים מֵתִים, שֶׁקֶץ וְרֵיחַ רָע, מְטוּנָּף, (מוסרח) מְסוּרַח, מִשִּׁפְחָה בִּישָׁא אִיהִי סִרְכָא, דַּאֲחִידָא בְּעֵרֶב רַב, מְעוּרָבִים בְּיִשְׂרָאֵל. וַאֲחִידַת בְּעֶצֶם וּבָשָׂר, דְּאִינּוּן בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל, עֶצֶם מֵת, וּבָשָׂר טָמֵא, בָּשָׂר בַּשָּׂדֶה טְרֵפָה, דְּעָלָהּ אִתְּמַר, (שמות כ״ב:ל׳) לַכֶּלֶב תַּשְׁלִיכוּן אוֹתוֹ.</p>\n<p>וּכְגַוְונָא דְּאִית תְּרֵיסָר מַזָּלוֹת, מִסִּטְרָא דְּטוֹב. הָכִי אִית תְּרֵיסַר מַזָּלוֹת, מִסִּטְרָא דְּרָע. הֲדָא הוּא דִּכְתִיב, (בראשית כ״ה:ט״ז) שְׁנֵים עָשָׂר נְשִׂיאִים לְאֻמֹּתָם. (קהלת ז׳:י״ד) דְּזֶה לְעְֵמַּת זֶה עָשָׂה הָאֱלֹהִים, וְרַשִׁיעַיָּיא אִינּוּן אֲבִי אֲבוֹת הַטּוּמְאָה, דְּאִינּוּן טְמֵא מֵת וְשֶׁרֶץ, דִּמְטַמֵּא לְבַּר נָשׁ מֵאֲוִירוֹ וּמִתּוֹכוֹ וּמִגַּבּוֹ. וַאֲפִילּוּ תּוֹךְ תּוֹכוֹ דְּכַהֲנָא מִסְתְּאַב בְּהוֹן. וּבְגִין דָּא (ויקרא כ״א:י״א) עַל כָּל נַפְשׁוֹת מֵת לֹא יָבֹא. דְּרָשָׁע קָרוּי מֵת. וּבוּצִינָא קַדִּישָׁא, לְאָבִיו וּלְאִמּוֹ לֹא יִטַּמָּא. (ע\"כ).</p>"],[9520012707,"<p>הָכָא אַשְׁכַּחְנָא אַסְוָותָא לְגַבִּי, דְּאִתְּמַר בִּי (ישעיהו נ״ג:ט׳) וְיִּתֵּן אֶת רְשָׁעִים קִבְרוֹ. בָּתַר דִּקְבוּרָה דָּא בְּגִין אַבָּא וְאִימָּא, דְּאִינּוּן בְּגָלוּתָא עִם יִשְׂרָאֵל, אִתְקַיָּים בִּי קְרָא וְלֹא יִטַּמָּא. אֵלִיָּהוּ, לָא תִּתְעַכֵּב מִלְּנַחְתָּא, דְּאַף עַל גַּב דְּאַנְתְּ כַּהֲנָא, לְאָבִיו וּלְאִמּוֹ (לא) יִטַּמָא. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּגָלוּתָא, דְּאִיהִי קְבוּרָה לוֹן, וַאֲנָא קָבוּר בֵּינַיְיהוּ. בְּאוֹמָאָה עֲלָךְ, בְּשֵׁם יְיָ' חַי וְקַיָּים, לָא תִּתְעַכֵּב מִלְּנַחְתָּא. מַלְאֲכִין קַדִּישִׁין, מָארֵי דְּגַדְפִין, בְּאוֹמָאָה עָלַיְיכוּ, טוֹלוּ אוֹמָאָה דָּא, וּסְלִיקוּ לָהּ עַל גַּדְפַיְיכוּ. שְׁבוּעַת יְיָ' בְּחַ\"י צַדִיק וְקַיָּים עַמּוּדָא דְּאֶמְצָעִיתָא. טוֹלוּ אוֹמָאָה דָּא, וּסְלִיקוּ לָהּ עַל גַּדְפַיְיכוּ. בְּמַטְרוֹנִיתָא בִּיקָרָא דִּילָהּ, לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מַלְאֲכִין עִלָּאִין, שְׁלִיחָן דְּקוּדְשָׁא בְּרִיךְ הוּא מִימִינָא. וּמַלְאָכִין שְׁלִיחָן דִּילֵיהּ, מִשְּׂמָאלָא. וּמַלְאָכִים דְּאַבָּא וְאִמָּא, יֵהוֹן סָתְרִין (סחרין) לָהּ עֵילָּא וְתַתָּא, וּמְכַסִּין לָהּ בְּאָת ו', בְּשִׁית גַּדְפִין דִּילֵיהּ. דְּאִתְּמַר בֵּיהּ (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם וְגוֹ' בִּשְׁתַּיִם יְכַסֶּה פָּנָיו דִּשְׁבוּעָה דִּילֵיהּ, דְּאִיהִי ה', רְבִיעָאָה. וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו דִּילָהּ, וּבִשְׁתַּיִם מְעוֹפְפִים לָהּ.</p>\n<p>וְאַנְתְּ אֵלִיָּהוּ, דִּסְלִיקַת לְעֵילָּא, לְעִילַּת הָעִילּוֹת, וְהוּא טָעִין לָךְ מִכָּל טוּב, נָחִית לְגַבָּהּ, וְתֶהֱוֵי כְּרוּב תְּחוֹתָא, לְנַחְתָּא לָהּ מְלֵאָה כָּל טוּב. וּמַלְאָכִין דְּאַבָּא וְאִימָּא, דְּאִינּוּן יָ\"הּ, (ס\"א אסתרו לה) אַסְחֲרוּ לָךְ, בִּנְחִיתוּ דִּילָהּ. וּמַלְאָכִין דְּבַעְלָהּ, בְּרָא דְּאַבָּא וְאִמָּא, ו', כַּסִּיאוּ לָהּ, וּמְעַפְפִין לָהּ, מִשִׁית גַּדְפִין <Nonei></i> אב\"ג ית\"ץ, וְבְּל\"ו דְּתַלְיָין מִנַּיְיהוּ כְּחֶשְׁבוֹן ל\"ו. וַדָאי אִיהוּ שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ. וּנְחִיתַת ה' (נ\"א י\"ה) דִּילֵיהּ, טְמִירָא מְכוּסָּה בְּהוֹן. וּמַלְאָכִין דְּאִינּוּן דְּצַדִּיק חַ\"י עָלְמִין, אַסְמִיכוּ לָהּ עָלַיְיכוּ כְּחֵיוָן דְּסַמְכִי לְכֻרְסְיָיא.</p>\n<p>דְּאַף עַל גַּב דְּהֵ\"א דַּאֲצִילוּת, דִּשְׁמָא דִּיְדוָֹ\"ד, אִיהִי סְמִיכַת לְכֻלְּהוּ, לֵית לְכוֹן לְפָרְחָא לְעֵילָּא, וּלְנַחְתָּא לְתַתָּא, בַּר מִינָהּ. כְּאֵבָרִין דְּגוּפָא, דְּלֵית לְהוֹן תְּנוּעָה בַּר מִנִּשְׁמָתָא, דְּאֵבָרִין דְּאִית לָהּ, אִתְפְּשָּׁטוּ עָלַיְיכוּ, לְסַמְכָא לְכוֹן בְּהוֹן. דְּהָכִי אִיהִי ה', כְּיַמָּא, אִי אִית לָהּ מָאנִין, מִתְמַלְּיָין מִנָהּ, וּמִתְפַּשְּׁטִין בְּהוֹן, כַּנְּחָלִים דְּמִתְפַּשְּׁטִן מִן יַמָּא עַל אַרְעָא. וְאִי לָאו, אִיהִי ה' בְּגַרְמָא יְחִידָאָה, בְּלָא אִתְפַּשְּׁטוּתָא דְּנַחֲלִין.</p>\n<p>הָכִי מָאנִין דִּשְׁכִינְתָּא, אִינּוּן מַלְאֲכִין קַדִישִׁין לְעֵילָּא, וְיִשְׂרָאֵל לְתַתָּא, אִי אִית בְּהוֹן מָארֵי מִדוֹת, מָארֵי חֶסֶד חֲסִידִים, גִּבּוֹרִים מָארֵי תּוֹרָה, נְּבִיאִים וּכְתוּבִים, צַדִּיקִים, אַנְשֵׁי מַלְכוּת, דְּאִתְּמַר בְּהוּ (דניאל א׳:ד׳) וַאֲשֶׁר כֹּחַ בָּהֶם לַעֲמוֹד בְּהֵיכַל הַמֶּלֶךְ, בַּעֲמִידָה דִּצְלוֹתָא. בְּהֵיכָלָא דְּמַלְכָּא אֲדֹנָ\"י, מַלְכָּא דִּילָהּ יְדוָֹ\"ד. וְהֵם חֲכָמִים וּנְבוֹנִים רָאשֵׁי יִשְׂרָאֵל. וְלָא רָאשֵׁי עֵרֶב רַב, דְּאִתְּמַר בְּהוֹן, (איכה א׳:ה׳) הָיוּ צָרֶיהָ לְרֹאשׁ. אִיהִי אִתְפַּשְּׁטַת עָלַיְיהוּ בְּעֶשֶׂר סְפִירָן דִּילָהּ. בְּהַהוּא זִמְנָא, נָחִית עִלַּת הָעִלּוֹת, בְּיוֹד הֵ\"א וָא\"ו הֵ\"א, לְנַחְתָּא עָלַיְיהוּ, לְאָקָמָא שְׁכִינְתָּא עָלַיְיהוּ.</p>\n<p>וּבְזִמְנָא (שמות ב׳:י״ב) דְּוַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ, אִיהִי אַמְרַת, (שיר השירים א׳:ז׳) שַׁלָּמָה אֶהְיֶה כְּעוֹטְיָה, מְעוּטֶּפֶת בְּגַרְמָא דְּלָא אִתְפַּשְּׁטַת עָלַיְיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא צָוַוח עָלֵהּ וְאָמַר, (איכה א׳:א׳) אֵיכָה יָשְׁבָה בָדָד.</p>\n<p>אַדְּהָכִי, קָם בּוּצִינָא קַדִישָׁא וְאָמַר, רִבּוֹן עָלְמָא, הָא הָכָא רַעְיָא מְהֵימָנָא. דְּאִתְּמַר בֵּיהּ (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד, עַד כְּעַן וַיַּרְא כִּי אֵין אִישׁ. הָא הָכָא וְהָאִישׁ מֹשֶׁה, דְּשָׁקִיל לְשִׁתִּין רִבּוֹא דְּיִשְׂרָאֵל. וּבֵיהּ (תהילים ל״ג:י״ד) מִמְכוֹן שִׁבְתּוֹ הִשְׁגִיחַ. דְּבֵיהּ אִתְּמַר לְגַבֵּי דָּרָא דְּגָלוּתָא בַּתְרָאָה, (ישעיהו נ״ג:ו׳) וַיְיָ' הִפְגִּיעַ בּוֹ אֵת עֲוֹן כֻּלָּנוּ. וְאִיהוּ כָּלִיל בְּעֶשֶׂר מִדּוֹת, דִּבְגִּינַיְיהוּ אַמָרְת (בראשית י״ח:ל״ב) לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה. נְחִית עָלֵיהּ, לְאַשְׁגְּחָא עַל עָלְמָא, וְקַיֵּים מִילָּךְ, דְּאַנְתְּ קְשׁוֹט, וְכָל מִילָּךְ קְשׁוֹט.</p>\n<p>דְּאִיהוּ גָּמַל חֶסֶד עִם שְׁכִינְתָּא, וְקָטִיר שִׁפְחָה דִּילָהּ בִּגְבוּרָה, לְמֶהֱוֵי שִׁפְחָה אֲסִירָא תְּחוֹת גְּבִירְתָּהּ, בְּקִשּׁוּרָא דִּתְפִלִּין. וְאִשְׁתְּדַּל בְּגִינָהּ, בְּתוֹרַת אֱמֶת. (מלאכי ב׳:ו׳) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ. וְאִשְׁתְּדַּל בָּהּ, בַּנְּבִיאִים וּכְתוּבִים. בִּנְבִיאֵי, בְּכַמָּה נֶחָמוֹת. בַּכְּתוּבִים, בְּעֲשְׂרָה מִינֵי תְּהִלִּים. בְּצַדִּיק, בְּי\"ח בִּרְכָאן דִּצְלוֹתָא.</p>\n<p>וּמָארֵי מַתְנִיתִין, לָא אִשְׁתְּמוֹדְעָן לֵיהּ לְרַעְיָא מְהֵימָנָא. אֵלִיָּהוּ, בְּאוֹמָאָה עֲלָךְ בִּשְׁמָא דִּיְדוָֹ\"ד, וּבִשְׁמֵיהּ מְפֹרָשׁ, גַּלֵּי לֵיהּ לְכָל רֵישֵּׁי מָארֵי מַתְנִיתִין, דְּיִשְׁתְּמוֹדְעוּן לֵיהּ, וְלָא יִתְחַלֵּל יַתִּיר, דְּאִתְּמַר בֵּיהּ, (לגבי עלמא) (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ. לֵית לָךְ צוֹרֶךְ לְמֵיטַל רְשׁוּ דְּהָא אֲנָא שְׁלִיחָא דְּמָארֵי עָלְמָא, וְיָדַעְנָא דְּאִי אַנְתְּ עָבִיד דָּא, דְּיוֹדֵי לָךְ קוּדְשָׁא בְּרִיךְ הוּא עָלֵיהּ, וְיִסְתַּלְּקוּן בְּנָךְ בְּגִינֵיהּ, עֵילָּא וְתַתָּא. וְלָא תִּתְעַכָּב לְמֶעְבַּד, לָא שָׁבוּעַ וְלָא חֹדֶשׁ וְלָא שָׁנָה, אֶלָּא מִיַּד. (כאן חסר)</p>"],[9520012708,"<p>רַעִִיָא מְהֵימָנָא, מָאנֵי דְּפִסְחָא, בְּזִמְנָא דְּשָׁלִיט עָלַיְיהוּ לֵיל שִׁמּוּרִים, כֻּלְּהוּ צְרִיכִים לְמֶהֱוֵי שְׁמוּרִים, וּנְטוּרִים מֵחָמֵץ וּשְׂאוֹר בְּכָל שֶׁהוּא, וְכָל מַאֲכָלִים וּמַשְׁקִים (ס\"א מאני דפסחא) כֻּלְּהוּ נְטוּרִין. וּמַאן דְּנָטִיר לוֹן מֵחָמֵץ וּשְׂאוֹר. גּוּפֵיהּ, אִיהוּ נָטִיר מִיֵצֶר הָרָע לְתַתָּא, וְנִשְׁמְתַא (ונשמתיה) לְעֵילָּא. וְאִתְּמַר בֵּיהּ, (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. בְּגִין דְּהָא אִתְעָבִיד גּוּפֵיהּ קֹדֶשׁ, וְנִשְׁמָתֵיהּ קֹדֶשׁ קֳדָשִׁים. וְאִתְּמַר בְּיֵצֶר הָרָע (ויקרא כ״ב:י׳) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ, (במדבר א׳:נ״א) וְהַזָּר הַקָּרֵב יוּמָת.</p>\n<p>פֶּסַח, דְּרוֹעָא יְמִינָא דְּאַבְרָהָם, כֶּסֶף מְזוּקָּק. מַאן דְּעָרַב בֵּיהּ עוֹפֶרֶת, מְשַׁקֵּר לֵיהּ. הָכִי מַאן דְּעָרַב חָמֵץ אוֹ שְׂאוֹר כָּל שֶׁהוּא בְּמַּצָּה, כְּאִלּוּ מְשַׁקֵּר חוֹתָמָא (במוניטה) דְּמַלְכָּא. וְהָכִי מַאן דְּעָרַב בְּטִפָּה דִּילֵיהּ שׁוּם תַּעֲרוֹבֶת, כְּאִילּוּ מְשַׁקֵּר חוֹתָמָא דְּמַלְכָּא, דָּא בְּדָא תַּלְיָיא.</p>"],[9520012709,"<p>רֹאשׁ הַשָּׁנָה, דְּרוֹעָא שְׂמָאלָא דְּיִצְחָק. תַּמָּן דִּינֵי נְפָשׁוֹת, וַעֲקֵדָה דְּיִצְחָק תַּמָּן הֲוָה. דְּעָקִיד לֵיהּ אַבְרָהָם. קִשּׁוּרָא דִּתְפִלָּה דְּיָד, דּוּמְיָא דַּעֲקֵדָה דְּיִצְחָק. זַכָּאָה אִיהוּ בְּרָא דְּאִתְעֲקַד בַּאֲבוֹי, וְאִתְקָשַּׁר בֵּיהּ, לְמֶעְבַּד עוֹבָדוֹהִי, בְּאוֹרַיְיתָא וּבַמִּצְוָה. וְזַכָּאָה עֶבֶד דְּאִתְקְשַּׁר תְּחוֹת רַבֵּיהּ, לְמֶעְבַּד רְעוּתֵיהּ, אִיהוּ בַּאֲתָר דִּבְרָא דְּמַלְכָּא.</p>\n<p>מְטַטְרוֹ\"ן, זַכָּאָה אַנְתְּ, וְזַכָּאִין בְּנָךְ, דְּאִינּוּן קְשִׁירִין וַעֲקִידִין בִּתְפִלִּין תְּחוֹת רְשׁוּתָא דְּמָארָךְ. וּבְגִין דָּא, אַף עַל גַּב דְּאַנְתְּ עֶבֶד לְמָארָךְ, מַלְכָּא אַנְתְּ עַל כָּל מְמָנָן דִּשְׁאַר עַמִּין. מַלְכָּא עַל כָּל מַלְאָכִין. מַלְכָּא, דְּשֵׁדִים וְכָל מַשִׁרְיָיתֵיהּ, דַחֲלִין מִנָךְ. מַאן גָּרִים דָּא, בְּגִין דְּאַנְתְּ שְׁרַפְרָף לְמָארָךְ, וְאַנְתְּ מְשַׁמֵּשׁ לְמָארָךְ. שַׁדַּי דִּמְזוּזָה לְבַר, שׁוֹמֵר הַפֶתַח. יְדוָֹ\"ד דְּאִיהוּ מָארָךְ, מִלְּגָאו.</p>\n<p>וְהָכִי אִיהוּ כַּד קוּדְשָׁא בְּרִיךְ הוּא נָחִית לְשַׁלְּטָאָה עַל עֵץ הַדַּעַת טוֹב וָרָע, דְּאִיהוּ טוֹב מְטַטְרוֹ\"ן. רָע סָמָאֵל, שֵׁד, מַלְכָּא דְּשֵׁדִים. <Nonei></i> מְטַטְרוֹן מַלְאָךְ, מַלְכָּא דְּמַלְאָכִים. אֲבָל מִסִּטְרָא דְּאִילָנָא דְּחַיֵּי, שַׁדַּי אִיהוּ יְסוֹד. וּבְגִין דָּא לְמַטָּה, שְׁנַיִם, עֶבֶד וְרַבּוֹ, דְּלָאו אִינּוּן יִחוּדָא חֲדָא, וּלְמַעְלָה, אֶחָד. תִּפְאֶרֶת יְסוֹד, דְּגוּף וּבְרִית חַשְׁבֵינָן חַד, דְּאִיהִי עַמּוּדָא דְּאֶמְצָעִיתָא וְצַדִּיק.</p>\n<p>כְּגַוְונָא דִּתְפִלִּין דְּרֹאשׁ, דְּאִיהוּ בִּינָה עַל תִּפְאֶרֶת, מִסִּטְרָא דְּאִילָנָא דְּחַיֵּי דַּאֲצִילוּת, וּמַלְכוּת תְּפִלָּה דְּיָד. הָכִי לְתַתָּא בְּאִילָנָא דְּחַיֵּי דִּבְרִיאָה, מִסִּטְרָא דְּכֻרְסְיָיא עִלָּאָה, תְּפִלִּין דְּרֹאשׁ מְטַטְרוֹן. תְּפִלִין דְּיַד דִּילֵיהּ, כִּסֵּא תַּחְתּוֹן. וְהַאי אִיהוּ דְּאָמַר נָבִיא עָלֵיהּ, (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן.</p>"],[9520012710,"<p>אֲבָל מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע, בְּקִשּׁוּרָא דִּתְפִלִּין, אִתְקְשַּׁר יֵצֶר הָרָע תְּחוֹת יֵצֶר הַטּוֹב, כְּעַבְדָּא תְּחוֹת מָארֵיהּ, בְּקָלָא דְּאוֹרַיְיתָא, בְּקָלָא דִּצְלוֹתָא, בְּקוֹל דְּשׁוֹפָר. קָלָא אִיהוּ רוֹמַ\"ח לְגַבֵּיהּ. וְדָא קוֹל הַשּׁוֹפָר, קוֹל דְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ כָּלִיל אֶשָּׁא מַיָּא וְרוּחָא. דְּאִינּוּן תְּלַת אֲבָהָן, דִּבְהוֹן הי\"ו, ה' בְּאַבְרָהָם, י' בְּיִצְחָק, בְּכָל אֲתָר ה' דְּשָׁלִיט עַל י' דִּינָא הוּא, וְהַאי אִיהוּ ה\"י מִן אֱלֹהִים. וּבְגִין דָּא (תהילים מ״ז:ו׳) עָלָה אֱלֹהִים בִּתְרוּעָה. ו' מִן וֵאלֹהֵי יַעֲקֹב, וְדָא רוּחַ הַשּׁוֹפָר, שְׁכִינְתָּא מָנָא דְּכֻלְּהוּ תְּלַת, וְאִיהוּ ה' מִן הַשּׁוֹפָר.</p>\n<p>דְּאִינּוּן י' שׁוֹפָרוֹת, דְּאִינּוּן קשר\"ק קש\"ק קר\"ק, מִתְלַבְּשִׁין בְּהוֹן הֵ\"א יוֹ\"ד וָא\"ו הֵ\"א, דְּכָל אַתְוָון אִלֵּין (ס\"א אינון) דִּינִין לְסִטְרִין אַחֲרָנִין וּלְחַיָּיבַיָּא. כְּשַׁלְשְׁלָאִין וְרוּמְחִין וְסַיְיפִין. תְּרוּעָה שַׁלְשֶׁלֶת אִיהִי. וּתְרֵי תְּרוּעוֹת אִית בְּעַשְׂרָה שׁוֹפָרוֹת. וְאִינּוּן חַד. (חסר)</p>\n<p>דְּאִתְּמַר בָּהּ וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים (או על הביצים ואינון). יִשְׂרָאֵל מְצַפְצְפִין לָהּ בְּכַמָּה צִפְצוּפִין דִּצְלוֹתִין, וְאִיהִי לָא בַּעְיָא לְנַחְתָּא לְגַבַּיְיהוּ. יִשְׂרָאֵל מַה עָבְדִין. נָטְלִין אִימָּא דְּאִיהִי שְׁכִינְתָּא בַּהֲדַיְיהוּ, וְקַשְׁרִין לָהּ בְּקִשּׁוּרָא דִּתְפִלִּין. כַּד מָטָאן לִקְרִיאַת שְׁמַע, קָרָאן בְּנִין דִּילָהּ בְּשִׁית תֵּיבִין דְּיִיחוּדָא, דְּאִינּוּן (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, הָא קָא נַחְתִּין לְגַבֵּי אִמְּהוֹן, קַשְׁרִין לוֹן עִמָּהּ. וְהַאי אִיהִי (ויקרא כ״ג:ב׳) אֲשֶׁר תִּקְרְאוּ אוֹתָם, דְּאִיהוּ עוֹנָתָהּ, כְּמוֹ מוֹעֲדֵי.</p>"],[9520012711,"<p>הָכִי בְּגַוְונָא דָּא מַצָּה, בָּהּ מְזַמְּנִין לְשִׁבְעָה יוֹמִין דְּפֶסַח. מְזַמְּנִין לְשִׁבְעָה יוֹמִין דְּסֻכּוֹת, בְּשִׁבְעָה מִינֵי, דְּאִינּוּן לוּלָב, וְאֶתְרוֹג, וְג' הֲדַסִּים, וּב' בַּדֵי עֲרָבָה. (בשבועות) שְׁבוּעוֹת, קָרָאן לוֹן בְּאוֹרַיְיתָא. רֹאשׁ הַשָּׁנָה יוֹמָא דְּדִינָא, כָּל חַד בְּמִינֵיהּ.</p>\n<p>כָּל מַאן דְּקָרָא, כָּל דַּרְגָּא בְּמִינֵיהּ, יִתְקַיֵּים בֵּיהּ, (ישעיהו נ״ח:ט׳) אָז תִּקְרָא וַיְיָ' יַעֲנֶה. אָ\"ז, ז' יוֹמִין דְּסֻכּוֹת, וְחַג שְׁמִינִי עֲצֶרֶת. אָ\"ז, מַצָּה, וְז' יוֹמִין דְּפֶסַח. אָ\"ז, סוּכָּה, וְז' מִינִין דְּלוּלָב, דְּאִינּוּן שָׁלֹשׁ הֲדַסִּים, וּשְׁנֵי עֲרָבוֹת, לוּלָב, וְאֶתְרוֹג, וּכְלִילָן בְּד', הָא חַד סָרֵי, כְּחוּשְׁבַּן ה\"ו. וְצָרִיךְ לוֹמַר הַלֵּל עָלַיְיהוּ, הַלְלוּיָהּ, לְאַשְׁלְמָא שֵׁם יְדוָֹד.</p>\n<p>וְצָרִיךְ לְסַלְּקָא לָהּ בְּמַחֲשָׁבָה, בְּאַרְבַּע מִינִין, הֲדָא הוּא דִכְתִיב, (שיר השירים ז׳:ט׳) אָמַרְתִּי אֶעֱלֶה בְתָמָר. אֶעֱלֶ\"ה סִימַן: אֶתְרוֹ\"ג, עֲרָבָ\"ה, לוּלָ\"ב, הֲדָ\"ס. וּמַחֲשָׁבָה שְׁמָא מְפֹרָשׁ, אִשְׁתְלִים בָּהּ י\"ד, כְּגַוְונָא דְּי\"ד פִּרְקִין דִּיְדָא דִּימִינָא, דְּבֵיהּ צָרִיךְ לְנַטְלָא לוּלָב. הֲרֵי מַתַּן תּוֹרָה, שָׁבֻעוֹת, שִׁבְעָה בְּשִׁבְעָה י\"ד. בְּרֹאשׁ הַשָּׁנָה, י\"ד בְּקוֹל הַשּׁוֹפָר, וּבְעֶשֶׂר שׁוֹפָרוֹת, כִּדְאוֹקִימְנָא לְעֵילָּא.</p>\n<p>בַּפֶסַח, אִיהִי שְׁכִינְתָּא יָ\"ד הַגְּדוֹלָה, מִסִּטְרָא דְּחֶסֶד. בְּרֹאשׁ הַשָּׁנָה, אִיהִי יָ\"ד הַחֲזָקָה, מִסִּטְרָא דִּגְבוּרָה. בְּמַתַּן תּוֹרָה, יָ\"ד רָמָה, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וּתְלַת זִמְנִין י\"ד, מ\"ב. וּתְלַת אֲבָהָן דְּתַלְיָין מִנַּיְיהוּ, סַלְּקִין חֲמִשָּׁה וְאַרְבָּעִים, כְּחוּשְׁבַּן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. (קפ\"ז ע\"ב, פיקודא ליתן מחצית השקל)</p>"],[9520012712,"<p>וַיֵּלֶךְ מֹשֶׁה וַיְדַבֵּר אֶת הַדְּבָרִים הָאֵלֶּה אֶל כָּל יִשְׂרָאֵל. רִבִּי חִזְקִיָּה פָּתַח, (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם וְגוֹ', זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וּבְגִין דְּאִתְרְעֵי בְּהוּ, קָרָא לוֹן בְּנִין <Nonei></i> בּוּכְרִין קַדִישִׁין, אַחִין (כביכול), נָחַת לְדַיְּירָא עִמְּהוֹן. הֲדָא הוּא דִכְתִיב, (שמות כ״ה:ח׳) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וּבָעָא לְאַתְקְנָא לְהוּ כְּגַוְונָא דִּלְעֵילָּא, וְשָׁארִי עָלַיְיהוּ שִׁבְעָה עֲנָנֵי יְקָר, שְׁכִינְתֵּיהּ אַזְלָא קַמַּיְיהוּ, הֲדָא הוּא דִכְתִיב, (שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם.</p>\n<p>תְּלַת אַחִין קַדִישִׁין אַזְלִין בֵּינַיְיהוּ, וּמַאן אִינּוּן. מֹשֶׁה, אַהֲרֹן, וּמִרְיָם. וּבִזְכוּתֵהוֹן, יָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא, מַתְנָן עִלָּאִין (והא אתמר). כָּל יוֹמוֹי דְּאַהֲרֹן, לָא אַעְדוּ עֲנָנֵי יְקָר מִיִשְׂרָאֵל. וְהָא אוֹקְמוּהָ, (בגין) דְּאַהֲרֹן דְּרוֹעָא יְמִינָא דְּיִשְׂרָאֵל הֲוָה. וְהַיְינוּ דִּכְתִיב, (במדבר כ״א:א׳) וַיִּשְׁמָע הַכְּנַעֲנִי מֶלֶךְ עֲרָד וְגוֹ', כִּי בָּא יִשְׂרָאֵל דֶּרֶךְ הָאֲתָרִים וְגוֹ'. כְּבַּר נָשׁ דְּאָזִיל בְּלָא דְּרוֹעָא, וְסָמִיךְ גַּרְמֵיהּ לְכָל אֲתָר, וּכְדֵין וַיִּלָּחֶם בְּיִשְׂרָאֵל וַיִשְׁבְּ מִמֶּנוּ שֶׁבִי, בְּגִין דַּהֲווֹ בְּלָא דְּרוֹעָא יְמִינָא. (ועל דא אצטריכו ישראל למנדר נדר עליה הדא הוא דכתיב, (במדבר כ״א:ב׳) וידר ישראל נדר ליי' ויאמר אם נתן תתן וגו') תָּא חֲזֵי, אַהֲרֹן דְּרוֹעָא יְמִינָא דְּגוּפָא הֲוָה. וְעַל דָּא כְּתִיב, (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמַאן אִיהוּ. אַהֲרֹן.</p>\n<p>וַיֵּלֶךְ מֹשֶׁה, מַאי וַיֵּלֶךְ, לְאָן הָלַךְ. אֶלָּא וַיֵּלֶךְ, כְּגוּפָא בְּלָא דְּרוֹעָא. כְּמָה דְאַתְּ אָמֵר, (איכה א׳:ו׳) וַיֵּלְכוּ בְּלֹא כֹחַ לִפְנֵי רוֹדֵף. דְּהָא מִית אַהֲרֹן דְּרוֹעָא יְמִינָא, וּבָעָא לְאִסְתַּלְּקָא גּוּפָא. (כל יומוי דמשה שמשא נהיר בעלמא).</p>\n<p>כָּל יוֹמוֹי דְּמֹשֶׁה, אַכְלוּ יִשְׂרָאֵל לֶחֶם מִן הַשָּׁמַיִם. כֵּיוָן דְּאָתָא יְהוֹשֻׁעַ, מַה כְּתִיב (יהושע ה׳:י״א) וַיִּשְׁבּוֹת הַמָּן מִמָּחֳרָת וְגוֹ'. וַיֹּאכְלוּ מֵעֲבוּר הָאָרֶץ מִמָּחֳרָת הַפֶּסַח. מַה בֵּין הַאי לְהַאי. אֶלָּא דָּא מִלְעֵילָּא וְדָא לְּתַתָּא. (מכאן אוליפנא) כָּל זִמְנָא דְּמֹשֶׁה אִשְׁתְּכַח, גּוּפָא דְּשִׁמְשָׁא שַׁלִּיט, וְנָהִיר לְעָלְמָא. כֵּיוָן דְּאִסְתְּלַּק מֹשֶׁה, אִתְכְּנַשׁ גּוּפָא דְּשִׁמְשָׁא, וְנָפִיק גּוּפָא דְּסִיהֲרָא.</p>"]]});
